window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["judicial-interpretations|其他"] = {"renminjianchayuangongyisusongbananguize":[{"i":1,"n":"第一条","txt":"为了规范人民检察院履行公益诉讼检察职责，加强对国家利益和社会公共利益的保护，根据《中华人民共和国人民检察院组织法》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》等法律规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院办理公益诉讼案件的任务，是通过依法独立行使检察权，督促行政机关依法履行监督管理职责，支持适格主体依法行使公益诉权，维护国家利益和社会公共利益，维护社会公平正义，维护宪法和法律权威，促进国家治理体系和治理能力现代化。"},{"i":3,"n":"第三条","txt":"人民检察院办理公益诉讼案件，应当遵守宪法、法律和相关法规，秉持客观公正立场，遵循相关诉讼制度的基本原则和程序规定，坚持司法公开。"},{"i":4,"n":"第四条","txt":"人民检察院通过提出检察建议、提起诉讼和支持起诉等方式履行公益诉讼检察职责。"},{"i":5,"n":"第五条","txt":"人民检察院办理公益诉讼案件，由检察官、检察长、检察委员会在各自职权范围内对办案事项作出决定，并依照规定承担相应司法责任。"},{"i":6,"n":"第六条","txt":"人民检察院办理公益诉讼案件，根据案件情况，可以由一名检察官独任办理，也可以由两名以上检察官组成办案组办理。由检察官办案组办理的，检察长应当指定一名检察官担任主办检察官，组织、指挥办案组办理案件。"},{"i":7,"n":"第七条","txt":"负责公益诉讼检察的部门负责人对本部门的办案活动进行监督管理。需要报请检察长决定的事项，应当先由部门负责人审核。部门负责人可以主持召开检察官联席会议进行讨论，也可以直接报请检察长决定。"},{"i":8,"n":"第八条","txt":"检察长不同意检察官处理意见的，可以要求检察官复核，也可以直接作出决定，或者提请检察委员会讨论决定。"},{"i":9,"n":"第九条","txt":"人民检察院提起诉讼或者支持起诉的民事、行政公益诉讼案件，由负责民事、行政检察的部门或者办案组织分别履行诉讼监督的职责。"},{"i":10,"n":"第十条","txt":"最高人民检察院领导地方各级人民检察院和专门人民检察院的公益诉讼检察工作，上级人民检察院领导下级人民检察院的公益诉讼检察工作。"},{"i":11,"n":"第十一条","txt":"人民检察院办理公益诉讼案件，实行一体化工作机制，上级人民检察院根据办案需要，可以交办、提办、督办、领办案件。"},{"i":12,"n":"第十二条","txt":"人民检察院办理公益诉讼案件，依照规定接受人民监督员监督。"},{"i":13,"n":"第十三条","txt":"人民检察院办理行政公益诉讼案件，由行政机关对应的同级人民检察院立案管辖。"},{"i":14,"n":"第十四条","txt":"人民检察院办理民事公益诉讼案件，由违法行为发生地、损害结果地或者违法行为人住所地基层人民检察院立案管辖。"},{"i":15,"n":"第十五条","txt":"设区的市级以上人民检察院管辖本辖区内重大、复杂的案件。公益损害范围涉及两个以上行政区划的公益诉讼案件，可以由共同的上一级人民检察院管辖。"},{"i":16,"n":"第十六条","txt":"人民检察院立案管辖与人民法院诉讼管辖级别、地域不对应的，具有管辖权的人民检察院可以立案，需要提起诉讼的，应当将案件移送有管辖权人民法院对应的同级人民检察院。"},{"i":17,"n":"第十七条","txt":"上级人民检察院可以根据办案需要，将下级人民检察院管辖的公益诉讼案件指定本辖区内其他人民检察院办理。"},{"i":18,"n":"第十八条","txt":"上级人民检察院认为确有必要的，可以办理下级人民检察院管辖的案件，也可以将本院管辖的案件交下级人民检察院办理。"},{"i":19,"n":"第十九条","txt":"检察人员具有下列情形之一的，应当自行回避，当事人、诉讼代理人有权申请其回避："},{"i":20,"n":"第二十条","txt":"检察人员自行回避的，应当书面或者口头提出，并说明理由。口头提出的，应当记录在卷。"},{"i":21,"n":"第二十一条","txt":"当事人及其诉讼代理人申请回避的，应当书面或者口头提出，并说明理由。口头提出的，应当记录在卷。"},{"i":22,"n":"第二十二条","txt":"检察长的回避，由检察委员会讨论决定；检察人员和其他人员的回避，由检察长决定。检察委员会讨论检察长回避问题时，由副检察长主持。"},{"i":23,"n":"第二十三条","txt":"人民检察院对当事人提出的回避申请，应当在收到申请后三日内作出决定，并通知申请人。申请人对决定不服的，可以在接到决定时向原决定机关申请复议一次。人民检察院应当在三日内作出复议决定，并通知复议申请人。复议期间，被申请回避的人员不停止参与本案工作。"},{"i":24,"n":"第二十四条","txt":"公益诉讼案件线索的来源包括："},{"i":25,"n":"第二十五条","txt":"人民检察院对公益诉讼案件线索实行统一登记备案管理制度。重大案件线索应当向上一级人民检察院备案。"},{"i":26,"n":"第二十六条","txt":"人民检察院发现公益诉讼案件线索不属于本院管辖的，应当制作《移送案件线索通知书》，移送有管辖权的同级人民检察院，受移送的人民检察院应当受理。受移送的人民检察院认为不属于本院管辖的，应当报告上级人民检察院，不得自行退回原移送线索的人民检察院或者移送其他人民检察院。"},{"i":27,"n":"第二十七条","txt":"人民检察院应当对公益诉讼案件线索的真实性、可查性等进行评估，必要时可以进行初步调查，并形成《初步调查报告》。"},{"i":28,"n":"第二十八条","txt":"人民检察院经过评估，认为国家利益或者社会公共利益受到侵害，可能存在违法行为的，应当立案调查。"},{"i":29,"n":"第二十九条","txt":"对于国家利益或者社会公共利益受到严重侵害，人民检察院经初步调查仍难以确定不依法履行监督管理职责的行政机关或者违法行为人的，也可以立案调查。"},{"i":30,"n":"第三十条","txt":"检察官对案件线索进行评估后提出立案或者不立案意见的，应当制作《立案审批表》，经过初步调查的附《初步调查报告》，报请检察长决定后制作《立案决定书》或者《不立案决定书》。"},{"i":31,"n":"第三十一条","txt":"负责公益诉讼检察的部门在办理公益诉讼案件过程中，发现涉嫌犯罪或者职务违法、违纪线索的，应当依照规定移送本院相关检察业务部门或者其他有管辖权的主管机关。"},{"i":32,"n":"第三十二条","txt":"人民检察院办理公益诉讼案件，应当依法、客观、全面调查收集证据。"},{"i":33,"n":"第三十三条","txt":"人民检察院在调查前应当制定调查方案，确定调查思路、方法、步骤以及拟收集的证据清单等。"},{"i":34,"n":"第三十四条","txt":"人民检察院办理公益诉讼案件的证据包括书证、物证、视听资料、电子数据、证人证言、当事人陈述、鉴定意见、专家意见、勘验笔录等。"},{"i":35,"n":"第三十五条","txt":"人民检察院办理公益诉讼案件，可以采取以下方式开展调查和收集证据："},{"i":36,"n":"第三十六条","txt":"人民检察院开展调查和收集证据，应当由两名以上检察人员共同进行。检察官可以组织司法警察、检察技术人员参加，必要时可以指派或者聘请其他具有专门知识的人参与。根据案件实际情况，也可以商请相关单位协助进行。"},{"i":37,"n":"第三十七条","txt":"询问应当个别进行。检察人员在询问前应当出示工作证，询问过程中应当制作《询问笔录》。被询问人确认无误后，签名或者盖章。被询问人拒绝签名盖章的，应当在笔录上注明。"},{"i":38,"n":"第三十八条","txt":"需要向有关单位或者个人调取物证、书证的，应当制作《调取证据通知书》和《调取证据清单》，持上述文书调取有关证据材料。"},{"i":39,"n":"第三十九条","txt":"人民检察院应当收集提取视听资料、电子数据的原始存储介质，调取原始存储介质确有困难或者因保密需要无法调取的，可以调取复制件。调取复制件的，应当说明其来源和制作经过。"},{"i":40,"n":"第四十条","txt":"人民检察院可以就专门性问题书面或者口头咨询有关专业人员、相关部门或者行业协会的意见。"},{"i":41,"n":"第四十一条","txt":"人民检察院对专门性问题认为确有必要鉴定、评估、审计、检验、检测、翻译的，可以委托具备资格的机构进行鉴定、评估、审计、检验、检测、翻译，委托时应当制作《委托鉴定（评估、审计、检验、检测、翻译）函》。"},{"i":42,"n":"第四十二条","txt":"人民检察院认为确有必要的，可以勘验物证或者现场。"},{"i":43,"n":"第四十三条","txt":"人民检察院办理公益诉讼案件，需要异地调查收集证据的，可以自行调查或者委托当地同级人民检察院进行。委托时应当出具委托书，载明需要调查的对象、事项及要求。受委托人民检察院应当在收到委托书之日起三十日内完成调查，并将情况回复委托的人民检察院。"},{"i":44,"n":"第四十四条","txt":"人民检察院可以依照规定组织听证，听取听证员、行政机关、违法行为人、行政相对人、受害人代表等相关各方意见，了解有关情况。"},{"i":45,"n":"第四十五条","txt":"行政机关及其工作人员拒绝或者妨碍人民检察院调查收集证据的，人民检察院可以向同级人大常委会报告，向同级纪检监察机关通报，或者通过上级人民检察院向其上级主管机关通报。"},{"i":46,"n":"第四十六条","txt":"人民检察院对于符合起诉条件的公益诉讼案件，应当依法向人民法院提起诉讼。"},{"i":47,"n":"第四十七条","txt":"人民检察院办理行政公益诉讼案件，审查起诉期限为一个月，自检察建议整改期满之日起计算。"},{"i":48,"n":"第四十八条","txt":"人民检察院办理公益诉讼案件，委托鉴定、评估、审计、检验、检测、翻译期间不计入审查起诉期限。"},{"i":49,"n":"第四十九条","txt":"人民检察院提起公益诉讼的案件，应当派员出庭履行职责，参加相关诉讼活动。"},{"i":50,"n":"第五十条","txt":"人民法院通知人民检察院派员参加证据交换、庭前会议的，由出席法庭的检察人员参加。人民检察院认为有必要的，可以商人民法院组织证据交换或者召开庭前会议。"},{"i":51,"n":"第五十一条","txt":"出庭检察人员履行以下职责："},{"i":52,"n":"第五十二条","txt":"出庭检察人员应当客观、全面地向法庭出示证据。根据庭审情况合理安排举证顺序，分组列举证据，可以使用多媒体等示证方式。质证应当围绕证据的真实性、合法性、关联性展开。"},{"i":53,"n":"第五十三条","txt":"出庭检察人员向被告、证人、鉴定人、勘验人等发问应当遵循下列要求："},{"i":54,"n":"第五十四条","txt":"出庭检察人员可以申请人民法院通知证人、鉴定人、有专门知识的人出庭作证或者提出意见。"},{"i":55,"n":"第五十五条","txt":"出庭检察人员在法庭审理期间，发现需要补充调查的，可以在法庭休庭后进行补充调查。"},{"i":56,"n":"第五十六条","txt":"出庭检察人员参加法庭辩论，应结合法庭调查情况，围绕双方在事实、证据、法律适用等方面的争议焦点发表辩论意见。"},{"i":57,"n":"第五十七条","txt":"出庭检察人员应当结合庭审情况，客观公正发表出庭意见。"},{"i":58,"n":"第五十八条","txt":"人民检察院应当在收到人民法院第一审公益诉讼判决书、裁定书后三日内报送上一级人民检察院备案。"},{"i":59,"n":"第五十九条","txt":"人民检察院提出上诉的，应当制作公益诉讼上诉书。公益诉讼上诉书的主要内容包括："},{"i":60,"n":"第六十条","txt":"人民检察院应当在上诉期限内通过原审人民法院向上一级人民法院提交公益诉讼上诉书，并将副本连同相关证据材料报送上一级人民检察院。"},{"i":61,"n":"第六十一条","txt":"上一级人民检察院认为上诉不当的，应当指令下级人民检察院撤回上诉。"},{"i":62,"n":"第六十二条","txt":"被告不服第一审公益诉讼判决、裁定上诉的，人民检察院应当在收到上诉状副本后三日内报送上一级人民检察院，提起诉讼的人民检察院和上一级人民检察院应当全面审查案卷材料。"},{"i":63,"n":"第六十三条","txt":"人民法院决定开庭审理的上诉案件，提起诉讼的人民检察院和上一级人民检察院应当共同派员出席第二审法庭。"},{"i":64,"n":"第六十四条","txt":"最高人民检察院发现各级人民法院、上级人民检察院发现下级人民法院已经发生法律效力的公益诉讼判决、裁定确有错误，损害国家利益或者社会公共利益的，应当依法提出抗诉。"},{"i":65,"n":"第六十五条","txt":"人民法院决定开庭审理的公益诉讼再审案件，与人民法院对应的同级人民检察院应当派员出席法庭。"},{"i":66,"n":"第六十六条","txt":"人民检察院发现人民法院公益诉讼审判程序违反法律规定，或者审判人员有《中华人民共和国法官法》第四十六条规定的违法行为，可能影响案件公正审判、执行的，或者人民法院在公益诉讼案件判决生效后不依法移送执行或者执行活动违反法律规定的，应当依法向同级人民法院提出检察建议。"},{"i":67,"n":"第六十七条","txt":"人民检察院经过对行政公益诉讼案件线索进行评估，认为同时存在以下情形的，应当立案："},{"i":68,"n":"第六十八条","txt":"人民检察院对于符合本规则第六十七条规定的下列情形，应当立案："},{"i":69,"n":"第六十九条","txt":"对于同一侵害国家利益或者社会公共利益的损害后果，数个负有不同监督管理职责的行政机关均可能存在不依法履行职责情形的，人民检察院可以对数个行政机关分别立案。"},{"i":70,"n":"第七十条","txt":"人民检察院决定立案的，应当在七日内将《立案决定书》送达行政机关，并可以就其是否存在违法行使职权或者不作为、国家利益或者社会公共利益受到侵害的后果、整改方案等事项进行磋商。"},{"i":71,"n":"第七十一条","txt":"人民检察院办理行政公益诉讼案件，围绕以下事项进行调查："},{"i":72,"n":"第七十二条","txt":"人民检察院认定行政机关监督管理职责的依据为法律法规规章，可以参考行政机关的“三定”方案、权力清单和责任清单等。"},{"i":73,"n":"第七十三条","txt":"调查结束，检察官应当制作《调查终结报告》，区分情况提出以下处理意见："},{"i":74,"n":"第七十四条","txt":"经调查，人民检察院认为存在下列情形之一的，应当作出终结案件决定："},{"i":75,"n":"第七十五条","txt":"经调查，人民检察院认为行政机关不依法履行职责，致使国家利益或者社会公共利益受到侵害的，应当报检察长决定向行政机关提出检察建议，并于《检察建议书》送达之日起五日内向上一级人民检察院备案。"},{"i":76,"n":"第七十六条","txt":"人民检察院决定提出检察建议的，应当在三日内将《检察建议书》送达行政机关。"},{"i":77,"n":"第七十七条","txt":"提出检察建议后，人民检察院应当对行政机关履行职责的情况和国家利益或者社会公共利益受到侵害的情况跟进调查，收集相关证据材料。"},{"i":78,"n":"第七十八条","txt":"行政机关在法律、司法解释规定的整改期限内已依法作出行政决定或者制定整改方案，但因突发事件等客观原因不能全部整改到位，且没有怠于履行监督管理职责情形的，人民检察院可以中止审查。"},{"i":79,"n":"第七十九条","txt":"经过跟进调查，检察官应当制作《审查终结报告》，区分情况提出以下处理意见："},{"i":80,"n":"第八十条","txt":"经审查，人民检察院发现有本规则第七十四条第一款规定情形之一的，应当终结案件。"},{"i":81,"n":"第八十一条","txt":"行政机关经检察建议督促仍然没有依法履行职责，国家利益或者社会公共利益处于受侵害状态的，人民检察院应当依法提起行政公益诉讼。"},{"i":82,"n":"第八十二条","txt":"有下列情形之一的，人民检察院可以认定行政机关未依法履行职责："},{"i":83,"n":"第八十三条","txt":"人民检察院可以根据行政机关的不同违法情形，向人民法院提出确认行政行为违法或者无效、撤销或者部分撤销违法行政行为、依法履行法定职责、变更行政行为等诉讼请求。"},{"i":84,"n":"第八十四条","txt":"在行政公益诉讼案件审理过程中，行政机关已经依法履行职责而全部实现诉讼请求的，人民检察院可以撤回起诉。确有必要的，人民检察院可以变更诉讼请求，请求判决确认行政行为违法。"},{"i":85,"n":"第八十五条","txt":"人民检察院经过对民事公益诉讼线索进行评估，认为同时存在以下情形的，应当立案："},{"i":86,"n":"第八十六条","txt":"人民检察院立案后，应当调查以下事项："},{"i":87,"n":"第八十七条","txt":"人民检察院办理涉及刑事犯罪的民事公益诉讼案件，在刑事案件的委托鉴定评估中，可以同步提出公益诉讼案件办理的鉴定评估需求。"},{"i":88,"n":"第八十八条","txt":"刑事侦查中依法收集的证据材料，可以在基于同一违法事实提起的民事公益诉讼案件中作为证据使用。"},{"i":89,"n":"第八十九条","txt":"调查结束，检察官应当制作《调查终结报告》，区分情况提出以下处理意见："},{"i":90,"n":"第九十条","txt":"经调查，人民检察院发现存在以下情形之一的，应当终结案件："},{"i":91,"n":"第九十一条","txt":"经调查，人民检察院认为社会公共利益受到损害，存在违法行为的，应当依法发布公告。公告应当包括以下内容："},{"i":92,"n":"第九十二条","txt":"人民检察院办理侵害英雄烈士等的姓名、肖像、名誉、荣誉的民事公益诉讼案件，可以直接征询英雄烈士等的近亲属的意见。被侵害的英雄烈士等人数众多、难以确定近亲属，或者直接征询近亲属意见确有困难的，也可以通过公告的方式征询英雄烈士等的近亲属的意见。"},{"i":93,"n":"第九十三条","txt":"发布公告后，人民检察院应当对赔偿权利人启动生态环境损害赔偿程序情况、适格主体起诉情况、英雄烈士等的近亲属提起民事诉讼情况，以及社会公共利益受到损害的情况跟进调查，收集相关证据材料。"},{"i":94,"n":"第九十四条","txt":"经过跟进调查，检察官应当制作《审查终结报告》，区分情况提出以下处理意见："},{"i":95,"n":"第九十五条","txt":"经审查，人民检察院发现有本规则第九十条规定情形之一的，应当终结案件。"},{"i":96,"n":"第九十六条","txt":"有下列情形之一，社会公共利益仍然处于受损害状态的，人民检察院应当提起民事公益诉讼："},{"i":97,"n":"第九十七条","txt":"人民检察院在刑事案件提起公诉时，对破坏生态环境和资源保护，食品药品安全领域侵害众多消费者合法权益，侵犯未成年人合法权益，侵害英雄烈士等的姓名、肖像、名誉、荣誉等损害社会公共利益的违法行为，可以向人民法院提起刑事附带民事公益诉讼。"},{"i":98,"n":"第九十八条","txt":"人民检察院可以向人民法院提出要求被告停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失等诉讼请求。"},{"i":99,"n":"第九十九条","txt":"民事公益诉讼案件可以依法在人民法院主持下进行调解。调解协议不得减免诉讼请求载明的民事责任，不得损害社会公共利益。"},{"i":100,"n":"第一百条","txt":"下列案件，人民检察院可以支持起诉："},{"i":101,"n":"第一百零一条","txt":"人民检察院可以采取提供法律咨询、向人民法院提交支持起诉意见书、协助调查取证、出席法庭等方式支持起诉。"},{"i":102,"n":"第一百零二条","txt":"人民检察院在向人民法院提交支持起诉意见书后，发现有以下不适合支持起诉情形的，可以撤回支持起诉："},{"i":103,"n":"第一百零三条","txt":"人民检察院撤回支持起诉后，认为适格主体提出的诉讼请求不足以保护社会公共利益，符合立案条件的，可以另行立案。"},{"i":104,"n":"第一百零四条","txt":"办理公益诉讼案件的人民检察院对涉及法律适用、办案程序、司法政策等问题，可以依照有关规定向上级人民检察院请示。"},{"i":105,"n":"第一百零五条","txt":"本规则所涉及的法律文书格式，由最高人民检察院统一制定。"},{"i":106,"n":"第一百零六条","txt":"各级人民检察院办理公益诉讼案件，应当依照有关规定及时归档。"},{"i":107,"n":"第一百零七条","txt":"人民检察院提起公益诉讼，不需要交纳诉讼费用。"},{"i":108,"n":"第一百零八条","txt":"军事检察院等专门人民检察院办理公益诉讼案件，适用本规则和其他有关规定。"},{"i":109,"n":"第一百零九条","txt":"本规则所称检察官，包括检察长、副检察长、检察委员会委员、检察员。"},{"i":110,"n":"第一百一十条","txt":"《中华人民共和国军人地位和权益保障法》《中华人民共和国安全生产法（2021修正）》等法律施行后，人民检察院办理公益诉讼案件的范围相应调整。"},{"i":111,"n":"第一百一十一条","txt":"本规则未规定的其他事项，适用民事诉讼法、行政诉讼法及相关司法解释的规定。"},{"i":112,"n":"第一百一十二条","txt":"本规则自2021年7月1日起施行。"}],"renminjianchayuanxingshisusongguize":[{"i":1,"n":"第一条","txt":"为保证人民检察院在刑事诉讼中严格依照法定程序办案，正确履行职权，实现惩罚犯罪与保障人权的统一，根据《中华人民共和国刑事诉讼法》《中华人民共和国人民检察院组织法》和有关法律规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院在刑事诉讼中的任务，是立案侦查直接受理的案件、审查逮捕、审查起诉和提起公诉、对刑事诉讼实行法律监督，保证准确、及时查明犯罪事实，正确应用法律，惩罚犯罪分子，保障无罪的人不受刑事追究，保障刑事法律的统一正确实施，维护社会主义法制，尊重和保障人权，保护公民的人身权利、财产权利、民主权利和其他权利，保障社会主义建设事业的顺利进行。"},{"i":3,"n":"第三条","txt":"人民检察院办理刑事案件，应当严格遵守《中华人民共和国刑事诉讼法》以及其他法律的有关规定，秉持客观公正的立场，尊重和保障人权，既要追诉犯罪，也要保障无罪的人不受刑事追究。"},{"i":4,"n":"第四条","txt":"人民检察院办理刑事案件，由检察官、检察长、检察委员会在各自职权范围内对办案事项作出决定，并依照规定承担相应司法责任。"},{"i":5,"n":"第五条","txt":"人民检察院办理刑事案件，根据案件情况，可以由一名检察官独任办理，也可以由两名以上检察官组成办案组办理。由检察官办案组办理的，检察长应当指定一名检察官担任主办检察官，组织、指挥办案组办理案件。"},{"i":6,"n":"第六条","txt":"人民检察院根据检察工作需要设置业务机构，在刑事诉讼中按照分工履行职责。"},{"i":7,"n":"第七条","txt":"检察长不同意检察官处理意见的，可以要求检察官复核，也可以直接作出决定，或者提请检察委员会讨论决定。"},{"i":8,"n":"第八条","txt":"对同一刑事案件的审查逮捕、审查起诉、出庭支持公诉和立案监督、侦查监督、审判监督等工作，由同一检察官或者检察官办案组负责，但是审查逮捕、审查起诉由不同人民检察院管辖，或者依照法律、有关规定应当另行指派检察官或者检察官办案组办理的除外。"},{"i":9,"n":"第九条","txt":"最高人民检察院领导地方各级人民检察院和专门人民检察院的工作，上级人民检察院领导下级人民检察院的工作。检察长统一领导人民检察院的工作。"},{"i":10,"n":"第十条","txt":"上级人民检察院对下级人民检察院作出的决定，有权予以撤销或者变更；发现下级人民检察院办理的案件有错误的，有权指令下级人民检察院予以纠正。"},{"i":11,"n":"第十一条","txt":"犯罪嫌疑人、被告人自愿如实供述自己的罪行，承认指控的犯罪事实，愿意接受处罚的，可以依法从宽处理。"},{"i":12,"n":"第十二条","txt":"人民检察院办理刑事案件的活动依照规定接受人民监督员监督。"},{"i":13,"n":"第十三条","txt":"人民检察院在对诉讼活动实行法律监督中发现的司法工作人员利用职权实施的非法拘禁、刑讯逼供、非法搜查等侵犯公民权利、损害司法公正的犯罪，可以由人民检察院立案侦查。"},{"i":14,"n":"第十四条","txt":"人民检察院办理直接受理侦查的案件，由设区的市级人民检察院立案侦查。基层人民检察院发现犯罪线索的，应当报设区的市级人民检察院决定立案侦查。"},{"i":15,"n":"第十五条","txt":"对本规则第十三条第二款规定的案件，人民检察院需要直接立案侦查的，应当层报省级人民检察院决定。"},{"i":16,"n":"第十六条","txt":"上级人民检察院在必要的时候，可以直接立案侦查或者组织、指挥、参与侦查下级人民检察院管辖的案件。下级人民检察院认为案情重大、复杂，需要由上级人民检察院立案侦查的案件，可以请求移送上级人民检察院立案侦查。"},{"i":17,"n":"第十七条","txt":"人民检察院办理直接受理侦查的案件，发现犯罪嫌疑人同时涉嫌监察机关管辖的职务犯罪线索的，应当及时与同级监察机关沟通。"},{"i":18,"n":"第十八条","txt":"人民检察院办理直接受理侦查的案件涉及公安机关管辖的刑事案件，应当将属于公安机关管辖的刑事案件移送公安机关。如果涉嫌的主罪属于公安机关管辖，由公安机关为主侦查，人民检察院予以配合；如果涉嫌的主罪属于人民检察院管辖，由人民检察院为主侦查，公安机关予以配合。"},{"i":19,"n":"第十九条","txt":"本规则第十三条规定的案件，由犯罪嫌疑人工作单位所在地的人民检察院管辖。如果由其他人民检察院管辖更为适宜的，可以由其他人民检察院管辖。"},{"i":20,"n":"第二十条","txt":"对管辖不明确的案件，可以由有关人民检察院协商确定管辖。"},{"i":21,"n":"第二十一条","txt":"几个人民检察院都有权管辖的案件，由最初受理的人民检察院管辖。必要时，可以由主要犯罪地的人民检察院管辖。"},{"i":22,"n":"第二十二条","txt":"对于下列案件，上级人民检察院可以指定管辖："},{"i":23,"n":"第二十三条","txt":"军事检察院等专门人民检察院的管辖以及军队与地方互涉刑事案件的管辖，按照有关规定执行。"},{"i":24,"n":"第二十四条","txt":"检察人员在受理举报和办理案件过程中，发现有刑事诉讼法第二十九条或者第三十条规定的情形之一的，应当自行提出回避；没有自行提出回避的，人民检察院应当决定其回避，当事人及其法定代理人有权要求其回避。"},{"i":25,"n":"第二十五条","txt":"检察人员自行回避的，应当书面或者口头提出，并说明理由。口头提出的，应当记录在案。"},{"i":26,"n":"第二十六条","txt":"人民检察院应当告知当事人及其法定代理人有依法申请回避的权利，并告知办理相关案件的检察人员、书记员等人员的姓名、职务等有关情况。"},{"i":27,"n":"第二十七条","txt":"当事人及其法定代理人要求检察人员回避的，应当书面或者口头向人民检察院提出，并说明理由。口头提出的，应当记录在案。根据刑事诉讼法第三十条的规定要求检察人员回避的，应当提供有关证明材料。"},{"i":28,"n":"第二十八条","txt":"在开庭审理过程中，当事人及其法定代理人向法庭申请出庭的检察人员回避的，在收到人民法院通知后，人民检察院应当作出回避或者驳回申请的决定。不属于刑事诉讼法第二十九条、第三十条规定情形的回避申请，出席法庭的检察人员应当建议法庭当庭驳回。"},{"i":29,"n":"第二十九条","txt":"检察长的回避，由检察委员会讨论决定。检察委员会讨论检察长回避问题时，由副检察长主持，检察长不得参加。"},{"i":30,"n":"第三十条","txt":"当事人及其法定代理人要求公安机关负责人回避，向同级人民检察院提出，或者向公安机关提出后，公安机关移送同级人民检察院的，由检察长提交检察委员会讨论决定。"},{"i":31,"n":"第三十一条","txt":"检察长应当回避，本人没有自行回避，当事人及其法定代理人也没有申请其回避的，检察委员会应当决定其回避。"},{"i":32,"n":"第三十二条","txt":"人民检察院作出驳回申请回避的决定后，应当告知当事人及其法定代理人如不服本决定，有权在收到驳回申请回避的决定书后五日以内向原决定机关申请复议一次。"},{"i":33,"n":"第三十三条","txt":"当事人及其法定代理人对驳回申请回避的决定不服申请复议的，决定机关应当在三日以内作出复议决定并书面通知申请人。"},{"i":34,"n":"第三十四条","txt":"对人民检察院直接受理的案件进行侦查的人员或者进行补充侦查的人员在回避决定作出以前和复议期间，不得停止对案件的侦查。"},{"i":35,"n":"第三十五条","txt":"参加过同一案件侦查的人员，不得承办该案的审查逮捕、审查起诉、出庭支持公诉和诉讼监督工作，但在审查起诉阶段参加自行补充侦查的人员除外。"},{"i":36,"n":"第三十六条","txt":"被决定回避的检察长在回避决定作出以前所取得的证据和进行的诉讼行为是否有效，由检察委员会根据案件具体情况决定。"},{"i":37,"n":"第三十七条","txt":"本规则关于回避的规定，适用于书记员、司法警察和人民检察院聘请或者指派的翻译人员、鉴定人。"},{"i":38,"n":"第三十八条","txt":"人民检察院在办案过程中，应当依法保障犯罪嫌疑人行使辩护权利。"},{"i":39,"n":"第三十九条","txt":"辩护人、诉讼代理人向人民检察院提出有关申请、要求或者提交有关书面材料的，负责案件管理的部门应当接收并及时移送办案部门或者与办案部门联系，具体业务由办案部门负责办理，本规则另有规定的除外。"},{"i":40,"n":"第四十条","txt":"人民检察院负责侦查的部门在第一次讯问犯罪嫌疑人或者对其采取强制措施时，应当告知犯罪嫌疑人有权委托辩护人，并告知其如果因经济困难或者其他原因没有委托辩护人的，可以申请法律援助。属于刑事诉讼法第三十五条规定情形的，应当告知犯罪嫌疑人有权获得法律援助。"},{"i":41,"n":"第四十一条","txt":"在押或者被指定居所监视居住的犯罪嫌疑人向人民检察院提出委托辩护人要求的，人民检察院应当及时向其监护人、近亲属或者其指定的人员转达要求，并记录在案。"},{"i":42,"n":"第四十二条","txt":"人民检察院办理直接受理侦查案件和审查起诉案件，发现犯罪嫌疑人是盲、聋、哑人或者是尚未完全丧失辨认或者控制自己行为能力的精神病人，或者可能被判处无期徒刑、死刑，没有委托辩护人的，应当自发现之日起三日以内书面通知法律援助机构指派律师为其提供辩护。"},{"i":43,"n":"第四十三条","txt":"人民检察院收到在押或者被指定居所监视居住的犯罪嫌疑人提出的法律援助申请，应当在二十四小时以内将申请材料转交法律援助机构，并通知犯罪嫌疑人的监护人、近亲属或者其委托的其他人员协助提供有关证件、证明等材料。"},{"i":44,"n":"第四十四条","txt":"属于应当提供法律援助的情形，犯罪嫌疑人拒绝法律援助机构指派的律师作为辩护人的，人民检察院应当查明拒绝的原因。有正当理由的，予以准许，但犯罪嫌疑人需另行委托辩护人；犯罪嫌疑人未另行委托辩护人的，应当书面通知法律援助机构另行指派律师为其提供辩护。"},{"i":45,"n":"第四十五条","txt":"辩护人接受委托后告知人民检察院，或者法律援助机构指派律师后通知人民检察院的，人民检察院负责案件管理的部门应当及时登记辩护人的相关信息，并将有关情况和材料及时通知、移交办案部门。"},{"i":46,"n":"第四十六条","txt":"人民检察院负责案件管理的部门应当依照法律规定对辩护人、诉讼代理人的资格进行审查，办案部门应当予以协助。"},{"i":47,"n":"第四十七条","txt":"自人民检察院对案件审查起诉之日起，应当允许辩护律师查阅、摘抄、复制本案的案卷材料。案卷材料包括案件的诉讼文书和证据材料。"},{"i":48,"n":"第四十八条","txt":"自人民检察院对案件审查起诉之日起，律师以外的辩护人向人民检察院申请查阅、摘抄、复制本案的案卷材料或者申请同在押、被监视居住的犯罪嫌疑人会见和通信的，由人民检察院负责捕诉的部门进行审查并作出是否许可的决定，在三日以内书面通知申请人。"},{"i":49,"n":"第四十九条","txt":"辩护律师或者经过许可的其他辩护人到人民检察院查阅、摘抄、复制本案的案卷材料，由负责案件管理的部门及时安排，由办案部门提供案卷材料。因办案部门工作等原因无法及时安排的，应当向辩护人说明，并自即日起三个工作日以内安排辩护人阅卷，办案部门应当予以配合。"},{"i":50,"n":"第五十条","txt":"案件提请批准逮捕或者移送起诉后，辩护人认为公安机关在侦查期间收集的证明犯罪嫌疑人无罪或者罪轻的证据材料未提交，申请人民检察院向公安机关调取的，人民检察院负责捕诉的部门应当及时审查。经审查，认为辩护人申请调取的证据已收集并且与案件事实有联系的，应当予以调取；认为辩护人申请调取的证据未收集或者与案件事实没有联系的，应当决定不予调取并向辩护人说明理由。公安机关移送相关证据材料的，人民检察院应当在三日以内告知辩护人。"},{"i":51,"n":"第五十一条","txt":"在人民检察院侦查、审查逮捕、审查起诉过程中，辩护人收集的有关犯罪嫌疑人不在犯罪现场、未达到刑事责任年龄、属于依法不负刑事责任的精神病人的证据，告知人民检察院的，人民检察院应当及时审查。"},{"i":52,"n":"第五十二条","txt":"案件移送起诉后，辩护律师依据刑事诉讼法第四十三条第一款的规定申请人民检察院收集、调取证据的，人民检察院负责捕诉的部门应当及时审查。经审查，认为需要收集、调取证据的，应当决定收集、调取并制作笔录附卷；决定不予收集、调取的，应当书面说明理由。"},{"i":53,"n":"第五十三条","txt":"辩护律师申请人民检察院许可其向被害人或者其近亲属、被害人提供的证人收集与本案有关材料的，人民检察院负责捕诉的部门应当及时进行审查。人民检察院应当在五日以内作出是否许可的决定，通知辩护律师；不予许可的，应当书面说明理由。"},{"i":54,"n":"第五十四条","txt":"在人民检察院侦查、审查逮捕、审查起诉过程中，辩护人要求听取其意见的，办案部门应当及时安排。辩护人提出书面意见的，办案部门应当接收并登记。"},{"i":55,"n":"第五十五条","txt":"人民检察院自收到移送起诉案卷材料之日起三日以内，应当告知被害人及其法定代理人或者其近亲属、附带民事诉讼的当事人及其法定代理人有权委托诉讼代理人。被害人及其法定代理人、近亲属因经济困难没有委托诉讼代理人的，应当告知其可以申请法律援助。"},{"i":56,"n":"第五十六条","txt":"经人民检察院许可，诉讼代理人查阅、摘抄、复制本案案卷材料的，参照本规则第四十九条的规定办理。"},{"i":57,"n":"第五十七条","txt":"辩护人、诉讼代理人认为公安机关、人民检察院、人民法院及其工作人员具有下列阻碍其依法行使诉讼权利行为之一，向同级或者上一级人民检察院申诉或者控告的，人民检察院负责控告申诉检察的部门应当接受并依法办理，其他办案部门应当予以配合："},{"i":58,"n":"第五十八条","txt":"辩护人、诉讼代理人认为其依法行使诉讼权利受到阻碍向人民检察院申诉或者控告的，人民检察院应当及时受理并调查核实，在十日以内办结并书面答复。情况属实的，通知有关机关或者本院有关部门、下级人民检察院予以纠正。"},{"i":59,"n":"第五十九条","txt":"辩护律师告知人民检察院其委托人或者其他人员准备实施、正在实施危害国家安全、危害公共安全以及严重危及他人人身安全犯罪的，人民检察院应当接受并立即移送有关机关依法处理。"},{"i":60,"n":"第六十条","txt":"人民检察院发现辩护人有帮助犯罪嫌疑人、被告人隐匿、毁灭、伪造证据、串供，或者威胁、引诱证人作伪证以及其他干扰司法机关诉讼活动的行为，可能涉嫌犯罪的，应当将涉嫌犯罪的线索或者证据材料移送有管辖权的机关依法处理。"},{"i":61,"n":"第六十一条","txt":"人民检察院认定案件事实，应当以证据为根据。"},{"i":62,"n":"第六十二条","txt":"证据的审查认定，应当结合案件的具体情况，从证据与待证事实的关联程度、各证据之间的联系、是否依照法定程序收集等方面进行综合审查判断。"},{"i":63,"n":"第六十三条","txt":"人民检察院侦查终结或者提起公诉的案件，证据应当确实、充分。证据确实、充分，应当符合以下条件："},{"i":64,"n":"第六十四条","txt":"行政机关在行政执法和查办案件过程中收集的物证、书证、视听资料、电子数据等证据材料，经人民检察院审查符合法定要求的，可以作为证据使用。"},{"i":65,"n":"第六十五条","txt":"监察机关依照法律规定收集的物证、书证、证人证言、被调查人供述和辩解、视听资料、电子数据等证据材料，在刑事诉讼中可以作为证据使用。"},{"i":66,"n":"第六十六条","txt":"对采用刑讯逼供等非法方法收集的犯罪嫌疑人供述和采用暴力、威胁等非法方法收集的证人证言、被害人陈述，应当依法排除，不得作为移送审查逮捕、批准或者决定逮捕、移送起诉以及提起公诉的依据。"},{"i":67,"n":"第六十七条","txt":"对采用下列方法收集的犯罪嫌疑人供述，应当予以排除："},{"i":68,"n":"第六十八条","txt":"对采用刑讯逼供方法使犯罪嫌疑人作出供述，之后犯罪嫌疑人受该刑讯逼供行为影响而作出的与该供述相同的重复性供述，应当一并排除，但下列情形除外："},{"i":69,"n":"第六十九条","txt":"采用暴力、威胁以及非法限制人身自由等非法方法收集的证人证言、被害人陈述，应当予以排除。"},{"i":70,"n":"第七十条","txt":"收集物证、书证不符合法定程序，可能严重影响司法公正的，人民检察院应当及时要求公安机关补正或者作出书面解释；不能补正或者无法作出合理解释的，对该证据应当予以排除。"},{"i":71,"n":"第七十一条","txt":"对重大案件，人民检察院驻看守所检察人员在侦查终结前应当对讯问合法性进行核查并全程同步录音、录像，核查情况应当及时通知本院负责捕诉的部门。"},{"i":72,"n":"第七十二条","txt":"人民检察院发现侦查人员以非法方法收集证据的，应当及时进行调查核实。"},{"i":73,"n":"第七十三条","txt":"人民检察院经审查认定存在非法取证行为的，对该证据应当予以排除，其他证据不能证明犯罪嫌疑人实施犯罪行为的，应当不批准或者决定逮捕。已经移送起诉的，可以依法将案件退回监察机关补充调查或者退回公安机关补充侦查，或者作出不起诉决定。被排除的非法证据应当随案移送，并写明为依法排除的非法证据。"},{"i":74,"n":"第七十四条","txt":"人民检察院认为可能存在以刑讯逼供等非法方法收集证据情形的，可以书面要求监察机关或者公安机关对证据收集的合法性作出说明。说明应当加盖单位公章，并由调查人员或者侦查人员签名。"},{"i":75,"n":"第七十五条","txt":"对于公安机关立案侦查的案件，存在下列情形之一的，人民检察院在审查逮捕、审查起诉和审判阶段，可以调取公安机关讯问犯罪嫌疑人的录音、录像，对证据收集的合法性以及犯罪嫌疑人、被告人供述的真实性进行审查："},{"i":76,"n":"第七十六条","txt":"对于提起公诉的案件，被告人及其辩护人提出审前供述系非法取得，并提供相关线索或者材料的，人民检察院可以将讯问录音、录像连同案卷材料一并移送人民法院。"},{"i":77,"n":"第七十七条","txt":"在法庭审理过程中，被告人或者辩护人对讯问活动合法性提出异议，公诉人可以要求被告人及其辩护人提供相关线索或者材料。必要时，公诉人可以提请法庭当庭播放相关时段的讯问录音、录像，对有关异议或者事实进行质证。"},{"i":78,"n":"第七十八条","txt":"人民检察院认为第一审人民法院有关证据收集合法性的审查、调查结论导致第一审判决、裁定错误的，可以依照刑事诉讼法第二百二十八条的规定向人民法院提出抗诉。"},{"i":79,"n":"第七十九条","txt":"人民检察院在办理危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪、毒品犯罪等案件过程中，证人、鉴定人、被害人因在诉讼中作证，本人或者其近亲属人身安全面临危险，向人民检察院请求保护的，人民检察院应当受理并及时进行审查。对于确实存在人身安全危险的，应当立即采取必要的保护措施。人民检察院发现存在上述情形的，应当主动采取保护措施。"},{"i":80,"n":"第八十条","txt":"证人在人民检察院侦查、审查逮捕、审查起诉期间因履行作证义务而支出的交通、住宿、就餐等费用，人民检察院应当给予补助。"},{"i":81,"n":"第八十一条","txt":"人民检察院根据案件情况，对犯罪嫌疑人可以拘传。"},{"i":82,"n":"第八十二条","txt":"拘传时，应当向被拘传的犯罪嫌疑人出示拘传证。对抗拒拘传的，可以使用戒具，强制到案。"},{"i":83,"n":"第八十三条","txt":"拘传的时间从犯罪嫌疑人到案时开始计算。犯罪嫌疑人到案后，应当责令其在拘传证上填写到案时间，签名或者盖章，并捺指印，然后立即讯问。拘传结束后，应当责令犯罪嫌疑人在拘传证上填写拘传结束时间。犯罪嫌疑人拒绝填写的，应当在拘传证上注明。"},{"i":84,"n":"第八十四条","txt":"人民检察院拘传犯罪嫌疑人，应当在犯罪嫌疑人所在市、县内的地点进行。"},{"i":85,"n":"第八十五条","txt":"需要对被拘传的犯罪嫌疑人变更强制措施的，应当在拘传期限内办理变更手续。"},{"i":86,"n":"第八十六条","txt":"人民检察院对于具有下列情形之一的犯罪嫌疑人，可以取保候审："},{"i":87,"n":"第八十七条","txt":"人民检察院对于严重危害社会治安的犯罪嫌疑人，以及其他犯罪性质恶劣、情节严重的犯罪嫌疑人不得取保候审。"},{"i":88,"n":"第八十八条","txt":"被羁押或者监视居住的犯罪嫌疑人及其法定代理人、近亲属或者辩护人向人民检察院申请取保候审，人民检察院应当在三日以内作出是否同意的答复。经审查符合本规则第八十六条规定情形之一的，可以对被羁押或者监视居住的犯罪嫌疑人依法办理取保候审手续。经审查不符合取保候审条件的，应当告知申请人，并说明不同意取保候审的理由。"},{"i":89,"n":"第八十九条","txt":"人民检察院决定对犯罪嫌疑人取保候审，应当责令犯罪嫌疑人提出保证人或者交纳保证金。"},{"i":90,"n":"第九十条","txt":"采取保证人保证方式的，保证人应当符合刑事诉讼法第六十九条规定的条件，并经人民检察院审查同意。"},{"i":91,"n":"第九十一条","txt":"人民检察院应当告知保证人履行以下义务："},{"i":92,"n":"第九十二条","txt":"采取保证金保证方式的，人民检察院可以根据犯罪嫌疑人的社会危险性，案件的性质、情节，可能判处刑罚的轻重，犯罪嫌疑人的经济状况等，责令犯罪嫌疑人交纳一千元以上的保证金。对于未成年犯罪嫌疑人，可以责令交纳五百元以上的保证金。"},{"i":93,"n":"第九十三条","txt":"人民检察院决定对犯罪嫌疑人取保候审的，应当制作取保候审决定书，载明取保候审开始的时间、保证方式、被取保候审人应当履行的义务和应当遵守的规定。"},{"i":94,"n":"第九十四条","txt":"人民检察院应当向取保候审的犯罪嫌疑人宣读取保候审决定书，由犯罪嫌疑人签名或者盖章，并捺指印，责令犯罪嫌疑人遵守刑事诉讼法第七十一条的规定，告知其违反规定应负的法律责任。以保证金方式保证的，应当同时告知犯罪嫌疑人一次性将保证金存入公安机关指定银行的专门账户。"},{"i":95,"n":"第九十五条","txt":"向犯罪嫌疑人宣布取保候审决定后，人民检察院应当将执行取保候审通知书送达公安机关执行，并告知公安机关在执行期间拟批准犯罪嫌疑人离开所居住的市、县的，应当事先征得人民检察院同意。以保证人方式保证的，应当将取保候审保证书同时送交公安机关。"},{"i":96,"n":"第九十六条","txt":"采取保证人保证方式的，如果保证人在取保候审期间不愿继续保证或者丧失保证条件的，人民检察院应当在收到保证人不愿继续保证的申请或者发现其丧失保证条件后三日以内，责令犯罪嫌疑人重新提出保证人或者交纳保证金，并将变更情况通知公安机关。"},{"i":97,"n":"第九十七条","txt":"采取保证金保证方式的，被取保候审人拒绝交纳保证金或者交纳保证金不足决定数额时，人民检察院应当作出变更取保候审措施、变更保证方式或者变更保证金数额的决定，并将变更情况通知公安机关。"},{"i":98,"n":"第九十八条","txt":"公安机关在执行取保候审期间向人民检察院征询是否同意批准犯罪嫌疑人离开所居住的市、县时，人民检察院应当根据案件的具体情况及时作出决定，并通知公安机关。"},{"i":99,"n":"第九十九条","txt":"人民检察院发现保证人没有履行刑事诉讼法第七十条规定的义务，应当通知公安机关，要求公安机关对保证人作出罚款决定。构成犯罪的，依法追究保证人的刑事责任。"},{"i":100,"n":"第一百条","txt":"人民检察院发现犯罪嫌疑人违反刑事诉讼法第七十一条的规定，已交纳保证金的，应当书面通知公安机关没收部分或者全部保证金，并且根据案件的具体情况，责令犯罪嫌疑人具结悔过，重新交纳保证金、提出保证人，或者决定对其监视居住、予以逮捕。"},{"i":101,"n":"第一百零一条","txt":"犯罪嫌疑人有下列违反取保候审规定的行为，人民检察院应当对犯罪嫌疑人予以逮捕："},{"i":102,"n":"第一百零二条","txt":"人民检察院决定对犯罪嫌疑人取保候审，最长不得超过十二个月。"},{"i":103,"n":"第一百零三条","txt":"公安机关决定对犯罪嫌疑人取保候审，案件移送人民检察院审查起诉后，对于需要继续取保候审的，人民检察院应当依法重新作出取保候审决定，并对犯罪嫌疑人办理取保候审手续。取保候审的期限应当重新计算并告知犯罪嫌疑人。对继续采取保证金方式取保候审的，被取保候审人没有违反刑事诉讼法第七十一条规定的，不变更保证金数额，不再重新收取保证金。"},{"i":104,"n":"第一百零四条","txt":"在取保候审期间，不得中断对案件的侦查、审查起诉。"},{"i":105,"n":"第一百零五条","txt":"取保候审期限届满或者发现不应当追究犯罪嫌疑人的刑事责任的，应当及时解除或者撤销取保候审。"},{"i":106,"n":"第一百零六条","txt":"犯罪嫌疑人在取保候审期间没有违反刑事诉讼法第七十一条的规定，或者发现不应当追究犯罪嫌疑人刑事责任的，变更、解除或者撤销取保候审时，应当告知犯罪嫌疑人可以凭变更、解除或者撤销取保候审的通知或者有关法律文书到银行领取退还的保证金。"},{"i":107,"n":"第一百零七条","txt":"人民检察院对于符合逮捕条件，具有下列情形之一的犯罪嫌疑人，可以监视居住："},{"i":108,"n":"第一百零八条","txt":"人民检察院应当向被监视居住的犯罪嫌疑人宣读监视居住决定书，由犯罪嫌疑人签名或者盖章，并捺指印，责令犯罪嫌疑人遵守刑事诉讼法第七十七条的规定，告知其违反规定应负的法律责任。"},{"i":109,"n":"第一百零九条","txt":"人民检察院核实犯罪嫌疑人住处或者为其指定居所后，应当制作监视居住执行通知书，将有关法律文书和案由、犯罪嫌疑人基本情况材料，送交监视居住地的公安机关执行，必要时人民检察院可以协助公安机关执行。"},{"i":110,"n":"第一百一十条","txt":"人民检察院可以根据案件的具体情况，商请公安机关对被监视居住的犯罪嫌疑人采取电子监控、不定期检查等监视方法，对其遵守监视居住规定的情况进行监督。"},{"i":111,"n":"第一百一十一条","txt":"犯罪嫌疑人有下列违反监视居住规定的行为，人民检察院应当对犯罪嫌疑人予以逮捕："},{"i":112,"n":"第一百一十二条","txt":"人民检察院决定对犯罪嫌疑人监视居住，最长不得超过六个月。"},{"i":113,"n":"第一百一十三条","txt":"公安机关决定对犯罪嫌疑人监视居住，案件移送人民检察院审查起诉后，对于需要继续监视居住的，人民检察院应当依法重新作出监视居住决定，并对犯罪嫌疑人办理监视居住手续。监视居住的期限应当重新计算并告知犯罪嫌疑人。"},{"i":114,"n":"第一百一十四条","txt":"在监视居住期间，不得中断对案件的侦查、审查起诉。"},{"i":115,"n":"第一百一十五条","txt":"监视居住期限届满或者发现不应当追究犯罪嫌疑人刑事责任的，应当解除或者撤销监视居住。"},{"i":116,"n":"第一百一十六条","txt":"监视居住应当在犯罪嫌疑人的住处执行。犯罪嫌疑人无固定住处的，可以在指定的居所执行。"},{"i":117,"n":"第一百一十七条","txt":"在指定的居所执行监视居住，除无法通知的以外，人民检察院应当在执行监视居住后二十四小时以内，将指定居所监视居住的原因通知被监视居住人的家属。无法通知的，应当将原因写明附卷。无法通知的情形消除后，应当立即通知。"},{"i":118,"n":"第一百一十八条","txt":"对于公安机关、人民法院决定指定居所监视居住的案件，由批准或者决定的公安机关、人民法院的同级人民检察院负责捕诉的部门对决定是否合法实行监督。"},{"i":119,"n":"第一百一十九条","txt":"被指定居所监视居住人及其法定代理人、近亲属或者辩护人认为指定居所监视居住决定存在违法情形，提出控告或者举报的，人民检察院应当受理。"},{"i":120,"n":"第一百二十条","txt":"对于公安机关、人民法院决定指定居所监视居住的案件，由人民检察院负责刑事执行检察的部门对指定居所监视居住的执行活动是否合法实行监督。发现存在下列违法情形之一的，应当及时提出纠正意见："},{"i":121,"n":"第一百二十一条","txt":"人民检察院对于具有下列情形之一的犯罪嫌疑人，可以决定拘留："},{"i":122,"n":"第一百二十二条","txt":"人民检察院作出拘留决定后，应当将有关法律文书和案由、犯罪嫌疑人基本情况的材料送交同级公安机关执行。必要时，人民检察院可以协助公安机关执行。"},{"i":123,"n":"第一百二十三条","txt":"对犯罪嫌疑人拘留后，除无法通知的以外，人民检察院应当在二十四小时以内，通知被拘留人的家属。"},{"i":124,"n":"第一百二十四条","txt":"对被拘留的犯罪嫌疑人，应当在拘留后二十四小时以内进行讯问。"},{"i":125,"n":"第一百二十五条","txt":"对被拘留的犯罪嫌疑人，发现不应当拘留的，应当立即释放；依法可以取保候审或者监视居住的，按照本规则的有关规定办理取保候审或者监视居住手续。"},{"i":126,"n":"第一百二十六条","txt":"人民检察院直接受理侦查的案件，拘留犯罪嫌疑人的羁押期限为十四日，特殊情况下可以延长一日至三日。"},{"i":127,"n":"第一百二十七条","txt":"公民将正在实行犯罪或者在犯罪后即被发觉的、通缉在案的、越狱逃跑的、正在被追捕的犯罪嫌疑人或者犯罪人扭送到人民检察院的，人民检察院应当予以接受，并且根据具体情况决定是否采取相应的紧急措施。不属于自己管辖的，应当移送主管机关处理。"},{"i":128,"n":"第一百二十八条","txt":"人民检察院对有证据证明有犯罪事实，可能判处徒刑以上刑罚的犯罪嫌疑人，采取取保候审尚不足以防止发生下列社会危险性的，应当批准或者决定逮捕："},{"i":129,"n":"第一百二十九条","txt":"犯罪嫌疑人具有下列情形之一的，可以认定为“可能实施新的犯罪”："},{"i":130,"n":"第一百三十条","txt":"犯罪嫌疑人具有下列情形之一的，可以认定为“有危害国家安全、公共安全或者社会秩序的现实危险”："},{"i":131,"n":"第一百三十一条","txt":"犯罪嫌疑人具有下列情形之一的，可以认定为“可能毁灭、伪造证据，干扰证人作证或者串供”："},{"i":132,"n":"第一百三十二条","txt":"犯罪嫌疑人具有下列情形之一的，可以认定为“可能对被害人、举报人、控告人实施打击报复”："},{"i":133,"n":"第一百三十三条","txt":"犯罪嫌疑人具有下列情形之一的，可以认定为“企图自杀或者逃跑”："},{"i":134,"n":"第一百三十四条","txt":"人民检察院办理审查逮捕案件，应当全面把握逮捕条件，对有证据证明有犯罪事实、可能判处徒刑以上刑罚的犯罪嫌疑人，除具有刑事诉讼法第八十一条第三款、第四款规定的情形外，应当严格审查是否具备社会危险性条件。"},{"i":135,"n":"第一百三十五条","txt":"人民检察院审查认定犯罪嫌疑人是否具有社会危险性，应当以公安机关移送的社会危险性相关证据为依据，并结合案件具体情况综合认定。必要时，可以通过讯问犯罪嫌疑人、询问证人等诉讼参与人、听取辩护律师意见等方式，核实相关证据。"},{"i":136,"n":"第一百三十六条","txt":"对有证据证明有犯罪事实，可能判处十年有期徒刑以上刑罚的犯罪嫌疑人，应当批准或者决定逮捕。"},{"i":137,"n":"第一百三十七条","txt":"人民检察院经审查认为被取保候审、监视居住的犯罪嫌疑人违反取保候审、监视居住规定，依照本规则第一百零一条、第一百一十一条的规定办理。"},{"i":138,"n":"第一百三十八条","txt":"对实施多个犯罪行为或者共同犯罪案件的犯罪嫌疑人，符合本规则第一百二十八条的规定，具有下列情形之一的，应当批准或者决定逮捕："},{"i":139,"n":"第一百三十九条","txt":"对具有下列情形之一的犯罪嫌疑人，人民检察院应当作出不批准逮捕或者不予逮捕的决定："},{"i":140,"n":"第一百四十条","txt":"犯罪嫌疑人涉嫌的罪行较轻，且没有其他重大犯罪嫌疑，具有下列情形之一的，可以作出不批准逮捕或者不予逮捕的决定："},{"i":141,"n":"第一百四十一条","txt":"对符合刑事诉讼法第七十四条第一款规定的犯罪嫌疑人，人民检察院经审查认为不需要逮捕的，可以在作出不批准逮捕决定的同时，向公安机关提出采取监视居住措施的建议。"},{"i":142,"n":"第一百四十二条","txt":"对于监察机关移送起诉的已采取留置措施的案件，人民检察院应当在受理案件后，及时对犯罪嫌疑人作出拘留决定，交公安机关执行。执行拘留后，留置措施自动解除。"},{"i":143,"n":"第一百四十三条","txt":"人民检察院应当在执行拘留后十日以内，作出是否逮捕、取保候审或者监视居住的决定。特殊情况下，决定的时间可以延长一日至四日。"},{"i":144,"n":"第一百四十四条","txt":"除无法通知的以外，人民检察院应当在公安机关执行拘留、逮捕后二十四小时以内，通知犯罪嫌疑人的家属。"},{"i":145,"n":"第一百四十五条","txt":"人民检察院应当自收到移送起诉的案卷材料之日起三日以内告知犯罪嫌疑人有权委托辩护人。对已经采取留置措施的，应当在执行拘留时告知。"},{"i":146,"n":"第一百四十六条","txt":"对于监察机关移送起诉的未采取留置措施的案件，人民检察院受理后，在审查起诉过程中根据案件情况，可以依照本规则相关规定决定是否采取逮捕、取保候审或者监视居住措施。"},{"i":147,"n":"第一百四十七条","txt":"对于监察机关移送起诉案件的犯罪嫌疑人采取强制措施，本节未规定的，适用本规则相关规定。"},{"i":148,"n":"第一百四十八条","txt":"人民检察院对担任县级以上各级人民代表大会代表的犯罪嫌疑人决定采取拘传、取保候审、监视居住、拘留、逮捕强制措施的，应当报请该代表所属的人民代表大会主席团或者常务委员会许可。"},{"i":149,"n":"第一百四十九条","txt":"担任县级以上人民代表大会代表的犯罪嫌疑人因现行犯被人民检察院拘留的，人民检察院应当立即向该代表所属的人民代表大会主席团或者常务委员会报告。报告的程序参照本规则第一百四十八条报请许可的程序规定。"},{"i":150,"n":"第一百五十条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为人民检察院采取强制措施法定期限届满，要求解除、变更强制措施或者释放犯罪嫌疑人的，人民检察院应当在收到申请后三日以内作出决定。"},{"i":151,"n":"第一百五十一条","txt":"犯罪嫌疑人及其法定代理人、近亲属或者辩护人向人民检察院提出变更强制措施申请的，人民检察院应当在收到申请后三日以内作出决定。"},{"i":152,"n":"第一百五十二条","txt":"人民检察院在侦查、审查起诉期间，对犯罪嫌疑人拘留、逮捕后发生依法延长侦查羁押期限、审查起诉期限，重新计算侦查羁押期限、审查起诉期限等期限改变的情形的，应当及时将变更后的期限书面通知看守所。"},{"i":153,"n":"第一百五十三条","txt":"人民检察院决定对涉嫌犯罪的机关事业单位工作人员取保候审、监视居住、拘留、逮捕的，应当在采取或者解除强制措施后五日以内告知其所在单位；决定撤销案件或者不起诉的，应当在作出决定后十日以内告知其所在单位。"},{"i":154,"n":"第一百五十四条","txt":"取保候审变更为监视居住，或者取保候审、监视居住变更为拘留、逮捕的，在变更的同时原强制措施自动解除，不再办理解除法律手续。"},{"i":155,"n":"第一百五十五条","txt":"人民检察院已经对犯罪嫌疑人取保候审、监视居住，案件起诉至人民法院后，人民法院决定取保候审、监视居住或者变更强制措施的，原强制措施自动解除，不再办理解除法律手续。"},{"i":156,"n":"第一百五十六条","txt":"下列案件，由人民检察院负责案件管理的部门统一受理："},{"i":157,"n":"第一百五十七条","txt":"人民检察院负责案件管理的部门受理案件时，应当接收案卷材料，并立即审查下列内容："},{"i":158,"n":"第一百五十八条","txt":"人民检察院负责案件管理的部门对接收的案卷材料审查后，认为具备受理条件的，应当及时进行登记，并立即将案卷材料和案件受理登记表移送办案部门办理。"},{"i":159,"n":"第一百五十九条","txt":"对公安机关送达的执行情况回执和人民法院送达的判决书、裁定书等法律文书，人民检察院负责案件管理的部门应当接收，即时登记。"},{"i":160,"n":"第一百六十条","txt":"人民检察院直接受理侦查的案件，移送审查逮捕、移送起诉的，按照本规则第一百五十六条至第一百五十八条的规定办理。"},{"i":161,"n":"第一百六十一条","txt":"人民检察院负责控告申诉检察的部门统一接受报案、控告、举报、申诉和犯罪嫌疑人投案自首，并依法审查，在七日以内作出以下处理："},{"i":162,"n":"第一百六十二条","txt":"控告、申诉符合下列条件的，人民检察院应当受理："},{"i":163,"n":"第一百六十三条","txt":"对于收到的群众来信，负责控告申诉检察的部门应当在七日以内进行程序性答复，办案部门应当在三个月以内将办理进展或者办理结果答复来信人。"},{"i":164,"n":"第一百六十四条","txt":"负责控告申诉检察的部门对受理的刑事申诉案件应当根据事实、法律进行审查，必要时可以进行调查核实。认为原案处理可能错误的，应当移送相关办案部门办理；认为原案处理没有错误的，应当书面答复申诉人。"},{"i":165,"n":"第一百六十五条","txt":"办案部门应当在规定期限内办结控告、申诉案件，制作相关法律文书，送达报案人、控告人、申诉人、举报人、自首人，并做好释法说理工作。"},{"i":166,"n":"第一百六十六条","txt":"人民检察院直接受理侦查案件的线索，由负责侦查的部门统一受理、登记和管理。负责控告申诉检察的部门接受的控告、举报，或者本院其他办案部门发现的案件线索，属于人民检察院直接受理侦查案件线索的，应当在七日以内移送负责侦查的部门。"},{"i":167,"n":"第一百六十七条","txt":"对于人民检察院直接受理侦查案件的线索，上级人民检察院在必要时，可以直接调查核实或者组织、指挥、参与下级人民检察院的调查核实，可以将下级人民检察院管辖的案件线索指定辖区内其他人民检察院调查核实，也可以将本院管辖的案件线索交由下级人民检察院调查核实；下级人民检察院认为案件线索重大、复杂，需要由上级人民检察院调查核实的，可以提请移送上级人民检察院调查核实。"},{"i":168,"n":"第一百六十八条","txt":"调查核实一般不得接触被调查对象。必须接触被调查对象的，应当经检察长批准。"},{"i":169,"n":"第一百六十九条","txt":"进行调查核实，可以采取询问、查询、勘验、检查、鉴定、调取证据材料等不限制被调查对象人身、财产权利的措施。不得对被调查对象采取强制措施，不得查封、扣押、冻结被调查对象的财产，不得采取技术侦查措施。"},{"i":170,"n":"第一百七十条","txt":"负责侦查的部门调查核实后，应当制作审查报告。"},{"i":171,"n":"第一百七十一条","txt":"人民检察院对于直接受理的案件，经审查认为有犯罪事实需要追究刑事责任的，应当制作立案报告书，经检察长批准后予以立案。"},{"i":172,"n":"第一百七十二条","txt":"对于其他机关或者本院其他办案部门移送的案件线索，决定不予立案的，负责侦查的部门应当制作不立案通知书，写明案由和案件来源、决定不立案的原因和法律依据，自作出不立案决定之日起十日以内送达移送案件线索的机关或者部门。"},{"i":173,"n":"第一百七十三条","txt":"对于控告和实名举报，决定不予立案的，应当制作不立案通知书，写明案由和案件来源、决定不立案的原因和法律依据，由负责侦查的部门在十五日以内送达控告人、举报人，同时告知本院负责控告申诉检察的部门。"},{"i":174,"n":"第一百七十四条","txt":"错告对被控告人、被举报人造成不良影响的，人民检察院应当自作出不立案决定之日起一个月以内向其所在单位或者有关部门通报调查核实的结论，澄清事实。"},{"i":175,"n":"第一百七十五条","txt":"人民检察院决定对人民代表大会代表立案，应当按照本规则第一百四十八条、第一百四十九条规定的程序向该代表所属的人民代表大会主席团或者常务委员会进行通报。"},{"i":176,"n":"第一百七十六条","txt":"人民检察院办理直接受理侦查的案件，应当全面、客观地收集、调取犯罪嫌疑人有罪或者无罪、罪轻或者罪重的证据材料，并依法进行审查、核实。办案过程中必须重证据，重调查研究，不轻信口供。严禁刑讯逼供和以威胁、引诱、欺骗以及其他非法方法收集证据，不得强迫任何人证实自己有罪。"},{"i":177,"n":"第一百七十七条","txt":"人民检察院办理直接受理侦查的案件，应当保障犯罪嫌疑人和其他诉讼参与人依法享有的辩护权和其他各项诉讼权利。"},{"i":178,"n":"第一百七十八条","txt":"人民检察院办理直接受理侦查的案件，应当严格依照刑事诉讼法规定的程序，严格遵守刑事案件办案期限的规定，依法提请批准逮捕、移送起诉、不起诉或者撤销案件。"},{"i":179,"n":"第一百七十九条","txt":"人民检察院办理直接受理侦查的案件，应当对侦查过程中知悉的国家秘密、商业秘密及个人隐私予以保密。"},{"i":180,"n":"第一百八十条","txt":"办理案件的人民检察院需要派员到本辖区以外进行搜查，调取物证、书证等证据材料，或者查封、扣押财物和文件的，应当持相关法律文书和证明文件等与当地人民检察院联系，当地人民检察院应当予以协助。"},{"i":181,"n":"第一百八十一条","txt":"人民检察院对于直接受理案件的侦查，可以适用刑事诉讼法第二编第二章规定的各项侦查措施。"},{"i":182,"n":"第一百八十二条","txt":"讯问犯罪嫌疑人，由检察人员负责进行。讯问时，检察人员或者检察人员和书记员不得少于二人。"},{"i":183,"n":"第一百八十三条","txt":"对于不需要逮捕、拘留的犯罪嫌疑人，可以传唤到犯罪嫌疑人所在市、县内的指定地点或者到他的住处进行讯问。"},{"i":184,"n":"第一百八十四条","txt":"传唤犯罪嫌疑人时，其家属在场的，应当当场将传唤的原因和处所口头告知其家属，并在讯问笔录中注明。其家属不在场的，应当及时将传唤的原因和处所通知被传唤人家属。无法通知的，应当在讯问笔录中注明。"},{"i":185,"n":"第一百八十五条","txt":"传唤持续的时间不得超过十二小时。案情特别重大、复杂，需要采取拘留、逮捕措施的，传唤持续的时间不得超过二十四小时。两次传唤间隔的时间一般不得少于十二小时，不得以连续传唤的方式变相拘禁犯罪嫌疑人。"},{"i":186,"n":"第一百八十六条","txt":"犯罪嫌疑人被送交看守所羁押后，检察人员对其进行讯问，应当填写提讯、提解证，在看守所讯问室进行。"},{"i":187,"n":"第一百八十七条","txt":"讯问犯罪嫌疑人一般按照下列顺序进行："},{"i":188,"n":"第一百八十八条","txt":"讯问犯罪嫌疑人，应当制作讯问笔录。讯问笔录应当忠实于原话，字迹清楚，详细具体，并交犯罪嫌疑人核对。犯罪嫌疑人没有阅读能力的，应当向他宣读。如果记载有遗漏或者差错，应当补充或者改正。犯罪嫌疑人认为讯问笔录没有错误的，由其在笔录上逐页签名或者盖章，并捺指印，在末页写明“以上笔录我看过（向我宣读过），和我说的相符”，同时签名或者盖章，并捺指印，注明日期。如果犯罪嫌疑人拒绝签名、盖章、捺指印的，应当在笔录上注明。讯问的检察人员、书记员也应当在笔录上签名。"},{"i":189,"n":"第一百八十九条","txt":"犯罪嫌疑人请求自行书写供述的，检察人员应当准许。必要时，检察人员也可以要求犯罪嫌疑人亲笔书写供述。犯罪嫌疑人应当在亲笔供述的末页签名或者盖章，并捺指印，注明书写日期。检察人员收到后，应当在首页右上方写明“于某年某月某日收到”，并签名。"},{"i":190,"n":"第一百九十条","txt":"人民检察院办理直接受理侦查的案件，应当在每次讯问犯罪嫌疑人时，对讯问过程实行全程录音、录像，并在讯问笔录中注明。"},{"i":191,"n":"第一百九十一条","txt":"人民检察院在侦查过程中，应当及时询问证人，并且告知证人履行作证的权利和义务。"},{"i":192,"n":"第一百九十二条","txt":"询问证人，应当由检察人员负责进行。询问时，检察人员或者检察人员和书记员不得少于二人。"},{"i":193,"n":"第一百九十三条","txt":"询问证人，可以在现场进行，也可以到证人所在单位、住处或者证人提出的地点进行。必要时，也可以通知证人到人民检察院提供证言。到证人提出的地点进行询问的，应当在笔录中记明。"},{"i":194,"n":"第一百九十四条","txt":"询问证人，应当问明证人的基本情况以及与当事人的关系，并且告知证人应当如实提供证据、证言和故意作伪证或者隐匿罪证应当承担的法律责任，但是不得向证人泄露案情，不得采用拘禁、暴力、威胁、引诱、欺骗以及其他非法方法获取证言。"},{"i":195,"n":"第一百九十五条","txt":"询问被害人，适用询问证人的规定。"},{"i":196,"n":"第一百九十六条","txt":"检察人员对于与犯罪有关的场所、物品、人身、尸体应当进行勘验或者检查。必要时，可以指派检察技术人员或者聘请其他具有专门知识的人，在检察人员的主持下进行勘验、检查。"},{"i":197,"n":"第一百九十七条","txt":"勘验时，人民检察院应当邀请两名与案件无关的见证人在场。"},{"i":198,"n":"第一百九十八条","txt":"人民检察院解剖死因不明的尸体，应当通知死者家属到场，并让其在解剖通知书上签名或者盖章。"},{"i":199,"n":"第一百九十九条","txt":"为了确定被害人、犯罪嫌疑人的某些特征、伤害情况或者生理状态，人民检察院可以对其人身进行检查，可以提取指纹信息，采集血液、尿液等生物样本。"},{"i":200,"n":"第二百条","txt":"为了查明案情，必要时经检察长批准，可以进行侦查实验。"},{"i":201,"n":"第二百零一条","txt":"侦查实验，必要时可以聘请有关专业人员参加，也可以要求犯罪嫌疑人、被害人、证人参加。"},{"i":202,"n":"第二百零二条","txt":"人民检察院有权要求有关单位和个人，交出能够证明犯罪嫌疑人有罪或者无罪以及犯罪情节轻重的证据。"},{"i":203,"n":"第二百零三条","txt":"为了收集犯罪证据，查获犯罪人，经检察长批准，检察人员可以对犯罪嫌疑人以及可能隐藏罪犯或者犯罪证据的人的身体、物品、住处、工作地点和其他有关的地方进行搜查。"},{"i":204,"n":"第二百零四条","txt":"搜查应当在检察人员的主持下进行，可以有司法警察参加。必要时，可以指派检察技术人员参加或者邀请当地公安机关、有关单位协助进行。"},{"i":205,"n":"第二百零五条","txt":"搜查时，应当向被搜查人或者他的家属出示搜查证。"},{"i":206,"n":"第二百零六条","txt":"搜查时，应当有被搜查人或者其家属、邻居或者其他见证人在场，并且对被搜查人或者其家属说明阻碍搜查、妨碍公务应负的法律责任。"},{"i":207,"n":"第二百零七条","txt":"搜查时，如果遇到阻碍，可以强制进行搜查。对以暴力、威胁方法阻碍搜查的，应当予以制止，或者由司法警察将其带离现场。阻碍搜查构成犯罪的，应当依法追究刑事责任。"},{"i":208,"n":"第二百零八条","txt":"检察人员可以凭人民检察院的证明文件，向有关单位和个人调取能够证明犯罪嫌疑人有罪或者无罪以及犯罪情节轻重的证据材料，并且可以根据需要拍照、录像、复印和复制。"},{"i":209,"n":"第二百零九条","txt":"调取物证应当调取原物。原物不便搬运、保存，或者依法应当返还被害人，或者因保密工作需要不能调取原物的，可以将原物封存，并拍照、录像。对原物拍照或者录像应当足以反映原物的外形、内容。"},{"i":210,"n":"第二百一十条","txt":"在侦查活动中发现的可以证明犯罪嫌疑人有罪、无罪或者犯罪情节轻重的各种财物和文件，应当查封或者扣押；与案件无关的，不得查封或者扣押。查封或者扣押应当经检察长批准。"},{"i":211,"n":"第二百一十一条","txt":"对犯罪嫌疑人使用违法所得与合法收入共同购置的不可分割的财产，可以先行查封、扣押、冻结。对无法分割退还的财产，应当在结案后予以拍卖、变卖，对不属于违法所得的部分予以退还。"},{"i":212,"n":"第二百一十二条","txt":"人民检察院根据侦查犯罪的需要，可以依照规定查询、冻结犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产，并可以要求有关单位和个人配合。"},{"i":213,"n":"第二百一十三条","txt":"犯罪嫌疑人的存款、汇款、债券、股票、基金份额等财产已冻结的，人民检察院不得重复冻结，可以轮候冻结。人民检察院应当要求有关银行或者其他金融机构、邮政部门在解除冻结或者作出处理前通知人民检察院。"},{"i":214,"n":"第二百一十四条","txt":"扣押、冻结债券、股票、基金份额等财产，应当书面告知当事人或者其法定代理人、委托代理人有权申请出售。"},{"i":215,"n":"第二百一十五条","txt":"对于冻结的存款、汇款、债券、股票、基金份额等财产，经查明确实与案件无关的，应当在三日以内解除冻结，并通知财产所有人。"},{"i":216,"n":"第二百一十六条","txt":"查询、冻结与案件有关的单位的存款、汇款、债券、股票、基金份额等财产的办法适用本规则第二百一十二条至第二百一十五条的规定。"},{"i":217,"n":"第二百一十七条","txt":"对于扣押的款项和物品，应当在三日以内将款项存入唯一合规账户，将物品送负责案件管理的部门保管。法律或者有关规定另有规定的除外。"},{"i":218,"n":"第二百一十八条","txt":"人民检察院为了查明案情，解决案件中某些专门性的问题，可以进行鉴定。"},{"i":219,"n":"第二百一十九条","txt":"人民检察院应当为鉴定人提供必要条件，及时向鉴定人送交有关检材和对比样本等原始材料，介绍与鉴定有关的情况，并明确提出要求鉴定解决的问题，但是不得暗示或者强迫鉴定人作出某种鉴定意见。"},{"i":220,"n":"第二百二十条","txt":"对于鉴定意见，检察人员应当进行审查，必要时可以进行补充鉴定或者重新鉴定。重新鉴定的，应当另行指派或者聘请鉴定人。"},{"i":221,"n":"第二百二十一条","txt":"用作证据的鉴定意见，人民检察院办案部门应当告知犯罪嫌疑人、被害人；被害人死亡或者没有诉讼行为能力的，应当告知其法定代理人、近亲属或诉讼代理人。"},{"i":222,"n":"第二百二十二条","txt":"对犯罪嫌疑人作精神病鉴定的期间不计入羁押期限和办案期限。"},{"i":223,"n":"第二百二十三条","txt":"为了查明案情，必要时，检察人员可以让被害人、证人和犯罪嫌疑人对与犯罪有关的物品、文件、尸体或场所进行辨认；也可以让被害人、证人对犯罪嫌疑人进行辨认，或者让犯罪嫌疑人对其他犯罪嫌疑人进行辨认。"},{"i":224,"n":"第二百二十四条","txt":"辨认应当在检察人员的主持下进行，执行辨认的人员不得少于二人。在辨认前，应当向辨认人详细询问被辨认对象的具体特征，避免辨认人见到被辨认对象，并应当告知辨认人有意作虚假辨认应负的法律责任。"},{"i":225,"n":"第二百二十五条","txt":"几名辨认人对同一被辨认对象进行辨认时，应当由每名辨认人单独进行。必要时，可以有见证人在场。"},{"i":226,"n":"第二百二十六条","txt":"辨认时，应当将辨认对象混杂在其他对象中。不得在辨认前向辨认人展示辨认对象及其影像资料，不得给辨认人任何暗示。"},{"i":227,"n":"第二百二十七条","txt":"人民检察院在立案后，对于利用职权实施的严重侵犯公民人身权利的重大犯罪案件，经过严格的批准手续，可以采取技术侦查措施，交有关机关执行。"},{"i":228,"n":"第二百二十八条","txt":"人民检察院办理直接受理侦查的案件，需要追捕被通缉或者决定逮捕的在逃犯罪嫌疑人、被告人的，经过批准，可以采取追捕所必需的技术侦查措施，不受本规则第二百二十七条规定的案件范围的限制。"},{"i":229,"n":"第二百二十九条","txt":"人民检察院采取技术侦查措施应当根据侦查犯罪的需要，确定采取技术侦查措施的种类和适用对象，按照有关规定报请批准。批准决定自签发之日起三个月以内有效。对于不需要继续采取技术侦查措施的，应当及时解除；对于复杂、疑难案件，期限届满仍有必要继续采取技术侦查措施的，应当在期限届满前十日以内制作呈请延长技术侦查措施期限报告书，写明延长的期限及理由，经过原批准机关批准，有效期可以延长，每次不得超过三个月。"},{"i":230,"n":"第二百三十条","txt":"采取技术侦查措施收集的物证、书证及其他证据材料，检察人员应当制作相应的说明材料，写明获取证据的时间、地点、数量、特征以及采取技术侦查措施的批准机关、种类等，并签名和盖章。"},{"i":231,"n":"第二百三十一条","txt":"检察人员对采取技术侦查措施过程中知悉的国家秘密、商业秘密和个人隐私，应当保密；对采取技术侦查措施获取的与案件无关的材料，应当及时销毁，并对销毁情况制作记录。"},{"i":232,"n":"第二百三十二条","txt":"人民检察院办理直接受理侦查的案件，应当逮捕的犯罪嫌疑人在逃，或者已被逮捕的犯罪嫌疑人脱逃的，经检察长批准，可以通缉。"},{"i":233,"n":"第二百三十三条","txt":"各级人民检察院需要在本辖区内通缉犯罪嫌疑人的，可以直接决定通缉；需要在本辖区外通缉犯罪嫌疑人的，由有决定权的上级人民检察院决定。"},{"i":234,"n":"第二百三十四条","txt":"人民检察院应当将通缉通知书和通缉对象的照片、身份、特征、案情简况送达公安机关，由公安机关发布通缉令，追捕归案。"},{"i":235,"n":"第二百三十五条","txt":"为防止犯罪嫌疑人等涉案人员逃往境外，需要在边防口岸采取边控措施的，人民检察院应当按照有关规定制作边控对象通知书，商请公安机关办理边控手续。"},{"i":236,"n":"第二百三十六条","txt":"应当逮捕的犯罪嫌疑人潜逃出境的，可以按照有关规定层报最高人民检察院商请国际刑警组织中国国家中心局，请求有关方面协助，或者通过其他法律规定的途径进行追捕。"},{"i":237,"n":"第二百三十七条","txt":"人民检察院经过侦查，认为犯罪事实清楚，证据确实、充分，依法应当追究刑事责任的，应当写出侦查终结报告，并且制作起诉意见书。"},{"i":238,"n":"第二百三十八条","txt":"负责侦查的部门应当将起诉意见书或者不起诉意见书，查封、扣押、冻结的犯罪嫌疑人的财物及其孳息、文件清单以及对查封、扣押、冻结的涉案财物的处理意见和其他案卷材料，一并移送本院负责捕诉的部门审查。国家或者集体财产遭受损失的，在提出提起公诉意见的同时，可以提出提起附带民事诉讼的意见。"},{"i":239,"n":"第二百三十九条","txt":"在案件侦查过程中，犯罪嫌疑人委托辩护律师的，检察人员可以听取辩护律师的意见。"},{"i":240,"n":"第二百四十条","txt":"人民检察院侦查终结的案件，需要在异地起诉、审判的，应当在移送起诉前与人民法院协商指定管辖的相关事宜。"},{"i":241,"n":"第二百四十一条","txt":"上级人民检察院侦查终结的案件，依照刑事诉讼法的规定应当由下级人民检察院提起公诉或者不起诉的，应当将有关决定、侦查终结报告连同案卷材料交由下级人民检察院审查。"},{"i":242,"n":"第二百四十二条","txt":"人民检察院在侦查过程中或者侦查终结后，发现具有下列情形之一的，负责侦查的部门应当制作拟撤销案件意见书，报请检察长决定："},{"i":243,"n":"第二百四十三条","txt":"地方各级人民检察院决定撤销案件的，负责侦查的部门应当将撤销案件意见书连同本案全部案卷材料，在法定期限届满七日前报上一级人民检察院审查；重大、复杂案件在法定期限届满十日前报上一级人民检察院审查。"},{"i":244,"n":"第二百四十四条","txt":"上一级人民检察院审查下级人民检察院报送的拟撤销案件，应当在收到案件后七日以内批复；重大、复杂案件，应当在收到案件后十日以内批复。情况紧急或者因其他特殊原因不能按时送达的，可以先行通知下级人民检察院执行。"},{"i":245,"n":"第二百四十五条","txt":"上一级人民检察院同意撤销案件的，下级人民检察院应当作出撤销案件决定，并制作撤销案件决定书。上一级人民检察院不同意撤销案件的，下级人民检察院应当执行上一级人民检察院的决定。"},{"i":246,"n":"第二百四十六条","txt":"撤销案件的决定，应当分别送达犯罪嫌疑人所在单位和犯罪嫌疑人。犯罪嫌疑人死亡的，应当送达犯罪嫌疑人原所在单位。如果犯罪嫌疑人在押，应当制作决定释放通知书，通知公安机关依法释放。"},{"i":247,"n":"第二百四十七条","txt":"人民检察院作出撤销案件决定的，应当在三十日以内报经检察长批准，对犯罪嫌疑人的违法所得作出处理。情况特殊的，可以延长三十日。"},{"i":248,"n":"第二百四十八条","txt":"人民检察院撤销案件时，对犯罪嫌疑人的违法所得及其他涉案财产应当区分不同情形，作出相应处理："},{"i":249,"n":"第二百四十九条","txt":"人民检察院撤销案件时，对查封、扣押、冻结的犯罪嫌疑人的涉案财物需要返还犯罪嫌疑人的，应当解除查封、扣押或者书面通知有关金融机构、邮政部门解除冻结，返还犯罪嫌疑人或者其合法继承人。"},{"i":250,"n":"第二百五十条","txt":"查封、扣押、冻结的财物，除依法应当返还被害人或者经查明确实与案件无关的以外，不得在诉讼程序终结之前处理。法律或者有关规定另有规定的除外。"},{"i":251,"n":"第二百五十一条","txt":"处理查封、扣押、冻结的涉案财物，应当由检察长决定。"},{"i":252,"n":"第二百五十二条","txt":"人民检察院直接受理侦查的共同犯罪案件，如果同案犯罪嫌疑人在逃，但在案犯罪嫌疑人犯罪事实清楚，证据确实、充分的，对在案犯罪嫌疑人应当根据本规则第二百三十七条的规定分别移送起诉或者移送不起诉。"},{"i":253,"n":"第二百五十三条","txt":"人民检察院直接受理侦查的案件，对犯罪嫌疑人没有采取取保候审、监视居住、拘留或者逮捕措施的，负责侦查的部门应当在立案后二年以内提出移送起诉、移送不起诉或者撤销案件的意见；对犯罪嫌疑人采取取保候审、监视居住、拘留或者逮捕措施的，负责侦查的部门应当在解除或者撤销强制措施后一年以内提出移送起诉、移送不起诉或者撤销案件的意见。"},{"i":254,"n":"第二百五十四条","txt":"人民检察院直接受理侦查的案件，撤销案件以后，又发现新的事实或者证据，认为有犯罪事实需要追究刑事责任的，可以重新立案侦查。"},{"i":255,"n":"第二百五十五条","txt":"人民检察院办理审查逮捕、审查起诉案件，应当全面审查证明犯罪嫌疑人有罪或者无罪、罪轻或者罪重的证据。"},{"i":256,"n":"第二百五十六条","txt":"经公安机关商请或者人民检察院认为确有必要时，可以派员适时介入重大、疑难、复杂案件的侦查活动，参加公安机关对于重大案件的讨论，对案件性质、收集证据、适用法律等提出意见，监督侦查活动是否合法。"},{"i":257,"n":"第二百五十七条","txt":"对于批准逮捕后要求公安机关继续侦查、不批准逮捕后要求公安机关补充侦查或者审查起诉阶段退回公安机关补充侦查的案件，人民检察院应当分别制作继续侦查提纲或者补充侦查提纲，写明需要继续侦查或者补充侦查的事项、理由、侦查方向、需补充收集的证据及其证明作用等，送交公安机关。"},{"i":258,"n":"第二百五十八条","txt":"人民检察院讯问犯罪嫌疑人时，应当首先查明犯罪嫌疑人的基本情况，依法告知犯罪嫌疑人诉讼权利和义务，以及认罪认罚的法律规定，听取其供述和辩解。犯罪嫌疑人翻供的，应当讯问其原因。犯罪嫌疑人申请排除非法证据的，应当告知其提供相关线索或者材料。犯罪嫌疑人检举揭发他人犯罪的，应当予以记录，并依照有关规定移送有关机关、部门处理。"},{"i":259,"n":"第二百五十九条","txt":"办理审查逮捕、审查起诉案件，可以询问证人、被害人、鉴定人等诉讼参与人，并制作笔录附卷。询问时，应当告知其诉讼权利和义务。"},{"i":260,"n":"第二百六十条","txt":"讯问犯罪嫌疑人，询问被害人、证人、鉴定人，听取辩护人、被害人及其诉讼代理人的意见，应当由检察人员负责进行。检察人员或者检察人员和书记员不得少于二人。"},{"i":261,"n":"第二百六十一条","txt":"办理审查逮捕案件，犯罪嫌疑人已经委托辩护律师的，可以听取辩护律师的意见。辩护律师提出要求的，应当听取辩护律师的意见。对辩护律师的意见应当制作笔录，辩护律师提出的书面意见应当附卷。"},{"i":262,"n":"第二百六十二条","txt":"直接听取辩护人、被害人及其诉讼代理人的意见有困难的，可以通过电话、视频等方式听取意见并记录在案，或者通知辩护人、被害人及其诉讼代理人提出书面意见。无法通知或者在指定期限内未提出意见的，应当记录在案。"},{"i":263,"n":"第二百六十三条","txt":"对于公安机关提请批准逮捕、移送起诉的案件，检察人员审查时发现存在本规则第七十五条第一款规定情形的，可以调取公安机关讯问犯罪嫌疑人的录音、录像并审查相关的录音、录像。对于重大、疑难、复杂的案件，必要时可以审查全部录音、录像。"},{"i":264,"n":"第二百六十四条","txt":"经审查讯问犯罪嫌疑人录音、录像，发现公安机关、本院负责侦查的部门讯问不规范，讯问过程存在违法行为，录音、录像内容与讯问笔录不一致等情形的，应当逐一列明并向公安机关、本院负责侦查的部门书面提出，要求其予以纠正、补正或者书面作出合理解释。发现讯问笔录与讯问犯罪嫌疑人录音、录像内容有重大实质性差异的，或者公安机关、本院负责侦查的部门不能补正或者作出合理解释的，该讯问笔录不能作为批准或者决定逮捕、提起公诉的依据。"},{"i":265,"n":"第二百六十五条","txt":"犯罪嫌疑人及其辩护人申请排除非法证据，并提供相关线索或者材料的，人民检察院应当调查核实。发现侦查人员以刑讯逼供等非法方法收集证据的，应当依法排除相关证据并提出纠正意见。"},{"i":266,"n":"第二百六十六条","txt":"审查逮捕期间，犯罪嫌疑人申请排除非法证据，但未提交相关线索或者材料，人民检察院经全面审查案件事实、证据，未发现侦查人员存在以非法方法收集证据的情形，认为符合逮捕条件的，可以批准逮捕。"},{"i":267,"n":"第二百六十七条","txt":"人民检察院办理犯罪嫌疑人认罪认罚案件，应当保障犯罪嫌疑人获得有效法律帮助，确保其了解认罪认罚的性质和法律后果，自愿认罪认罚。"},{"i":268,"n":"第二百六十八条","txt":"人民检察院应当商法律援助机构设立法律援助工作站派驻值班律师或者及时安排值班律师，为犯罪嫌疑人提供法律咨询、程序选择建议、申请变更强制措施、对案件处理提出意见等法律帮助。"},{"i":269,"n":"第二百六十九条","txt":"犯罪嫌疑人认罪认罚的，人民检察院应当告知其享有的诉讼权利和认罪认罚的法律规定，听取犯罪嫌疑人、辩护人或者值班律师、被害人及其诉讼代理人对下列事项的意见，并记录在案："},{"i":270,"n":"第二百七十条","txt":"批准或者决定逮捕，应当将犯罪嫌疑人涉嫌犯罪的性质、情节，认罪认罚等情况，作为是否可能发生社会危险性的考虑因素。"},{"i":271,"n":"第二百七十一条","txt":"审查起诉阶段，对于在侦查阶段认罪认罚的案件，人民检察院应当重点审查以下内容："},{"i":272,"n":"第二百七十二条","txt":"犯罪嫌疑人自愿认罪认罚，同意量刑建议和程序适用的，应当在辩护人或者值班律师在场的情况下签署认罪认罚具结书。具结书应当包括犯罪嫌疑人如实供述罪行、同意量刑建议和程序适用等内容，由犯罪嫌疑人及其辩护人、值班律师签名。"},{"i":273,"n":"第二百七十三条","txt":"犯罪嫌疑人认罪认罚，人民检察院经审查，认为符合速裁程序适用条件的，应当在十日以内作出是否提起公诉的决定，对可能判处的有期徒刑超过一年的，可以延长至十五日；认为不符合速裁程序适用条件的，应当在本规则第三百五十一条规定的期限以内作出是否提起公诉的决定。"},{"i":274,"n":"第二百七十四条","txt":"认罪认罚案件，人民检察院向人民法院提起公诉的，应当提出量刑建议，在起诉书中写明被告人认罪认罚情况，并移送认罪认罚具结书等材料。量刑建议可以另行制作文书，也可以在起诉书中写明。"},{"i":275,"n":"第二百七十五条","txt":"犯罪嫌疑人认罪认罚的，人民检察院应当就主刑、附加刑、是否适用缓刑等提出量刑建议。量刑建议一般应当为确定刑。对新类型、不常见犯罪案件，量刑情节复杂的重罪案件等，也可以提出幅度刑量刑建议。"},{"i":276,"n":"第二百七十六条","txt":"办理认罪认罚案件，人民检察院应当将犯罪嫌疑人是否与被害方达成和解或者调解协议，或者赔偿被害方损失，取得被害方谅解，或者自愿承担公益损害修复、赔偿责任，作为提出量刑建议的重要考虑因素。"},{"i":277,"n":"第二百七十七条","txt":"犯罪嫌疑人认罪认罚，人民检察院拟提出适用缓刑或者判处管制的量刑建议，可以委托犯罪嫌疑人居住地的社区矫正机构进行调查评估，也可以自行调查评估。"},{"i":278,"n":"第二百七十八条","txt":"犯罪嫌疑人认罪认罚，人民检察院依照刑事诉讼法第一百七十七条第二款作出不起诉决定后，犯罪嫌疑人反悔的，人民检察院应当进行审查，并区分下列情形依法作出处理："},{"i":279,"n":"第二百七十九条","txt":"犯罪嫌疑人自愿如实供述涉嫌犯罪的事实，有重大立功或者案件涉及国家重大利益的，经最高人民检察院核准，公安机关可以撤销案件，人民检察院可以作出不起诉决定，也可以对涉嫌数罪中的一项或者多项不起诉。"},{"i":280,"n":"第二百八十条","txt":"人民检察院办理审查逮捕案件，可以讯问犯罪嫌疑人；具有下列情形之一的，应当讯问犯罪嫌疑人："},{"i":281,"n":"第二百八十一条","txt":"对有重大影响的案件，可以采取当面听取侦查人员、犯罪嫌疑人及其辩护人等意见的方式进行公开审查。"},{"i":282,"n":"第二百八十二条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，已经被拘留的，人民检察院应当在收到提请批准逮捕书后七日以内作出是否批准逮捕的决定；未被拘留的，应当在收到提请批准逮捕书后十五日以内作出是否批准逮捕的决定，重大、复杂案件，不得超过二十日。"},{"i":283,"n":"第二百八十三条","txt":"上级公安机关指定犯罪地或者犯罪嫌疑人居住地以外的下级公安机关立案侦查的案件，需要逮捕犯罪嫌疑人的，由侦查该案件的公安机关提请同级人民检察院审查批准逮捕。人民检察院应当依法作出批准或者不批准逮捕的决定。"},{"i":284,"n":"第二百八十四条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，人民检察院经审查认为符合本规则第一百二十八条、第一百三十六条、第一百三十八条规定情形，应当作出批准逮捕的决定，连同案卷材料送达公安机关执行，并可以制作继续侦查提纲，送交公安机关。"},{"i":285,"n":"第二百八十五条","txt":"对公安机关提请批准逮捕的犯罪嫌疑人，具有本规则第一百三十九条至第一百四十一条规定情形，人民检察院作出不批准逮捕决定的，应当说明理由，连同案卷材料送达公安机关执行。需要补充侦查的，应当制作补充侦查提纲，送交公安机关。"},{"i":286,"n":"第二百八十六条","txt":"人民检察院应当将批准逮捕的决定交公安机关立即执行，并要求公安机关将执行回执及时送达作出批准决定的人民检察院。如果未能执行，也应当要求其将回执及时送达人民检察院，并写明未能执行的原因。对于人民检察院不批准逮捕的，应当要求公安机关在收到不批准逮捕决定书后，立即释放在押的犯罪嫌疑人或者变更强制措施，并将执行回执在收到不批准逮捕决定书后三日以内送达作出不批准逮捕决定的人民检察院。"},{"i":287,"n":"第二百八十七条","txt":"对于没有犯罪事实或者犯罪嫌疑人具有刑事诉讼法第十六条规定情形之一，人民检察院作出不批准逮捕决定的，应当同时告知公安机关撤销案件。"},{"i":288,"n":"第二百八十八条","txt":"人民检察院办理公安机关提请批准逮捕的案件，发现遗漏应当逮捕的犯罪嫌疑人的，应当经检察长批准，要求公安机关提请批准逮捕。公安机关不提请批准逮捕或者说明的不提请批准逮捕的理由不成立的，人民检察院可以直接作出逮捕决定，送达公安机关执行。"},{"i":289,"n":"第二百八十九条","txt":"对已经作出的批准逮捕决定发现确有错误的，人民检察院应当撤销原批准逮捕决定，送达公安机关执行。"},{"i":290,"n":"第二百九十条","txt":"对不批准逮捕的案件，公安机关要求复议的，人民检察院负责捕诉的部门应当另行指派检察官或者检察官办案组进行审查，并在收到要求复议意见书和案卷材料后七日以内，经检察长批准，作出是否变更的决定，通知公安机关。"},{"i":291,"n":"第二百九十一条","txt":"对不批准逮捕的案件，公安机关提请上一级人民检察院复核的，上一级人民检察院应当在收到提请复核意见书和案卷材料后十五日以内，经检察长批准，作出是否变更的决定，通知下级人民检察院和公安机关执行。需要改变原决定的，应当通知作出不批准逮捕决定的人民检察院撤销原不批准逮捕决定，另行制作批准逮捕决定书。必要时，上级人民检察院也可以直接作出批准逮捕决定，通知下级人民检察院送达公安机关执行。"},{"i":292,"n":"第二百九十二条","txt":"人民检察院作出不批准逮捕决定，并且通知公安机关补充侦查的案件，公安机关在补充侦查后又要求复议的，人民检察院应当告知公安机关重新提请批准逮捕。公安机关坚持要求复议的，人民检察院不予受理。"},{"i":293,"n":"第二百九十三条","txt":"对公安机关提请批准逮捕的案件，负责捕诉的部门应当将批准、变更、撤销逮捕措施的情况书面通知本院负责刑事执行检察的部门。"},{"i":294,"n":"第二百九十四条","txt":"外国人、无国籍人涉嫌危害国家安全犯罪的案件或者涉及国与国之间政治、外交关系的案件以及在适用法律上确有疑难的案件，需要逮捕犯罪嫌疑人的，按照刑事诉讼法关于管辖的规定，分别由基层人民检察院或者设区的市级人民检察院审查并提出意见，层报最高人民检察院审查。最高人民检察院认为需要逮捕的，经征求外交部的意见后，作出批准逮捕的批复；认为不需要逮捕的，作出不批准逮捕的批复。基层人民检察院或者设区的市级人民检察院根据最高人民检察院的批复，依法作出批准或者不批准逮捕的决定。层报过程中，上级人民检察院认为不需要逮捕的，应当作出不批准逮捕的批复。报送的人民检察院根据批复依法作出不批准逮捕的决定。"},{"i":295,"n":"第二百九十五条","txt":"人民检察院办理审查逮捕的危害国家安全犯罪案件，应当报上一级人民检察院备案。"},{"i":296,"n":"第二百九十六条","txt":"人民检察院办理直接受理侦查的案件，需要逮捕犯罪嫌疑人的，由负责侦查的部门制作逮捕犯罪嫌疑人意见书，连同案卷材料、讯问犯罪嫌疑人录音、录像一并移送本院负责捕诉的部门审查。犯罪嫌疑人已被拘留的，负责侦查的部门应当在拘留后七日以内将案件移送本院负责捕诉的部门审查。"},{"i":297,"n":"第二百九十七条","txt":"对本院负责侦查的部门移送审查逮捕的案件，犯罪嫌疑人已被拘留的，负责捕诉的部门应当在收到逮捕犯罪嫌疑人意见书后七日以内，报请检察长决定是否逮捕，特殊情况下，决定逮捕的时间可以延长一日至三日；犯罪嫌疑人未被拘留的，负责捕诉的部门应当在收到逮捕犯罪嫌疑人意见书后十五日以内，报请检察长决定是否逮捕，重大、复杂案件，不得超过二十日。"},{"i":298,"n":"第二百九十八条","txt":"对犯罪嫌疑人决定逮捕的，负责捕诉的部门应当将逮捕决定书连同案卷材料、讯问犯罪嫌疑人录音、录像移交负责侦查的部门，并可以对收集证据、适用法律提出意见。由负责侦查的部门通知公安机关执行，必要时可以协助执行。"},{"i":299,"n":"第二百九十九条","txt":"对犯罪嫌疑人决定不予逮捕的，负责捕诉的部门应当将不予逮捕的决定连同案卷材料、讯问犯罪嫌疑人录音、录像移交负责侦查的部门，并说明理由。需要补充侦查的，应当制作补充侦查提纲。犯罪嫌疑人已被拘留的，负责侦查的部门应当通知公安机关立即释放。"},{"i":300,"n":"第三百条","txt":"对应当逮捕而本院负责侦查的部门未移送审查逮捕的犯罪嫌疑人，负责捕诉的部门应当向负责侦查的部门提出移送审查逮捕犯罪嫌疑人的建议。建议不被采纳的，应当报请检察长决定。"},{"i":301,"n":"第三百零一条","txt":"逮捕犯罪嫌疑人后，应当立即送看守所羁押。除无法通知的以外，负责侦查的部门应当把逮捕的原因和羁押的处所，在二十四小时以内通知其家属。对于无法通知的，在无法通知的情形消除后，应当立即通知其家属。"},{"i":302,"n":"第三百零二条","txt":"对被逮捕的犯罪嫌疑人，应当在逮捕后二十四小时以内进行讯问。"},{"i":303,"n":"第三百零三条","txt":"已经作出不予逮捕的决定，又发现需要逮捕犯罪嫌疑人的，应当重新办理逮捕手续。"},{"i":304,"n":"第三百零四条","txt":"犯罪嫌疑人在异地羁押的，负责侦查的部门应当将决定、变更、撤销逮捕措施的情况书面通知羁押地人民检察院负责刑事执行检察的部门。"},{"i":305,"n":"第三百零五条","txt":"人民检察院办理直接受理侦查的案件，对犯罪嫌疑人逮捕后的侦查羁押期限不得超过二个月。案情复杂、期限届满不能终结的案件，可以经上一级人民检察院批准延长一个月。"},{"i":306,"n":"第三百零六条","txt":"设区的市级人民检察院和基层人民检察院办理直接受理侦查的案件，符合刑事诉讼法第一百五十八条规定，在本规则第三百零五条规定的期限届满前不能侦查终结的，经省级人民检察院批准，可以延长二个月。"},{"i":307,"n":"第三百零七条","txt":"设区的市级人民检察院和基层人民检察院办理直接受理侦查的案件，对犯罪嫌疑人可能判处十年有期徒刑以上刑罚，依照本规则第三百零六条的规定依法延长羁押期限届满，仍不能侦查终结的，经省级人民检察院批准，可以再延长二个月。"},{"i":308,"n":"第三百零八条","txt":"最高人民检察院办理直接受理侦查的案件，依照刑事诉讼法的规定需要延长侦查羁押期限的，直接决定延长侦查羁押期限。"},{"i":309,"n":"第三百零九条","txt":"公安机关需要延长侦查羁押期限的，人民检察院应当要求其在侦查羁押期限届满七日前提请批准延长侦查羁押期限。"},{"i":310,"n":"第三百一十条","txt":"人民检察院审查批准或者决定延长侦查羁押期限，由负责捕诉的部门办理。"},{"i":311,"n":"第三百一十一条","txt":"对于同时具备下列条件的案件，人民检察院应当作出批准延长侦查羁押期限一个月的决定："},{"i":312,"n":"第三百一十二条","txt":"犯罪嫌疑人虽然符合逮捕条件，但经审查，公安机关在对犯罪嫌疑人执行逮捕后二个月以内未有效开展侦查工作或者侦查取证工作没有实质进展的，人民检察院可以作出不批准延长侦查羁押期限的决定。"},{"i":313,"n":"第三百一十三条","txt":"有决定权的人民检察院作出批准延长侦查羁押期限或者不批准延长侦查羁押期限的决定后，应当将决定书交由最初受理案件的人民检察院送达公安机关。"},{"i":314,"n":"第三百一十四条","txt":"因为特殊原因，在较长时间内不宜交付审判的特别重大复杂的案件，由最高人民检察院报请全国人民代表大会常务委员会批准延期审理。"},{"i":315,"n":"第三百一十五条","txt":"人民检察院在侦查期间发现犯罪嫌疑人另有重要罪行的，自发现之日起依照本规则第三百零五条的规定重新计算侦查羁押期限。"},{"i":316,"n":"第三百一十六条","txt":"人民检察院重新计算侦查羁押期限，应当由负责侦查的部门提出重新计算侦查羁押期限的意见，移送本院负责捕诉的部门审查。负责捕诉的部门审查后应当提出是否同意重新计算侦查羁押期限的意见，报检察长决定。"},{"i":317,"n":"第三百一十七条","txt":"对公安机关重新计算侦查羁押期限的备案，由负责捕诉的部门审查。负责捕诉的部门认为公安机关重新计算侦查羁押期限不当的，应当提出纠正意见。"},{"i":318,"n":"第三百一十八条","txt":"人民检察院直接受理侦查的案件，不能在法定侦查羁押期限内侦查终结的，应当依法释放犯罪嫌疑人或者变更强制措施。"},{"i":319,"n":"第三百一十九条","txt":"负责捕诉的部门审查延长侦查羁押期限、审查重新计算侦查羁押期限，可以讯问犯罪嫌疑人，听取辩护律师和侦查人员的意见，调取案卷及相关材料等。"},{"i":320,"n":"第三百二十条","txt":"法定最高刑为无期徒刑、死刑的犯罪，已过二十年追诉期限的，不再追诉。如果认为必须追诉的，须报请最高人民检察院核准。"},{"i":321,"n":"第三百二十一条","txt":"须报请最高人民检察院核准追诉的案件，公安机关在核准之前可以依法对犯罪嫌疑人采取强制措施。"},{"i":322,"n":"第三百二十二条","txt":"报请核准追诉的案件应当同时符合下列条件："},{"i":323,"n":"第三百二十三条","txt":"公安机关报请核准追诉的案件，由同级人民检察院受理并层报最高人民检察院审查决定。"},{"i":324,"n":"第三百二十四条","txt":"地方各级人民检察院对公安机关报请核准追诉的案件，应当及时进行审查并开展必要的调查。经检察委员会审议提出是否同意核准追诉的意见，制作报请核准追诉案件报告书，连同案卷材料一并层报最高人民检察院。"},{"i":325,"n":"第三百二十五条","txt":"最高人民检察院收到省级人民检察院报送的报请核准追诉案件报告书及案卷材料后，应当及时审查，必要时指派检察人员到案发地了解案件有关情况。经检察长批准，作出是否核准追诉的决定，并制作核准追诉决定书或者不予核准追诉决定书，逐级下达至最初受理案件的人民检察院，由其送达报请核准追诉的公安机关。"},{"i":326,"n":"第三百二十六条","txt":"对已经采取强制措施的案件，强制措施期限届满不能作出是否核准追诉决定的，应当对犯罪嫌疑人变更强制措施或者延长侦查羁押期限。"},{"i":327,"n":"第三百二十七条","txt":"最高人民检察院决定核准追诉的案件，最初受理案件的人民检察院应当监督公安机关的侦查工作。"},{"i":328,"n":"第三百二十八条","txt":"各级人民检察院提起公诉，应当与人民法院审判管辖相适应。负责捕诉的部门收到移送起诉的案件后，经审查认为不属于本院管辖的，应当在发现之日起五日以内经由负责案件管理的部门移送有管辖权的人民检察院。"},{"i":329,"n":"第三百二十九条","txt":"监察机关移送起诉的案件，需要依照刑事诉讼法的规定指定审判管辖的，人民检察院应当在监察机关移送起诉二十日前协商同级人民法院办理指定管辖有关事宜。"},{"i":330,"n":"第三百三十条","txt":"人民检察院审查移送起诉的案件，应当查明："},{"i":331,"n":"第三百三十一条","txt":"人民检察院办理审查起诉案件应当讯问犯罪嫌疑人。"},{"i":332,"n":"第三百三十二条","txt":"人民检察院认为需要对案件中某些专门性问题进行鉴定而监察机关或者公安机关没有鉴定的，应当要求监察机关或者公安机关进行鉴定。必要时，也可以由人民检察院进行鉴定，或者由人民检察院聘请有鉴定资格的人进行鉴定。"},{"i":333,"n":"第三百三十三条","txt":"在审查起诉中，发现犯罪嫌疑人可能患有精神病的，人民检察院应当依照本规则的有关规定对犯罪嫌疑人进行鉴定。"},{"i":334,"n":"第三百三十四条","txt":"人民检察院对鉴定意见有疑问的，可以询问鉴定人或者有专门知识的人并制作笔录附卷，也可以指派有鉴定资格的检察技术人员或者聘请其他有鉴定资格的人进行补充鉴定或者重新鉴定。"},{"i":335,"n":"第三百三十五条","txt":"人民检察院审查案件时，对监察机关或者公安机关的勘验、检查，认为需要复验、复查的，应当要求其复验、复查，人民检察院可以派员参加；也可以自行复验、复查，商请监察机关或者公安机关派员参加，必要时也可以指派检察技术人员或者聘请其他有专门知识的人参加。"},{"i":336,"n":"第三百三十六条","txt":"人民检察院对物证、书证、视听资料、电子数据及勘验、检查、辨认、侦查实验等笔录存在疑问的，可以要求调查人员或者侦查人员提供获取、制作的有关情况，必要时也可以询问提供相关证据材料的人员和见证人并制作笔录附卷，对物证、书证、视听资料、电子数据进行鉴定。"},{"i":337,"n":"第三百三十七条","txt":"人民检察院在审查起诉阶段认为需要逮捕犯罪嫌疑人的，应当经检察长决定。"},{"i":338,"n":"第三百三十八条","txt":"对于人民检察院正在审查起诉的案件，被逮捕的犯罪嫌疑人及其法定代理人、近亲属或者辩护人认为羁押期限届满，向人民检察院提出释放犯罪嫌疑人或者变更强制措施要求的，人民检察院应当在三日以内审查决定。经审查，认为法定期限届满的，应当决定释放或者依法变更强制措施，并通知公安机关执行；认为法定期限未满的，书面答复申请人。"},{"i":339,"n":"第三百三十九条","txt":"人民检察院对案件进行审查后，应当依法作出起诉或者不起诉以及是否提起附带民事诉讼、附带民事公益诉讼的决定。"},{"i":340,"n":"第三百四十条","txt":"人民检察院对监察机关或者公安机关移送的案件进行审查后，在人民法院作出生效判决之前，认为需要补充提供证据材料的，可以书面要求监察机关或者公安机关提供。"},{"i":341,"n":"第三百四十一条","txt":"人民检察院在审查起诉中发现有应当排除的非法证据，应当依法排除，同时可以要求监察机关或者公安机关另行指派调查人员或者侦查人员重新取证。必要时，人民检察院也可以自行调查取证。"},{"i":342,"n":"第三百四十二条","txt":"人民检察院认为犯罪事实不清、证据不足或者存在遗漏罪行、遗漏同案犯罪嫌疑人等情形需要补充侦查的，应当制作补充侦查提纲，连同案卷材料一并退回公安机关补充侦查。人民检察院也可以自行侦查，必要时可以要求公安机关提供协助。"},{"i":343,"n":"第三百四十三条","txt":"人民检察院对于监察机关移送起诉的案件，认为需要补充调查的，应当退回监察机关补充调查。必要时，可以自行补充侦查。"},{"i":344,"n":"第三百四十四条","txt":"对于监察机关移送起诉的案件，具有下列情形之一的，人民检察院可以自行补充侦查："},{"i":345,"n":"第三百四十五条","txt":"人民检察院负责捕诉的部门对本院负责侦查的部门移送起诉的案件进行审查后，认为犯罪事实不清、证据不足或者存在遗漏罪行、遗漏同案犯罪嫌疑人等情形需要补充侦查的，应当制作补充侦查提纲，连同案卷材料一并退回负责侦查的部门补充侦查。必要时，也可以自行侦查，可以要求负责侦查的部门予以协助。"},{"i":346,"n":"第三百四十六条","txt":"退回监察机关补充调查、退回公安机关补充侦查的案件，均应当在一个月以内补充调查、补充侦查完毕。"},{"i":347,"n":"第三百四十七条","txt":"补充侦查期限届满，公安机关未将案件重新移送起诉的，人民检察院应当要求公安机关说明理由。"},{"i":348,"n":"第三百四十八条","txt":"人民检察院在审查起诉中决定自行侦查的，应当在审查起诉期限内侦查完毕。"},{"i":349,"n":"第三百四十九条","txt":"人民检察院对已经退回监察机关二次补充调查或者退回公安机关二次补充侦查的案件，在审查起诉中又发现新的犯罪事实，应当将线索移送监察机关或者公安机关。对已经查清的犯罪事实，应当依法提起公诉。"},{"i":350,"n":"第三百五十条","txt":"对于在审查起诉期间改变管辖的案件，改变后的人民检察院对于符合刑事诉讼法第一百七十五条第二款规定的案件，可以经原受理案件的人民检察院协助，直接退回原侦查案件的公安机关补充侦查，也可以自行侦查。改变管辖前后退回补充侦查的次数总共不得超过二次。"},{"i":351,"n":"第三百五十一条","txt":"人民检察院对于移送起诉的案件，应当在一个月以内作出决定；重大、复杂的案件，一个月以内不能作出决定的，可以延长十五日。"},{"i":352,"n":"第三百五十二条","txt":"追缴的财物中，属于被害人的合法财产，不需要在法庭出示的，应当及时返还被害人，并由被害人在发还款物清单上签名或者盖章，注明返还的理由，并将清单、照片附卷。"},{"i":353,"n":"第三百五十三条","txt":"追缴的财物中，属于违禁品或者不宜长期保存的物品，应当依照国家有关规定处理，并将清单、照片、处理结果附卷。"},{"i":354,"n":"第三百五十四条","txt":"人民检察院在审查起诉阶段，可以适用本规则规定的侦查措施和程序。"},{"i":355,"n":"第三百五十五条","txt":"人民检察院认为犯罪嫌疑人的犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当作出起诉决定。"},{"i":356,"n":"第三百五十六条","txt":"人民检察院在办理公安机关移送起诉的案件中，发现遗漏罪行或者有依法应当移送起诉的同案犯罪嫌疑人未移送起诉的，应当要求公安机关补充侦查或者补充移送起诉。对于犯罪事实清楚，证据确实、充分的，也可以直接提起公诉。"},{"i":357,"n":"第三百五十七条","txt":"人民检察院立案侦查时认为属于直接受理侦查的案件，在审查起诉阶段发现属于监察机关管辖的，应当及时商监察机关办理。属于公安机关管辖，案件事实清楚，证据确实、充分，符合起诉条件的，可以直接起诉；事实不清、证据不足的，应当及时移送有管辖权的机关办理。"},{"i":358,"n":"第三百五十八条","txt":"人民检察院决定起诉的，应当制作起诉书。"},{"i":359,"n":"第三百五十九条","txt":"人民检察院提起公诉的案件，应当向人民法院移送起诉书、案卷材料、证据和认罪认罚具结书等材料。"},{"i":360,"n":"第三百六十条","txt":"人民检察院对于犯罪嫌疑人、被告人或者证人等翻供、翻证的材料以及对犯罪嫌疑人、被告人有利的其他证据材料，应当移送人民法院。"},{"i":361,"n":"第三百六十一条","txt":"人民法院向人民检察院提出书面意见要求补充移送材料，人民检察院认为有必要移送的，应当自收到通知之日起三日以内补送。"},{"i":362,"n":"第三百六十二条","txt":"对提起公诉后，在人民法院宣告判决前补充收集的证据材料，人民检察院应当及时移送人民法院。"},{"i":363,"n":"第三百六十三条","txt":"在审查起诉期间，人民检察院可以根据辩护人的申请，向监察机关、公安机关调取在调查、侦查期间收集的证明犯罪嫌疑人、被告人无罪或者罪轻的证据材料。"},{"i":364,"n":"第三百六十四条","txt":"人民检察院提起公诉的案件，可以向人民法院提出量刑建议。除有减轻处罚或者免除处罚情节外，量刑建议应当在法定量刑幅度内提出。建议判处有期徒刑、管制、拘役的，可以具有一定的幅度，也可以提出具体确定的建议。"},{"i":365,"n":"第三百六十五条","txt":"人民检察院对于监察机关或者公安机关移送起诉的案件，发现犯罪嫌疑人没有犯罪事实，或者符合刑事诉讼法第十六条规定的情形之一的，经检察长批准，应当作出不起诉决定。"},{"i":366,"n":"第三百六十六条","txt":"负责捕诉的部门对于本院负责侦查的部门移送起诉的案件，发现具有本规则第三百六十五条第一款规定情形的，应当退回本院负责侦查的部门，建议撤销案件。"},{"i":367,"n":"第三百六十七条","txt":"人民检察院对于二次退回补充调查或者补充侦查的案件，仍然认为证据不足，不符合起诉条件的，经检察长批准，依法作出不起诉决定。"},{"i":368,"n":"第三百六十八条","txt":"具有下列情形之一，不能确定犯罪嫌疑人构成犯罪和需要追究刑事责任的，属于证据不足，不符合起诉条件："},{"i":369,"n":"第三百六十九条","txt":"人民检察院根据刑事诉讼法第一百七十五条第四款规定决定不起诉的，在发现新的证据，符合起诉条件时，可以提起公诉。"},{"i":370,"n":"第三百七十条","txt":"人民检察院对于犯罪情节轻微，依照刑法规定不需要判处刑罚或者免除刑罚的，经检察长批准，可以作出不起诉决定。"},{"i":371,"n":"第三百七十一条","txt":"人民检察院直接受理侦查的案件，以及监察机关移送起诉的案件，拟作不起诉决定的，应当报请上一级人民检察院批准。"},{"i":372,"n":"第三百七十二条","txt":"人民检察院决定不起诉的，应当制作不起诉决定书。"},{"i":373,"n":"第三百七十三条","txt":"人民检察院决定不起诉的案件，可以根据案件的不同情况，对被不起诉人予以训诫或者责令具结悔过、赔礼道歉、赔偿损失。"},{"i":374,"n":"第三百七十四条","txt":"人民检察院决定不起诉的案件，应当同时书面通知作出查封、扣押、冻结决定的机关或者执行查封、扣押、冻结决定的机关解除查封、扣押、冻结。"},{"i":375,"n":"第三百七十五条","txt":"人民检察院决定不起诉的案件，需要没收违法所得的，经检察长批准，应当提出检察意见，移送有关主管机关处理，并要求有关主管机关及时通报处理情况。具体程序可以参照本规则第二百四十八条的规定办理。"},{"i":376,"n":"第三百七十六条","txt":"不起诉的决定，由人民检察院公开宣布。公开宣布不起诉决定的活动应当记录在案。"},{"i":377,"n":"第三百七十七条","txt":"不起诉决定书应当送达被害人或者其近亲属及其诉讼代理人、被不起诉人及其辩护人以及被不起诉人所在单位。送达时，应当告知被害人或者其近亲属及其诉讼代理人，如果对不起诉决定不服，可以自收到不起诉决定书后七日以内向上一级人民检察院申诉；也可以不经申诉，直接向人民法院起诉。依照刑事诉讼法第一百七十七条第二款作出不起诉决定的，应当告知被不起诉人，如果对不起诉决定不服，可以自收到不起诉决定书后七日以内向人民检察院申诉。"},{"i":378,"n":"第三百七十八条","txt":"对于监察机关或者公安机关移送起诉的案件，人民检察院决定不起诉的，应当将不起诉决定书送达监察机关或者公安机关。"},{"i":379,"n":"第三百七十九条","txt":"监察机关认为不起诉的决定有错误，向上一级人民检察院提请复议的，上一级人民检察院应当在收到提请复议意见书后三十日以内，经检察长批准，作出复议决定，通知监察机关。"},{"i":380,"n":"第三百八十条","txt":"公安机关对不起诉决定提请复核的，上一级人民检察院应当在收到提请复核意见书后三十日以内，经检察长批准，作出复核决定，通知提请复核的公安机关和下级人民检察院。经复核认为下级人民检察院不起诉决定错误的，应当指令下级人民检察院纠正，或者撤销、变更下级人民检察院作出的不起诉决定。"},{"i":381,"n":"第三百八十一条","txt":"被害人不服不起诉决定，在收到不起诉决定书后七日以内提出申诉的，由作出不起诉决定的人民检察院的上一级人民检察院负责捕诉的部门进行复查。"},{"i":382,"n":"第三百八十二条","txt":"被害人不服不起诉决定，在收到不起诉决定书七日以后提出申诉的，由作出不起诉决定的人民检察院负责控告申诉检察的部门进行审查。经审查，认为不起诉决定正确的，出具审查结论直接答复申诉人，并做好释法说理工作；认为不起诉决定可能存在错误的，移送负责捕诉的部门进行复查。"},{"i":383,"n":"第三百八十三条","txt":"人民检察院应当将复查决定书送达被害人、被不起诉人和作出不起诉决定的人民检察院。"},{"i":384,"n":"第三百八十四条","txt":"人民检察院收到人民法院受理被害人对被不起诉人起诉的通知后，应当终止复查，将作出不起诉决定所依据的有关案卷材料移送人民法院。"},{"i":385,"n":"第三百八十五条","txt":"对于人民检察院依照刑事诉讼法第一百七十七条第二款规定作出的不起诉决定，被不起诉人不服，在收到不起诉决定书后七日以内提出申诉的，应当由作出决定的人民检察院负责捕诉的部门进行复查；被不起诉人在收到不起诉决定书七日以后提出申诉的，由负责控告申诉检察的部门进行审查。经审查，认为不起诉决定正确的，出具审查结论直接答复申诉人，并做好释法说理工作；认为不起诉决定可能存在错误的，移送负责捕诉的部门复查。"},{"i":386,"n":"第三百八十六条","txt":"人民检察院复查不服不起诉决定的申诉，应当在立案后三个月以内报经检察长批准作出复查决定。案情复杂的，不得超过六个月。"},{"i":387,"n":"第三百八十七条","txt":"被害人、被不起诉人对不起诉决定不服提出申诉的，应当递交申诉书，写明申诉理由。没有书写能力的，也可以口头提出申诉。人民检察院应当根据其口头提出的申诉制作笔录。"},{"i":388,"n":"第三百八十八条","txt":"人民检察院发现不起诉决定确有错误，符合起诉条件的，应当撤销不起诉决定，提起公诉。"},{"i":389,"n":"第三百八十九条","txt":"最高人民检察院对地方各级人民检察院的起诉、不起诉决定，上级人民检察院对下级人民检察院的起诉、不起诉决定，发现确有错误的，应当予以撤销或者指令下级人民检察院纠正。"},{"i":390,"n":"第三百九十条","txt":"提起公诉的案件，人民检察院应当派员以国家公诉人的身份出席第一审法庭，支持公诉。"},{"i":391,"n":"第三百九十一条","txt":"对于提起公诉后人民法院改变管辖的案件，提起公诉的人民检察院参照本规则第三百二十八条的规定将案件移送与审判管辖相对应的人民检察院。"},{"i":392,"n":"第三百九十二条","txt":"人民法院决定开庭审判的，公诉人应当做好以下准备工作："},{"i":393,"n":"第三百九十三条","txt":"人民检察院在开庭审理前收到人民法院或者被告人及其辩护人、被害人、证人等送交的反映证据系非法取得的书面材料的，应当进行审查。对于审查逮捕、审查起诉期间已经提出并经查证不存在非法取证行为的，应当通知人民法院、有关当事人和辩护人，并按照查证的情况做好庭审准备。对于新的材料或者线索，可以要求监察机关、公安机关对证据收集的合法性进行说明或者提供相关证明材料。"},{"i":394,"n":"第三百九十四条","txt":"人民法院通知人民检察院派员参加庭前会议的，由出席法庭的公诉人参加。检察官助理可以协助。根据需要可以配备书记员担任记录。"},{"i":395,"n":"第三百九十五条","txt":"在庭前会议中，公诉人可以对案件管辖、回避、出庭证人、鉴定人、有专门知识的人的名单、辩护人提供的无罪证据、非法证据排除、不公开审理、延期审理、适用简易程序或者速裁程序、庭审方案等与审判相关的问题提出和交换意见，了解辩护人收集的证据等情况。"},{"i":396,"n":"第三百九十六条","txt":"当事人、辩护人、诉讼代理人在庭前会议中提出证据系非法取得，人民法院认为可能存在以非法方法收集证据情形的，人民检察院应当对证据收集的合法性进行说明。需要调查核实的，在开庭审理前进行。"},{"i":397,"n":"第三百九十七条","txt":"人民检察院向人民法院移送全部案卷材料后，在法庭审理过程中，公诉人需要出示、宣读、播放有关证据的，可以申请法庭出示、宣读、播放。"},{"i":398,"n":"第三百九十八条","txt":"公诉人在法庭上应当依法进行下列活动："},{"i":399,"n":"第三百九十九条","txt":"在法庭审理中，公诉人应当客观、全面、公正地向法庭出示与定罪、量刑有关的证明被告人有罪、罪重或者罪轻的证据。"},{"i":400,"n":"第四百条","txt":"公诉人讯问被告人，询问证人、被害人、鉴定人，出示物证，宣读书证、未出庭证人的证言笔录等应当围绕下列事实进行："},{"i":401,"n":"第四百零一条","txt":"在法庭审理中，下列事实不必提出证据进行证明："},{"i":402,"n":"第四百零二条","txt":"讯问被告人、询问证人不得采取可能影响陈述或者证言客观真实的诱导性发问以及其他不当发问方式。"},{"i":403,"n":"第四百零三条","txt":"被告人在庭审中的陈述与在侦查、审查起诉中的供述一致或者不一致的内容不影响定罪量刑的，可以不宣读被告人供述笔录。"},{"i":404,"n":"第四百零四条","txt":"公诉人对证人证言有异议，且该证人证言对案件定罪量刑有重大影响的，可以申请人民法院通知证人出庭作证。"},{"i":405,"n":"第四百零五条","txt":"证人应当由人民法院通知并负责安排出庭作证。"},{"i":406,"n":"第四百零六条","txt":"证人在法庭上提供证言，公诉人应当按照审判长确定的顺序向证人发问。可以要求证人就其所了解的与案件有关的事实进行陈述，也可以直接发问。"},{"i":407,"n":"第四百零七条","txt":"必要时，公诉人可以建议法庭采取不暴露证人、鉴定人、被害人外貌、真实声音等出庭作证保护措施，或者建议法庭根据刑事诉讼法第一百五十四条的规定在庭外对证据进行核实。"},{"i":408,"n":"第四百零八条","txt":"对于鉴定意见、勘验、检查、辨认、侦查实验等笔录和其他作为证据的文书以及经人民法院通知而未到庭的被害人的陈述笔录，公诉人应当当庭宣读。"},{"i":409,"n":"第四百零九条","txt":"公诉人向法庭出示物证，一般应当出示原物，原物不易搬运、不易保存或者已返还被害人的，可以出示反映原物外形和特征的照片、录像、复制品，并向法庭说明情况及与原物的同一性。"},{"i":410,"n":"第四百一十条","txt":"在法庭审理过程中，被告人及其辩护人提出被告人庭前供述系非法取得，审判人员认为需要进行法庭调查的，公诉人可以通过出示讯问笔录、提讯登记、体检记录、采取强制措施或者侦查措施的法律文书、侦查终结前对讯问合法性进行核查的材料等证据材料，有针对性地播放讯问录音、录像，提请法庭通知调查人员、侦查人员或者其他人员出庭说明情况等方式，对证据收集的合法性加以证明。"},{"i":411,"n":"第四百一十一条","txt":"公诉人对证据收集的合法性进行证明后，法庭仍有疑问的，可以建议法庭休庭，由人民法院对相关证据进行调查核实。人民法院调查核实证据，通知人民检察院派员到场的，人民检察院可以派员到场。"},{"i":412,"n":"第四百一十二条","txt":"在法庭审理过程中，对证据合法性以外的其他程序事实存在争议的，公诉人应当出示、宣读有关诉讼文书、侦查或者审查起诉活动笔录。"},{"i":413,"n":"第四百一十三条","txt":"对于搜查、查封、扣押、冻结、勘验、检查、辨认、侦查实验等活动中形成的笔录存在争议，需要调查人员、侦查人员以及上述活动的见证人出庭陈述有关情况的，公诉人可以建议合议庭通知其出庭。"},{"i":414,"n":"第四百一十四条","txt":"在法庭审理过程中，合议庭对证据有疑问或者人民法院根据辩护人、被告人的申请，向人民检察院调取在侦查、审查起诉中收集的有关被告人无罪或者罪轻的证据材料的，人民检察院应当自收到人民法院要求调取证据材料决定书后三日以内移交。没有上述材料的，应当向人民法院说明情况。"},{"i":415,"n":"第四百一十五条","txt":"在法庭审理过程中，合议庭对证据有疑问并在休庭后进行勘验、检查、查封、扣押、鉴定和查询、冻结的，人民检察院应当依法进行监督，发现上述活动有违法情况的，应当提出纠正意见。"},{"i":416,"n":"第四百一十六条","txt":"人民法院根据申请收集、调取的证据或者在合议庭休庭后自行调查取得的证据，应当经过庭审出示、质证才能决定是否作为判决的依据。未经庭审出示、质证直接采纳为判决依据的，人民检察院应当提出纠正意见。"},{"i":417,"n":"第四百一十七条","txt":"在法庭审理过程中，经审判长许可，公诉人可以逐一对正在调查的证据和案件情况发表意见，并同被告人、辩护人进行辩论。证据调查结束时，公诉人应当发表总结性意见。"},{"i":418,"n":"第四百一十八条","txt":"人民检察院向人民法院提出量刑建议的，公诉人应当在发表公诉意见时提出。"},{"i":419,"n":"第四百一十九条","txt":"适用普通程序审理的认罪认罚案件，公诉人可以建议适当简化法庭调查、辩论程序。"},{"i":420,"n":"第四百二十条","txt":"在法庭审判过程中，遇有下列情形之一的，公诉人可以建议法庭延期审理："},{"i":421,"n":"第四百二十一条","txt":"法庭宣布延期审理后，人民检察院应当在补充侦查期限内提请人民法院恢复法庭审理或者撤回起诉。"},{"i":422,"n":"第四百二十二条","txt":"在审判过程中，对于需要补充提供法庭审判所必需的证据或者补充侦查的，人民检察院应当自行收集证据和进行侦查，必要时可以要求监察机关或者公安机关提供协助；也可以书面要求监察机关或者公安机关补充提供证据。"},{"i":423,"n":"第四百二十三条","txt":"人民法院宣告判决前，人民检察院发现被告人的真实身份或者犯罪事实与起诉书中叙述的身份或者指控犯罪事实不符的，或者事实、证据没有变化，但罪名、适用法律与起诉书不一致的，可以变更起诉。发现遗漏同案犯罪嫌疑人或者罪行的，应当要求公安机关补充移送起诉或者补充侦查；对于犯罪事实清楚，证据确实、充分的，可以直接追加、补充起诉。"},{"i":424,"n":"第四百二十四条","txt":"人民法院宣告判决前，人民检察院发现具有下列情形之一的，经检察长批准，可以撤回起诉："},{"i":425,"n":"第四百二十五条","txt":"在法庭审理过程中，人民法院建议人民检察院补充侦查、补充起诉、追加起诉或者变更起诉的，人民检察院应当审查有关理由，并作出是否补充侦查、补充起诉、追加起诉或者变更起诉的决定。人民检察院不同意的，可以要求人民法院就起诉指控的犯罪事实依法作出裁判。"},{"i":426,"n":"第四百二十六条","txt":"变更、追加、补充或者撤回起诉应当以书面方式在判决宣告前向人民法院提出。"},{"i":427,"n":"第四百二十七条","txt":"出庭的书记员应当制作出庭笔录，详细记载庭审的时间、地点、参加人员、公诉人出庭执行任务情况和法庭调查、法庭辩论的主要内容以及法庭判决结果，由公诉人和书记员签名。"},{"i":428,"n":"第四百二十八条","txt":"人民检察院应当当庭向人民法院移交取回的案卷材料和证据。在审判长宣布休庭后，公诉人应当与审判人员办理交接手续。无法当庭移交的，应当在休庭后三日以内移交。"},{"i":429,"n":"第四百二十九条","txt":"人民检察院对查封、扣押、冻结的被告人财物及其孳息，应当根据不同情况作以下处理："},{"i":430,"n":"第四百三十条","txt":"人民检察院对于基层人民法院管辖的案件，符合下列条件的，可以建议人民法院适用简易程序审理："},{"i":431,"n":"第四百三十一条","txt":"具有下列情形之一的，人民检察院不得建议人民法院适用简易程序："},{"i":432,"n":"第四百三十二条","txt":"基层人民检察院审查案件，认为案件事实清楚、证据充分的，应当在讯问犯罪嫌疑人时，了解其是否承认自己所犯罪行，对指控的犯罪事实有无异议，告知其适用简易程序的法律规定，确认其是否同意适用简易程序。"},{"i":433,"n":"第四百三十三条","txt":"适用简易程序审理的公诉案件，人民检察院应当派员出席法庭。"},{"i":434,"n":"第四百三十四条","txt":"公诉人出席简易程序法庭时，应当主要围绕量刑以及其他有争议的问题进行法庭调查和法庭辩论。在确认被告人庭前收到起诉书并对起诉书指控的犯罪事实没有异议后，可以简化宣读起诉书，根据案件情况决定是否讯问被告人，询问证人、鉴定人和出示证据。"},{"i":435,"n":"第四百三十五条","txt":"适用简易程序审理的公诉案件，公诉人发现不宜适用简易程序审理的，应当建议法庭按照第一审普通程序重新审理。"},{"i":436,"n":"第四百三十六条","txt":"转为普通程序审理的案件，公诉人需要为出席法庭进行准备的，可以建议人民法院延期审理。"},{"i":437,"n":"第四百三十七条","txt":"人民检察院对基层人民法院管辖的案件，符合下列条件的，在提起公诉时，可以建议人民法院适用速裁程序审理："},{"i":438,"n":"第四百三十八条","txt":"具有下列情形之一的，人民检察院不得建议人民法院适用速裁程序："},{"i":439,"n":"第四百三十九条","txt":"公安机关、犯罪嫌疑人及其辩护人建议适用速裁程序，人民检察院经审查认为符合条件的，可以建议人民法院适用速裁程序审理。"},{"i":440,"n":"第四百四十条","txt":"人民检察院建议人民法院适用速裁程序的案件，起诉书内容可以适当简化，重点写明指控的事实和适用的法律。"},{"i":441,"n":"第四百四十一条","txt":"人民法院适用速裁程序审理的案件，人民检察院应当派员出席法庭。"},{"i":442,"n":"第四百四十二条","txt":"公诉人出席速裁程序法庭时，可以简要宣读起诉书指控的犯罪事实、证据、适用法律及量刑建议，一般不再讯问被告人。"},{"i":443,"n":"第四百四十三条","txt":"适用速裁程序审理的案件，人民检察院发现有不宜适用速裁程序审理情形的，应当建议人民法院转为普通程序或者简易程序重新审理。"},{"i":444,"n":"第四百四十四条","txt":"转为普通程序审理的案件，公诉人需要为出席法庭进行准备的，可以建议人民法院延期审理。"},{"i":445,"n":"第四百四十五条","txt":"对提出抗诉的案件或者公诉案件中人民法院决定开庭审理的上诉案件，同级人民检察院应当指派检察官出席第二审法庭。检察官助理可以协助检察官出庭。根据需要可以配备书记员担任记录。"},{"i":446,"n":"第四百四十六条","txt":"检察官出席第二审法庭的任务是："},{"i":447,"n":"第四百四十七条","txt":"对抗诉和上诉案件，第二审人民法院的同级人民检察院可以调取下级人民检察院与案件有关的材料。"},{"i":448,"n":"第四百四十八条","txt":"检察人员应当客观全面地审查原审案卷材料，不受上诉或者抗诉范围的限制。应当审查原审判决认定案件事实、适用法律是否正确，证据是否确实、充分，量刑是否适当，审判活动是否合法，并应当审查下级人民检察院的抗诉书或者上诉人的上诉状，了解抗诉或者上诉的理由是否正确、充分，重点审查有争议的案件事实、证据和法律适用问题，有针对性地做好庭审准备工作。"},{"i":449,"n":"第四百四十九条","txt":"检察人员在审查第一审案卷材料时，应当复核主要证据，可以讯问原审被告人。必要时，可以补充收集证据、重新鉴定或者补充鉴定。需要原侦查案件的公安机关补充收集证据的，可以要求其补充收集。"},{"i":450,"n":"第四百五十条","txt":"人民检察院办理死刑上诉、抗诉案件，应当进行下列工作："},{"i":451,"n":"第四百五十一条","txt":"出席第二审法庭前，检察人员应当制作讯问原审被告人、询问被害人、证人、鉴定人和出示、宣读、播放证据计划，拟写答辩提纲，并制作出庭意见。"},{"i":452,"n":"第四百五十二条","txt":"在法庭审理中，检察官应当针对原审判决或者裁定认定事实或适用法律、量刑等方面的问题，围绕抗诉或者上诉理由以及辩护人的辩护意见，讯问原审被告人，询问被害人、证人、鉴定人，出示和宣读证据，并提出意见和进行辩论。"},{"i":453,"n":"第四百五十三条","txt":"需要出示、宣读、播放第一审期间已移交人民法院的证据的，出庭的检察官可以申请法庭出示、宣读、播放。"},{"i":454,"n":"第四百五十四条","txt":"人民法院开庭审理再审案件，同级人民检察院应当派员出席法庭。"},{"i":455,"n":"第四百五十五条","txt":"人民检察院对于人民法院按照审判监督程序重新审判的案件，应当对原判决、裁定认定的事实、证据、适用法律进行全面审查，重点审查有争议的案件事实、证据和法律适用问题。"},{"i":456,"n":"第四百五十六条","txt":"人民检察院派员出席再审法庭，如果再审案件按照第一审程序审理，参照本章第一节有关规定执行；如果再审案件按照第二审程序审理，参照本章第四节有关规定执行。"},{"i":457,"n":"第四百五十七条","txt":"人民检察院办理未成年人刑事案件，应当贯彻“教育、感化、挽救”方针和“教育为主、惩罚为辅”的原则，坚持优先保护、特殊保护、双向保护，以帮助教育和预防重新犯罪为目的。"},{"i":458,"n":"第四百五十八条","txt":"人民检察院应当指定熟悉未成年人身心特点的检察人员办理未成年人刑事案件。"},{"i":459,"n":"第四百五十九条","txt":"人民检察院办理未成年人与成年人共同犯罪案件，一般应当对未成年人与成年人分案办理、分别起诉。不宜分案处理的，应当对未成年人采取隐私保护、快速办理等特殊保护措施。"},{"i":460,"n":"第四百六十条","txt":"人民检察院受理案件后，应当向未成年犯罪嫌疑人及其法定代理人了解其委托辩护人的情况，并告知其有权委托辩护人。"},{"i":461,"n":"第四百六十一条","txt":"人民检察院根据情况可以对未成年犯罪嫌疑人的成长经历、犯罪原因、监护教育等情况进行调查，并制作社会调查报告，作为办案和教育的参考。"},{"i":462,"n":"第四百六十二条","txt":"人民检察院对未成年犯罪嫌疑人审查逮捕，应当根据未成年犯罪嫌疑人涉嫌犯罪的性质、情节、主观恶性、有无监护与社会帮教条件、认罪认罚等情况，综合衡量其社会危险性，严格限制适用逮捕措施。"},{"i":463,"n":"第四百六十三条","txt":"对于罪行较轻，具备有效监护条件或者社会帮教措施，没有社会危险性或者社会危险性较小的未成年犯罪嫌疑人，应当不批准逮捕。"},{"i":464,"n":"第四百六十四条","txt":"审查逮捕未成年犯罪嫌疑人，应当重点查清其是否已满十四、十六、十八周岁。"},{"i":465,"n":"第四百六十五条","txt":"在审查逮捕、审查起诉中，人民检察院应当讯问未成年犯罪嫌疑人，听取辩护人的意见，并制作笔录附卷。辩护人提出书面意见的，应当附卷。对于辩护人提出犯罪嫌疑人无罪、罪轻或者减轻、免除刑事责任、不适宜羁押或者侦查活动有违法情形等意见的，检察人员应当进行审查，并在相关工作文书中叙明辩护人提出的意见，说明是否采纳的情况和理由。"},{"i":466,"n":"第四百六十六条","txt":"讯问未成年犯罪嫌疑人应当保护其人格尊严。"},{"i":467,"n":"第四百六十七条","txt":"未成年犯罪嫌疑人认罪认罚的，人民检察院应当告知本人及其法定代理人享有的诉讼权利和认罪认罚的法律规定，并依照刑事诉讼法第一百七十三条的规定，听取、记录未成年犯罪嫌疑人及其法定代理人、辩护人、被害人及其诉讼代理人的意见。"},{"i":468,"n":"第四百六十八条","txt":"未成年犯罪嫌疑人认罪认罚的，应当在法定代理人、辩护人在场的情况下签署认罪认罚具结书。法定代理人、辩护人对认罪认罚有异议的，不需要签署具结书。"},{"i":469,"n":"第四百六十九条","txt":"对于符合刑事诉讼法第二百八十二条第一款规定条件的未成年人刑事案件，人民检察院可以作出附条件不起诉的决定。"},{"i":470,"n":"第四百七十条","txt":"未成年犯罪嫌疑人及其法定代理人对拟作出附条件不起诉决定提出异议的，人民检察院应当提起公诉。但是，未成年犯罪嫌疑人及其法定代理人提出无罪辩解，人民检察院经审查认为无罪辩解理由成立的，应当按照本规则第三百六十五条的规定作出不起诉决定。"},{"i":471,"n":"第四百七十一条","txt":"人民检察院作出附条件不起诉的决定后，应当制作附条件不起诉决定书，并在三日以内送达公安机关、被害人或者其近亲属及其诉讼代理人、未成年犯罪嫌疑人及其法定代理人、辩护人。"},{"i":472,"n":"第四百七十二条","txt":"对附条件不起诉的决定，公安机关要求复议、提请复核或者被害人提出申诉的，具体程序参照本规则第三百七十九条至第三百八十三条的规定。被害人不服附条件不起诉决定的，应当告知其不适用刑事诉讼法第一百八十条关于被害人可以向人民法院起诉的规定，并做好释法说理工作。"},{"i":473,"n":"第四百七十三条","txt":"人民检察院作出附条件不起诉决定的，应当确定考验期。考验期为六个月以上一年以下，从人民检察院作出附条件不起诉的决定之日起计算。"},{"i":474,"n":"第四百七十四条","txt":"在附条件不起诉的考验期内，由人民检察院对被附条件不起诉的未成年犯罪嫌疑人进行监督考察。人民检察院应当要求未成年犯罪嫌疑人的监护人对未成年犯罪嫌疑人加强管教，配合人民检察院做好监督考察工作。"},{"i":475,"n":"第四百七十五条","txt":"人民检察院对于被附条件不起诉的未成年犯罪嫌疑人，应当监督考察其是否遵守下列规定："},{"i":476,"n":"第四百七十六条","txt":"人民检察院可以要求被附条件不起诉的未成年犯罪嫌疑人接受下列矫治和教育："},{"i":477,"n":"第四百七十七条","txt":"考验期届满，检察人员应当制作附条件不起诉考察意见书，提出起诉或者不起诉的意见，报请检察长决定。"},{"i":478,"n":"第四百七十八条","txt":"考验期满作出不起诉决定，被害人提出申诉的，依照本规则第四百七十二条规定办理。"},{"i":479,"n":"第四百七十九条","txt":"被附条件不起诉的未成年犯罪嫌疑人，在考验期内具有下列情形之一的，人民检察院应当撤销附条件不起诉的决定，提起公诉："},{"i":480,"n":"第四百八十条","txt":"被附条件不起诉的未成年犯罪嫌疑人，在考验期内没有本规则第四百七十九条规定的情形，考验期满的，人民检察院应当作出不起诉的决定。"},{"i":481,"n":"第四百八十一条","txt":"人民检察院办理未成年人刑事案件过程中，应当对涉案未成年人的资料予以保密，不得公开或者传播涉案未成年人的姓名、住所、照片、图像及可能推断出该未成年人的其他资料。"},{"i":482,"n":"第四百八十二条","txt":"犯罪的时候不满十八周岁，被判处五年有期徒刑以下刑罚的，人民检察院应当在收到人民法院生效判决、裁定后，对犯罪记录予以封存。"},{"i":483,"n":"第四百八十三条","txt":"人民检察院应当将拟封存的未成年人犯罪记录、案卷等相关材料装订成册，加密保存，不予公开，并建立专门的未成年人犯罪档案库，执行严格的保管制度。"},{"i":484,"n":"第四百八十四条","txt":"除司法机关为办案需要或者有关单位根据国家规定进行查询的以外，人民检察院不得向任何单位和个人提供封存的犯罪记录，并不得提供未成年人有犯罪记录的证明。"},{"i":485,"n":"第四百八十五条","txt":"未成年人犯罪记录封存后，没有法定事由、未经法定程序不得解封。"},{"i":486,"n":"第四百八十六条","txt":"人民检察院对未成年犯罪嫌疑人作出不起诉决定后，应当对相关记录予以封存。除司法机关为办案需要进行查询外，不得向任何单位和个人提供。封存的具体程序参照本规则第四百八十三条至第四百八十五条的规定。"},{"i":487,"n":"第四百八十七条","txt":"被封存犯罪记录的未成年人或者其法定代理人申请出具无犯罪记录证明的，人民检察院应当出具。需要协调公安机关、人民法院为其出具无犯罪记录证明的，人民检察院应当予以协助。"},{"i":488,"n":"第四百八十八条","txt":"负责未成年人检察的部门应当依法对看守所、未成年犯管教所监管未成年人的活动实行监督，配合做好对未成年人的教育。发现没有对未成年犯罪嫌疑人、被告人与成年犯罪嫌疑人、被告人分别关押、管理或者违反规定对未成年犯留所执行刑罚的，应当依法提出纠正意见。"},{"i":489,"n":"第四百八十九条","txt":"本节所称未成年人刑事案件，是指犯罪嫌疑人实施涉嫌犯罪行为时已满十四周岁、未满十八周岁的刑事案件。"},{"i":490,"n":"第四百九十条","txt":"人民检察院办理侵害未成年人犯罪案件，应当采取适合未成年被害人身心特点的方法，充分保护未成年被害人的合法权益。"},{"i":491,"n":"第四百九十一条","txt":"办理未成年人刑事案件，除本节已有规定的以外，按照刑事诉讼法和其他有关规定进行。"},{"i":492,"n":"第四百九十二条","txt":"下列公诉案件，双方当事人可以和解："},{"i":493,"n":"第四百九十三条","txt":"被害人死亡的，其法定代理人、近亲属可以与犯罪嫌疑人和解。"},{"i":494,"n":"第四百九十四条","txt":"犯罪嫌疑人系限制行为能力人的，其法定代理人可以代为和解。"},{"i":495,"n":"第四百九十五条","txt":"双方当事人可以就赔偿损失、赔礼道歉等民事责任事项进行和解，并且可以就被害人及其法定代理人或者近亲属是否要求或者同意公安机关、人民检察院、人民法院对犯罪嫌疑人依法从宽处理进行协商，但不得对案件的事实认定、证据采信、法律适用和定罪量刑等依法属于公安机关、人民检察院、人民法院职权范围的事宜进行协商。"},{"i":496,"n":"第四百九十六条","txt":"双方当事人可以自行达成和解，也可以经人民调解委员会、村民委员会、居民委员会、当事人所在单位或者同事、亲友等组织或者个人调解后达成和解。"},{"i":497,"n":"第四百九十七条","txt":"人民检察院应当对和解的自愿性、合法性进行审查，重点审查以下内容："},{"i":498,"n":"第四百九十八条","txt":"经审查认为双方自愿和解，内容合法，且符合本规则第四百九十二条规定的范围和条件的，人民检察院应当主持制作和解协议书。"},{"i":499,"n":"第四百九十九条","txt":"和解协议书约定的赔偿损失内容，应当在双方签署协议后立即履行，至迟在人民检察院作出从宽处理决定前履行。确实难以一次性履行的，在提供有效担保并且被害人同意的情况下，也可以分期履行。"},{"i":500,"n":"第五百条","txt":"双方当事人在侦查阶段达成和解协议，公安机关向人民检察院提出从宽处理建议的，人民检察院在审查逮捕和审查起诉时应当充分考虑公安机关的建议。"},{"i":501,"n":"第五百零一条","txt":"人民检察院对于公安机关提请批准逮捕的案件，双方当事人达成和解协议的，可以作为有无社会危险性或者社会危险性大小的因素予以考虑。经审查认为不需要逮捕的，可以作出不批准逮捕的决定；在审查起诉阶段可以依法变更强制措施。"},{"i":502,"n":"第五百零二条","txt":"人民检察院对于公安机关移送起诉的案件，双方当事人达成和解协议的，可以作为是否需要判处刑罚或者免除刑罚的因素予以考虑。符合法律规定的不起诉条件的，可以决定不起诉。"},{"i":503,"n":"第五百零三条","txt":"人民检察院拟对当事人达成和解的公诉案件作出不起诉决定的，应当听取双方当事人对和解的意见，并且查明犯罪嫌疑人是否已经切实履行和解协议、不能即时履行的是否已经提供有效担保，将其作为是否决定不起诉的因素予以考虑。"},{"i":504,"n":"第五百零四条","txt":"犯罪嫌疑人或者其亲友等以暴力、威胁、欺骗或者其他非法方法强迫、引诱被害人和解，或者在协议履行完毕之后威胁、报复被害人的，应当认定和解协议无效。已经作出不批准逮捕或者不起诉决定的，人民检察院根据案件情况可以撤销原决定，对犯罪嫌疑人批准逮捕或者提起公诉。"},{"i":505,"n":"第五百零五条","txt":"对于监察机关移送起诉的贪污贿赂犯罪案件，犯罪嫌疑人、被告人在境外，人民检察院认为犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，可以向人民法院提起公诉。"},{"i":506,"n":"第五百零六条","txt":"人民检察院对公安机关移送起诉的需要报请最高人民检察院核准的案件，经检察委员会讨论提出提起公诉意见的，应当层报最高人民检察院核准。报送材料包括起诉意见书、案件审查报告、报请核准的报告及案件证据材料。"},{"i":507,"n":"第五百零七条","txt":"最高人民检察院收到下级人民检察院报请核准提起公诉的案卷材料后，应当及时指派检察官对案卷材料进行审查，提出核准或者不予核准的意见，报检察长决定。"},{"i":508,"n":"第五百零八条","txt":"报请核准的人民检察院收到最高人民检察院核准决定书后，应当提起公诉，起诉书中应当载明经最高人民检察院核准的内容。"},{"i":509,"n":"第五百零九条","txt":"审查起诉期间，犯罪嫌疑人自动投案或者被抓获的，人民检察院应当重新审查。"},{"i":510,"n":"第五百一十条","txt":"提起公诉后被告人到案，人民法院拟重新审理的，人民检察院应当商人民法院将案件撤回并重新审查。"},{"i":511,"n":"第五百一十一条","txt":"因被告人患有严重疾病无法出庭，中止审理超过六个月，被告人仍无法出庭，被告人及其法定代理人、近亲属申请或者同意恢复审理的，人民检察院可以建议人民法院适用缺席审判程序审理。"},{"i":512,"n":"第五百一十二条","txt":"对于贪污贿赂犯罪、恐怖活动犯罪等重大犯罪案件，犯罪嫌疑人、被告人逃匿，在通缉一年后不能到案，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以向人民法院提出没收违法所得的申请。"},{"i":513,"n":"第五百一十三条","txt":"犯罪嫌疑人、被告人为逃避侦查和刑事追究潜逃、隐匿，或者在刑事诉讼过程中脱逃的，应当认定为“逃匿”。"},{"i":514,"n":"第五百一十四条","txt":"公安机关发布通缉令或者公安部通过国际刑警组织发布红色国际通报，应当认定为“通缉”。"},{"i":515,"n":"第五百一十五条","txt":"犯罪嫌疑人、被告人通过实施犯罪直接或者间接产生、获得的任何财产，应当认定为“违法所得”。"},{"i":516,"n":"第五百一十六条","txt":"犯罪嫌疑人、被告人非法持有的违禁品、供犯罪所用的本人财物，应当认定为“其他涉案财产”。"},{"i":517,"n":"第五百一十七条","txt":"刑事诉讼法第二百九十九条第三款规定的“利害关系人”包括犯罪嫌疑人、被告人的近亲属和其他对申请没收的财产主张权利的自然人和单位。"},{"i":518,"n":"第五百一十八条","txt":"人民检察院审查监察机关或者公安机关移送的没收违法所得意见书，向人民法院提出没收违法所得的申请以及对违法所得没收程序中调查活动、审判活动的监督，由负责捕诉的部门办理。"},{"i":519,"n":"第五百一十九条","txt":"没收违法所得的申请，应当由有管辖权的中级人民法院的同级人民检察院提出。"},{"i":520,"n":"第五百二十条","txt":"人民检察院向人民法院提出没收违法所得的申请，应当制作没收违法所得申请书。没收违法所得申请书应当载明以下内容："},{"i":521,"n":"第五百二十一条","txt":"监察机关或者公安机关向人民检察院移送没收违法所得意见书，应当由有管辖权的人民检察院的同级监察机关或者公安机关移送。"},{"i":522,"n":"第五百二十二条","txt":"人民检察院审查监察机关或者公安机关移送的没收违法所得意见书，应当审查下列内容："},{"i":523,"n":"第五百二十三条","txt":"人民检察院应当在接到监察机关或者公安机关移送的没收违法所得意见书后三十日以内作出是否提出没收违法所得申请的决定。三十日以内不能作出决定的，可以延长十五日。"},{"i":524,"n":"第五百二十四条","txt":"人民检察院发现公安机关应当启动违法所得没收程序而不启动的，可以要求公安机关在七日以内书面说明不启动的理由。"},{"i":525,"n":"第五百二十五条","txt":"人民检察院发现公安机关在违法所得没收程序的调查活动中有违法情形的，应当向公安机关提出纠正意见。"},{"i":526,"n":"第五百二十六条","txt":"在审查监察机关或者公安机关移送的没收违法所得意见书的过程中，在逃的犯罪嫌疑人、被告人自动投案或者被抓获的，人民检察院应当终止审查，并将案卷退回监察机关或者公安机关处理。"},{"i":527,"n":"第五百二十七条","txt":"人民检察院直接受理侦查的案件，犯罪嫌疑人死亡而撤销案件，符合刑事诉讼法第二百九十八条第一款规定条件的，负责侦查的部门应当启动违法所得没收程序进行调查。"},{"i":528,"n":"第五百二十八条","txt":"在人民检察院审查起诉过程中，犯罪嫌疑人死亡，或者贪污贿赂犯罪、恐怖活动犯罪等重大犯罪案件的犯罪嫌疑人逃匿，在通缉一年后不能到案，依照刑法规定应当追缴其违法所得及其他涉案财产的，人民检察院可以直接提出没收违法所得的申请。"},{"i":529,"n":"第五百二十九条","txt":"人民法院对没收违法所得的申请进行审理，人民检察院应当承担举证责任。"},{"i":530,"n":"第五百三十条","txt":"出席法庭的检察官应当宣读没收违法所得申请书，并在法庭调查阶段就申请没收的财产属于违法所得及其他涉案财产等相关事实出示、宣读证据。"},{"i":531,"n":"第五百三十一条","txt":"人民检察院发现人民法院或者审判人员审理没收违法所得案件违反法律规定的诉讼程序，应当向人民法院提出纠正意见。"},{"i":532,"n":"第五百三十二条","txt":"在审理案件过程中，在逃的犯罪嫌疑人、被告人自动投案或者被抓获，人民法院按照刑事诉讼法第三百零一条第一款的规定终止审理的，人民检察院应当将案卷退回监察机关或者公安机关处理。"},{"i":533,"n":"第五百三十三条","txt":"对于刑事诉讼法第二百九十八条第一款规定以外需要没收违法所得的，按照有关规定执行。"},{"i":534,"n":"第五百三十四条","txt":"对于实施暴力行为，危害公共安全或者严重危害公民人身安全，已经达到犯罪程度，经法定程序鉴定依法不负刑事责任的精神病人，有继续危害社会可能的，人民检察院应当向人民法院提出强制医疗的申请。"},{"i":535,"n":"第五百三十五条","txt":"强制医疗的申请由被申请人实施暴力行为所在地的基层人民检察院提出；由被申请人居住地的人民检察院提出更为适宜的，可以由被申请人居住地的基层人民检察院提出。"},{"i":536,"n":"第五百三十六条","txt":"人民检察院向人民法院提出强制医疗的申请，应当制作强制医疗申请书。强制医疗申请书的主要内容包括："},{"i":537,"n":"第五百三十七条","txt":"人民检察院审查公安机关移送的强制医疗意见书，应当查明："},{"i":538,"n":"第五百三十八条","txt":"人民检察院办理公安机关移送的强制医疗案件，可以采取以下方式开展调查，调查情况应当记录并附卷："},{"i":539,"n":"第五百三十九条","txt":"人民检察院应当在接到公安机关移送的强制医疗意见书后三十日以内作出是否提出强制医疗申请的决定。"},{"i":540,"n":"第五百四十条","txt":"人民检察院发现公安机关应当启动强制医疗程序而不启动的，可以要求公安机关在七日以内书面说明不启动的理由。"},{"i":541,"n":"第五百四十一条","txt":"人民检察院对公安机关移送的强制医疗案件，发现公安机关对涉案精神病人进行鉴定违反法律规定，具有下列情形之一的，应当依法提出纠正意见："},{"i":542,"n":"第五百四十二条","txt":"人民检察院发现公安机关对涉案精神病人不应当采取临时保护性约束措施而采取的，应当提出纠正意见。"},{"i":543,"n":"第五百四十三条","txt":"在审查起诉中，犯罪嫌疑人经鉴定系依法不负刑事责任的精神病人的，人民检察院应当作出不起诉决定。认为符合刑事诉讼法第三百零二条规定条件的，应当向人民法院提出强制医疗的申请。"},{"i":544,"n":"第五百四十四条","txt":"人民法院对强制医疗案件开庭审理的，人民检察院应当派员出席法庭。"},{"i":545,"n":"第五百四十五条","txt":"人民检察院发现人民法院强制医疗案件审理活动具有下列情形之一的，应当提出纠正意见："},{"i":546,"n":"第五百四十六条","txt":"出席法庭的检察官发现人民法院或者审判人员审理强制医疗案件违反法律规定的诉讼程序，应当记录在案，并在休庭后及时向检察长报告，由人民检察院在庭审后向人民法院提出纠正意见。"},{"i":547,"n":"第五百四十七条","txt":"人民检察院认为人民法院作出的强制医疗决定或者驳回强制医疗申请的决定，具有下列情形之一的，应当在收到决定书副本后二十日以内向人民法院提出纠正意见："},{"i":548,"n":"第五百四十八条","txt":"人民法院在审理案件过程中发现被告人符合强制医疗条件，适用强制医疗程序对案件进行审理的，人民检察院应当在庭审中发表意见。"},{"i":549,"n":"第五百四十九条","txt":"人民法院收到被决定强制医疗的人、被害人及其法定代理人、近亲属复议申请后，未组成合议庭审理，或者未在一个月以内作出复议决定，或者有其他违法行为的，人民检察院应当提出纠正意见。"},{"i":550,"n":"第五百五十条","txt":"人民检察院对于人民法院批准解除强制医疗的决定实行监督，发现人民法院解除强制医疗的决定不当的，应当提出纠正意见。"},{"i":551,"n":"第五百五十一条","txt":"人民检察院对刑事诉讼活动实行法律监督，发现违法情形的，依法提出抗诉、纠正意见或者检察建议。"},{"i":552,"n":"第五百五十二条","txt":"人民检察院发现刑事诉讼活动中的违法行为，对于情节较轻的，由检察人员以口头方式提出纠正意见；对于情节较重的，经检察长决定，发出纠正违法通知书。对于带有普遍性的违法情形，经检察长决定，向相关机关提出检察建议。构成犯罪的，移送有关机关、部门依法追究刑事责任。"},{"i":553,"n":"第五百五十三条","txt":"人民检察院发出纠正违法通知书的，应当监督落实。被监督单位在纠正违法通知书规定的期限内没有回复纠正情况的，人民检察院应当督促回复。经督促被监督单位仍不回复或者没有正当理由不纠正的，人民检察院应当向上一级人民检察院报告。"},{"i":554,"n":"第五百五十四条","txt":"被监督单位对纠正意见申请复查的，人民检察院应当在收到被监督单位的书面意见后七日以内进行复查，并将复查结果及时通知申请复查的单位。经过复查，认为纠正意见正确的，应当及时向上一级人民检察院报告；认为纠正意见错误的，应当及时予以撤销。"},{"i":555,"n":"第五百五十五条","txt":"当事人和辩护人、诉讼代理人、利害关系人对于办案机关及其工作人员有刑事诉讼法第一百一十七条规定的行为，向该机关申诉或者控告，对该机关作出的处理不服或者该机关未在规定时间内作出答复，而向人民检察院申诉的，办案机关的同级人民检察院应当受理。"},{"i":556,"n":"第五百五十六条","txt":"对人民检察院及其工作人员办理案件中违法行为的申诉、控告，由负责控告申诉检察的部门受理和审查办理。对其他司法机关处理决定不服向人民检察院提出的申诉，由负责控告申诉检察的部门受理后，移送相关办案部门审查办理。"},{"i":557,"n":"第五百五十七条","txt":"被害人及其法定代理人、近亲属或者行政执法机关，认为公安机关对其控告或者移送的案件应当立案侦查而不立案侦查，或者当事人认为公安机关不应当立案而立案，向人民检察院提出的，人民检察院应当受理并进行审查。"},{"i":558,"n":"第五百五十八条","txt":"人民检察院负责控告申诉检察的部门受理对公安机关应当立案而不立案或者不应当立案而立案的控告、申诉，应当根据事实、法律进行审查。认为需要公安机关说明不立案或者立案理由的，应当及时将案件移送负责捕诉的部门办理；认为公安机关立案或者不立案决定正确的，应当制作相关法律文书，答复控告人、申诉人。"},{"i":559,"n":"第五百五十九条","txt":"人民检察院经审查，认为需要公安机关说明不立案理由的，应当要求公安机关书面说明不立案的理由。"},{"i":560,"n":"第五百六十条","txt":"人民检察院要求公安机关说明不立案或者立案理由，应当书面通知公安机关，并且告知公安机关在收到通知后七日以内，书面说明不立案或者立案的情况、依据和理由，连同有关证据材料回复人民检察院。"},{"i":561,"n":"第五百六十一条","txt":"公安机关说明不立案或者立案的理由后，人民检察院应当进行审查。认为公安机关不立案或者立案理由不能成立的，经检察长决定，应当通知公安机关立案或者撤销案件。"},{"i":562,"n":"第五百六十二条","txt":"公安机关对当事人的报案、控告、举报或者行政执法机关移送的涉嫌犯罪案件受理后未在规定期限内作出是否立案决定，当事人或者行政执法机关向人民检察院提出的，人民检察院应当受理并进行审查。经审查，认为尚未超过规定期限的，应当移送公安机关处理，并答复报案人、控告人、举报人或者行政执法机关；认为超过规定期限的，应当要求公安机关在七日以内书面说明逾期不作出是否立案决定的理由，连同有关证据材料回复人民检察院。公安机关在七日以内不说明理由也不作出立案或者不立案决定的，人民检察院应当提出纠正意见。人民检察院经审查有关证据材料认为符合立案条件的，应当通知公安机关立案。"},{"i":563,"n":"第五百六十三条","txt":"人民检察院通知公安机关立案或者撤销案件，应当制作通知立案书或者通知撤销案件书，说明依据和理由，连同证据材料送达公安机关，并且告知公安机关应当在收到通知立案书后十五日以内立案，对通知撤销案件书没有异议的应当立即撤销案件，并将立案决定书或者撤销案件决定书及时送达人民检察院。"},{"i":564,"n":"第五百六十四条","txt":"人民检察院通知公安机关立案或者撤销案件的，应当依法对执行情况进行监督。"},{"i":565,"n":"第五百六十五条","txt":"公安机关认为人民检察院撤销案件通知有错误，要求同级人民检察院复议的，人民检察院应当重新审查。在收到要求复议意见书和案卷材料后七日以内作出是否变更的决定，并通知公安机关。"},{"i":566,"n":"第五百六十六条","txt":"人民检察院负责捕诉的部门发现本院负责侦查的部门对应当立案侦查的案件不立案侦查或者对不应当立案侦查的案件立案侦查的，应当建议负责侦查的部门立案侦查或者撤销案件。建议不被采纳的，应当报请检察长决定。"},{"i":567,"n":"第五百六十七条","txt":"人民检察院应当对侦查活动中是否存在以下违法行为进行监督："},{"i":568,"n":"第五百六十八条","txt":"人民检察院发现侦查活动中的违法情形已涉嫌犯罪，属于人民检察院管辖的，依法立案侦查；不属于人民检察院管辖的，依照有关规定移送有管辖权的机关。"},{"i":569,"n":"第五百六十九条","txt":"人民检察院负责捕诉的部门发现本院负责侦查的部门在侦查活动中有违法情形，应当提出纠正意见。需要追究相关人员违法违纪责任的，应当报告检察长。"},{"i":570,"n":"第五百七十条","txt":"人民检察院应当对审判活动中是否存在以下违法行为进行监督："},{"i":571,"n":"第五百七十一条","txt":"人民检察院检察长或者检察长委托的副检察长，可以列席同级人民法院审判委员会会议，依法履行法律监督职责。"},{"i":572,"n":"第五百七十二条","txt":"人民检察院在审判活动监督中，发现人民法院或者审判人员审理案件违反法律规定的诉讼程序，应当向人民法院提出纠正意见。"},{"i":573,"n":"第五百七十三条","txt":"犯罪嫌疑人、被告人被逮捕后，人民检察院仍应当对羁押的必要性进行审查。"},{"i":574,"n":"第五百七十四条","txt":"人民检察院在办案过程中可以依职权主动进行羁押必要性审查。"},{"i":575,"n":"第五百七十五条","txt":"负责捕诉的部门依法对侦查和审判阶段的羁押必要性进行审查。经审查认为不需要继续羁押的，应当建议公安机关或者人民法院释放犯罪嫌疑人、被告人或者变更强制措施。"},{"i":576,"n":"第五百七十六条","txt":"办案机关对应的同级人民检察院负责控告申诉检察的部门或者负责案件管理的部门收到羁押必要性审查申请后，应当在当日移送本院负责捕诉的部门。"},{"i":577,"n":"第五百七十七条","txt":"人民检察院可以采取以下方式进行羁押必要性审查："},{"i":578,"n":"第五百七十八条","txt":"人民检察院应当根据犯罪嫌疑人、被告人涉嫌的犯罪事实、主观恶性、悔罪表现、身体状况、案件进展情况、可能判处的刑罚和有无再危害社会的危险等因素，综合评估有无必要继续羁押犯罪嫌疑人、被告人。"},{"i":579,"n":"第五百七十九条","txt":"人民检察院发现犯罪嫌疑人、被告人具有下列情形之一的，应当向办案机关提出释放或者变更强制措施的建议："},{"i":580,"n":"第五百八十条","txt":"人民检察院发现犯罪嫌疑人、被告人具有下列情形之一，且具有悔罪表现，不予羁押不致发生社会危险性的，可以向办案机关提出释放或者变更强制措施的建议："},{"i":581,"n":"第五百八十一条","txt":"人民检察院向办案机关发出释放或者变更强制措施建议书的，应当说明不需要继续羁押犯罪嫌疑人、被告人的理由和法律依据，并要求办案机关在十日以内回复处理情况。"},{"i":582,"n":"第五百八十二条","txt":"对于依申请审查的案件，人民检察院办结后，应当将提出建议的情况和公安机关、人民法院的处理情况，或者有继续羁押必要的审查意见和理由及时书面告知申请人。"},{"i":583,"n":"第五百八十三条","txt":"人民检察院依法对人民法院的判决、裁定是否正确实行法律监督，对人民法院确有错误的判决、裁定，应当依法提出抗诉。"},{"i":584,"n":"第五百八十四条","txt":"人民检察院认为同级人民法院第一审判决、裁定具有下列情形之一的，应当提出抗诉："},{"i":585,"n":"第五百八十五条","txt":"人民检察院在收到人民法院第一审判决书或者裁定书后，应当及时审查。对于需要提出抗诉的案件，应当报请检察长决定。"},{"i":586,"n":"第五百八十六条","txt":"人民检察院对同级人民法院第一审判决的抗诉，应当在接到判决书后第二日起十日以内提出；对第一审裁定的抗诉，应当在接到裁定书后第二日起五日以内提出。"},{"i":587,"n":"第五百八十七条","txt":"人民检察院对同级人民法院第一审判决、裁定的抗诉，应当制作抗诉书，通过原审人民法院向上一级人民法院提出，并将抗诉书副本连同案卷材料报送上一级人民检察院。"},{"i":588,"n":"第五百八十八条","txt":"被害人及其法定代理人不服地方各级人民法院第一审的判决，在收到判决书后五日以内请求人民检察院提出抗诉的，人民检察院应当立即进行审查，在收到被害人及其法定代理人的请求后五日以内作出是否抗诉的决定，并且答复请求人。经审查认为应当抗诉的，适用本规则第五百八十四条至第五百八十七条的规定办理。"},{"i":589,"n":"第五百八十九条","txt":"上一级人民检察院对下级人民检察院按照第二审程序提出抗诉的案件，认为抗诉正确的，应当支持抗诉。"},{"i":590,"n":"第五百九十条","txt":"第二审人民法院发回原审人民法院按照第一审程序重新审判的案件，如果人民检察院认为重新审判的判决、裁定确有错误的，可以按照第二审程序提出抗诉。"},{"i":591,"n":"第五百九十一条","txt":"人民检察院认为人民法院已经发生法律效力的判决、裁定确有错误，具有下列情形之一的，应当按照审判监督程序向人民法院提出抗诉："},{"i":592,"n":"第五百九十二条","txt":"对于高级人民法院判处死刑缓期二年执行的案件，省级人民检察院认为确有错误提请抗诉的，一般应当在收到生效判决、裁定后三个月以内提出，至迟不得超过六个月。"},{"i":593,"n":"第五百九十三条","txt":"当事人及其法定代理人、近亲属认为人民法院已经发生法律效力的判决、裁定确有错误，向人民检察院申诉的，由作出生效判决、裁定的人民法院的同级人民检察院依法办理。"},{"i":594,"n":"第五百九十四条","txt":"对不服人民法院已经发生法律效力的判决、裁定的申诉，经两级人民检察院办理且省级人民检察院已经复查的，如果没有新的证据，人民检察院不再复查，但原审被告人可能被宣告无罪或者判决、裁定有其他重大错误可能的除外。"},{"i":595,"n":"第五百九十五条","txt":"人民检察院对已经发生法律效力的判决、裁定的申诉复查后，认为需要提请或者提出抗诉的，报请检察长决定。"},{"i":596,"n":"第五百九十六条","txt":"人民检察院对不服人民法院已经发生法律效力的判决、裁定的申诉案件复查终结后，应当制作刑事申诉复查通知书，在十日以内通知申诉人。"},{"i":597,"n":"第五百九十七条","txt":"最高人民检察院发现各级人民法院已经发生法律效力的判决或者裁定，上级人民检察院发现下级人民法院已经发生法律效力的判决或者裁定确有错误时，可以直接向同级人民法院提出抗诉，或者指令作出生效判决、裁定人民法院的上一级人民检察院向同级人民法院提出抗诉。"},{"i":598,"n":"第五百九十八条","txt":"人民检察院按照审判监督程序向人民法院提出抗诉的，应当将抗诉书副本报送上一级人民检察院。"},{"i":599,"n":"第五百九十九条","txt":"对按照审判监督程序提出抗诉的案件，人民检察院认为人民法院再审作出的判决、裁定仍然确有错误的，如果案件是依照第一审程序审判的，同级人民检察院应当按照第二审程序向上一级人民法院提出抗诉；如果案件是依照第二审程序审判的，上一级人民检察院应当按照审判监督程序向同级人民法院提出抗诉。"},{"i":600,"n":"第六百条","txt":"人民检察院办理按照第二审程序、审判监督程序抗诉的案件，认为需要对被告人采取强制措施的，参照本规则相关规定。决定采取强制措施应当经检察长批准。"},{"i":601,"n":"第六百零一条","txt":"人民检察院对自诉案件的判决、裁定的监督，适用本节的规定。"},{"i":602,"n":"第六百零二条","txt":"最高人民检察院依法对最高人民法院的死刑复核活动实行法律监督。"},{"i":603,"n":"第六百零三条","txt":"最高人民检察院、省级人民检察院通过办理下列案件对死刑复核活动实行法律监督："},{"i":604,"n":"第六百零四条","txt":"省级人民检察院对于进入最高人民法院死刑复核程序的案件，发现具有下列情形之一的，应当及时向最高人民检察院提请监督："},{"i":605,"n":"第六百零五条","txt":"省级人民检察院发现死刑复核案件被告人有自首、立功、怀孕或者被告人家属与被害人家属达成赔偿谅解协议等新的重大情况，影响死刑适用的，应当及时向最高人民检察院报告。"},{"i":606,"n":"第六百零六条","txt":"当事人及其近亲属或者受委托的律师向最高人民检察院提出不服死刑裁判的申诉，由负责死刑复核监督的部门审查。"},{"i":607,"n":"第六百零七条","txt":"对于适用死刑存在较大分歧或者在全国有重大影响的死刑第二审案件，省级人民检察院应当及时报最高人民检察院备案。"},{"i":608,"n":"第六百零八条","txt":"高级人民法院死刑复核期间，设区的市级人民检察院向省级人民检察院报告重大情况、备案等程序，参照本规则第六百零五条、第六百零七条规定办理。"},{"i":609,"n":"第六百零九条","txt":"对死刑复核监督案件的审查可以采取下列方式："},{"i":610,"n":"第六百一十条","txt":"审查死刑复核监督案件，具有下列情形之一的，应当听取下级人民检察院的意见："},{"i":611,"n":"第六百一十一条","txt":"最高人民检察院经审查发现死刑复核案件具有下列情形之一的，应当经检察长决定，依法向最高人民法院提出检察意见："},{"i":612,"n":"第六百一十二条","txt":"人民检察院依法对羁押期限和办案期限是否合法实行法律监督。"},{"i":613,"n":"第六百一十三条","txt":"对公安机关、人民法院办理案件相关期限的监督，犯罪嫌疑人、被告人被羁押的，由人民检察院负责刑事执行检察的部门承担；犯罪嫌疑人、被告人未被羁押的，由人民检察院负责捕诉的部门承担。对人民检察院办理案件相关期限的监督，由负责案件管理的部门承担。"},{"i":614,"n":"第六百一十四条","txt":"人民检察院在办理案件过程中，犯罪嫌疑人、被告人被羁押，具有下列情形之一的，办案部门应当在作出决定或者收到决定书、裁定书后十日以内通知本院负有监督职责的部门："},{"i":615,"n":"第六百一十五条","txt":"人民检察院发现看守所的羁押期限管理活动具有下列情形之一的，应当依法提出纠正意见："},{"i":616,"n":"第六百一十六条","txt":"人民检察院发现公安机关的侦查羁押期限执行情况具有下列情形之一的，应当依法提出纠正意见："},{"i":617,"n":"第六百一十七条","txt":"人民检察院发现人民法院的审理期限执行情况具有下列情形之一的，应当依法提出纠正意见："},{"i":618,"n":"第六百一十八条","txt":"人民检察院发现同级或者下级公安机关、人民法院超期羁押的，应当向该办案机关发出纠正违法通知书。"},{"i":619,"n":"第六百一十九条","txt":"人民检察院发出纠正违法通知书后，有关办案机关未回复意见或者继续超期羁押的，应当及时报告上一级人民检察院。"},{"i":620,"n":"第六百二十条","txt":"人民检察院办理直接受理侦查的案件或者审查逮捕、审查起诉案件，在犯罪嫌疑人侦查羁押期限、办案期限即将届满前，负责案件管理的部门应当依照有关规定向本院办案部门进行期限届满提示。发现办案部门办理案件超过规定期限的，应当依照有关规定提出纠正意见。"},{"i":621,"n":"第六百二十一条","txt":"人民检察院依法对刑事判决、裁定和决定的执行工作以及监狱、看守所等的监管执法活动实行法律监督。"},{"i":622,"n":"第六百二十二条","txt":"人民检察院根据工作需要，可以对监狱、看守所等场所采取巡回检察、派驻检察等方式进行监督。"},{"i":623,"n":"第六百二十三条","txt":"人民检察院对监狱、看守所等场所进行监督，除可以采取本规则第五百五十一条规定的调查核实措施外，还可以采取实地查看禁闭室、会见室、监区、监舍等有关场所，列席监狱、看守所有关会议，与有关监管民警进行谈话，召开座谈会，开展问卷调查等方式。"},{"i":624,"n":"第六百二十四条","txt":"人民检察院对刑罚执行和监管执法活动实行监督，可以根据下列情形分别处理："},{"i":625,"n":"第六百二十五条","txt":"人民检察院发现人民法院、公安机关、看守所等机关的交付执行活动具有下列情形之一的，应当依法提出纠正意见："},{"i":626,"n":"第六百二十六条","txt":"人民法院判决被告人无罪、免予刑事处罚、判处管制、宣告缓刑、单处罚金或者剥夺政治权利，被告人被羁押的，人民检察院应当监督被告人是否被立即释放。发现被告人没有被立即释放的，应当立即向人民法院或者看守所提出纠正意见。"},{"i":627,"n":"第六百二十七条","txt":"人民检察院发现公安机关未依法执行拘役、剥夺政治权利，拘役执行期满未依法发给释放证明，或者剥夺政治权利执行期满未书面通知本人及其所在单位、居住地基层组织等违法情形的，应当依法提出纠正意见。"},{"i":628,"n":"第六百二十八条","txt":"人民检察院发现监狱、看守所对服刑期满或者依法应当予以释放的人员没有按期释放，对被裁定假释的罪犯依法应当交付罪犯居住地社区矫正机构实行社区矫正而不交付，对主刑执行完毕仍然需要执行附加剥夺政治权利的罪犯依法应当交付罪犯居住地公安机关执行而不交付，或者对服刑期未满又无合法释放根据的罪犯予以释放等违法行为的，应当依法提出纠正意见。"},{"i":629,"n":"第六百二十九条","txt":"人民检察院发现人民法院、监狱、看守所、公安机关暂予监外执行的活动具有下列情形之一的，应当依法提出纠正意见："},{"i":630,"n":"第六百三十条","txt":"人民检察院收到监狱、看守所抄送的暂予监外执行书面意见副本后，应当逐案进行审查，发现罪犯不符合暂予监外执行法定条件或者提请暂予监外执行违反法定程序的，应当在十日以内报经检察长批准，向决定或者批准机关提出书面检察意见，同时抄送执行机关。"},{"i":631,"n":"第六百三十一条","txt":"人民检察院接到决定或者批准机关抄送的暂予监外执行决定书后，应当及时审查下列内容："},{"i":632,"n":"第六百三十二条","txt":"人民检察院经审查认为暂予监外执行不当的，应当自接到通知之日起一个月以内，向决定或者批准暂予监外执行的机关提出纠正意见。下级人民检察院认为暂予监外执行不当的，应当立即层报决定或者批准暂予监外执行的机关的同级人民检察院，由其决定是否向决定或者批准暂予监外执行的机关提出纠正意见。"},{"i":633,"n":"第六百三十三条","txt":"人民检察院向决定或者批准暂予监外执行的机关提出不同意暂予监外执行的书面意见后，应当监督其对决定或者批准暂予监外执行的结果进行重新核查，并监督重新核查的结果是否符合法律规定。对核查不符合法律规定的，应当依法提出纠正意见，并向上一级人民检察院报告。"},{"i":634,"n":"第六百三十四条","txt":"对于暂予监外执行的罪犯，人民检察院发现罪犯不符合暂予监外执行条件、严重违反有关暂予监外执行的监督管理规定或者暂予监外执行的情形消失而罪犯刑期未满的，应当通知执行机关收监执行，或者建议决定或者批准暂予监外执行的机关作出收监执行决定。"},{"i":635,"n":"第六百三十五条","txt":"人民检察院收到执行机关抄送的减刑、假释建议书副本后，应当逐案进行审查。发现减刑、假释建议不当或者提请减刑、假释违反法定程序的，应当在十日以内报经检察长批准，向审理减刑、假释案件的人民法院提出书面检察意见，同时也可以向执行机关提出书面纠正意见。案情复杂或者情况特殊的，可以延长十日。"},{"i":636,"n":"第六百三十六条","txt":"人民检察院发现监狱等执行机关提请人民法院裁定减刑、假释的活动具有下列情形之一的，应当依法提出纠正意见："},{"i":637,"n":"第六百三十七条","txt":"人民法院开庭审理减刑、假释案件，人民检察院应当指派检察人员出席法庭，发表意见。"},{"i":638,"n":"第六百三十八条","txt":"人民检察院收到人民法院减刑、假释的裁定书副本后，应当及时审查下列内容："},{"i":639,"n":"第六百三十九条","txt":"人民检察院经审查认为人民法院减刑、假释的裁定不当，应当在收到裁定书副本后二十日以内，向作出减刑、假释裁定的人民法院提出纠正意见。"},{"i":640,"n":"第六百四十条","txt":"对人民法院减刑、假释裁定的纠正意见，由作出减刑、假释裁定的人民法院的同级人民检察院书面提出。"},{"i":641,"n":"第六百四十一条","txt":"人民检察院对人民法院减刑、假释的裁定提出纠正意见后，应当监督人民法院是否在收到纠正意见后一个月以内重新组成合议庭进行审理，并监督重新作出的裁定是否符合法律规定。对最终裁定不符合法律规定的，应当向同级人民法院提出纠正意见。"},{"i":642,"n":"第六百四十二条","txt":"人民检察院发现社区矫正决定机关、看守所、监狱、社区矫正机构在交付、接收社区矫正对象活动中违反有关规定的，应当依法提出纠正意见。"},{"i":643,"n":"第六百四十三条","txt":"人民检察院发现社区矫正执法活动具有下列情形之一的，应当依法提出纠正意见："},{"i":644,"n":"第六百四十四条","txt":"人民检察院发现对社区矫正对象的刑罚变更执行活动具有下列情形之一的，应当依法提出纠正意见："},{"i":645,"n":"第六百四十五条","txt":"人民检察院发现人民法院执行刑事裁判涉财产部分具有下列情形之一的，应当依法提出纠正意见："},{"i":646,"n":"第六百四十六条","txt":"人民检察院发现被执行人或者其他人员有隐匿、转移、变卖财产等妨碍执行情形的，可以建议人民法院及时查封、扣押、冻结。"},{"i":647,"n":"第六百四十七条","txt":"被判处死刑立即执行的罪犯在被执行死刑时，人民检察院应当指派检察官临场监督。"},{"i":648,"n":"第六百四十八条","txt":"省级人民检察院负责案件管理的部门收到高级人民法院报请最高人民法院复核的死刑判决书、裁定书副本后，应当在三日以内将判决书、裁定书副本移送本院负责刑事执行检察的部门。"},{"i":649,"n":"第六百四十九条","txt":"执行死刑前，人民检察院发现具有下列情形之一的，应当建议人民法院立即停止执行，并层报最高人民检察院负责死刑复核监督的部门："},{"i":650,"n":"第六百五十条","txt":"判处被告人死刑缓期二年执行的判决、裁定在执行过程中，人民检察院监督的内容主要包括："},{"i":651,"n":"第六百五十一条","txt":"人民检察院发现人民法院、公安机关、强制医疗机构在对依法不负刑事责任的精神病人的强制医疗的交付执行、医疗、解除等活动中违反有关规定的，应当依法提出纠正意见。"},{"i":652,"n":"第六百五十二条","txt":"人民检察院在强制医疗执行监督中发现被强制医疗的人不符合强制医疗条件或者需要依法追究刑事责任，人民法院作出的强制医疗决定可能错误的，应当在五日以内将有关材料转交作出强制医疗决定的人民法院的同级人民检察院。收到材料的人民检察院负责捕诉的部门应当在二十日以内进行审查，并将审查情况和处理意见反馈负责强制医疗执行监督的人民检察院。"},{"i":653,"n":"第六百五十三条","txt":"人民检察院发现公安机关在对涉案精神病人采取临时保护性约束措施时有违法情形的，应当依法提出纠正意见。"},{"i":654,"n":"第六百五十四条","txt":"人民检察院发现看守所收押活动和监狱收监活动中具有下列情形之一的，应当依法提出纠正意见："},{"i":655,"n":"第六百五十五条","txt":"人民检察院发现监狱、看守所等执行机关在管理、教育改造罪犯等活动中有违法行为的，应当依法提出纠正意见。"},{"i":656,"n":"第六百五十六条","txt":"看守所对收押的犯罪嫌疑人进行身体检查时，人民检察院驻看守所检察人员可以在场。发现收押的犯罪嫌疑人有伤或者身体异常的，应当要求看守所进行拍照或者录像，由送押人员、犯罪嫌疑人说明原因，在体检记录中写明，并由送押人员、收押人员和犯罪嫌疑人签字确认。必要时，驻看守所检察人员可以自行拍照或者录像，并将相关情况记录在案。"},{"i":657,"n":"第六百五十七条","txt":"人民检察院发现看守所、监狱等监管场所有殴打、体罚、虐待、违法使用戒具、违法适用禁闭等侵害在押人员人身权利情形的，应当依法提出纠正意见。"},{"i":658,"n":"第六百五十八条","txt":"人民检察院发现看守所违反有关规定，有下列情形之一的，应当依法提出纠正意见："},{"i":659,"n":"第六百五十九条","txt":"人民检察院发现看守所代为执行刑罚的活动具有下列情形之一的，应当依法提出纠正意见："},{"i":660,"n":"第六百六十条","txt":"人民检察院发现监狱没有按照规定对罪犯进行分押分管、监狱人民警察没有对罪犯实行直接管理等违反监管规定情形的，应当依法提出纠正意见。"},{"i":661,"n":"第六百六十一条","txt":"人民检察院发现看守所出所活动和监狱出监活动具有下列情形之一的，应当依法提出纠正意见："},{"i":662,"n":"第六百六十二条","txt":"人民检察院发现看守所、监狱、强制医疗机构等场所具有下列情形之一的，应当开展事故检察："},{"i":663,"n":"第六百六十三条","txt":"人民检察院应当对看守所、监狱、强制医疗机构等场所或者主管机关的事故调查结论进行审查。具有下列情形之一的，人民检察院应当调查核实："},{"i":664,"n":"第六百六十四条","txt":"人民检察院负责案件管理的部门对检察机关办理案件的受理、期限、程序、质量等进行管理、监督、预警。"},{"i":665,"n":"第六百六十五条","txt":"人民检察院负责案件管理的部门发现本院办案活动具有下列情形之一的，应当及时提出纠正意见："},{"i":666,"n":"第六百六十六条","txt":"人民检察院负责案件管理的部门对以本院名义制发法律文书实施监督管理。"},{"i":667,"n":"第六百六十七条","txt":"人民检察院办理的案件，办结后需要向其他单位移送案卷材料的，统一由负责案件管理的部门审核移送材料是否规范、齐备。负责案件管理的部门认为材料规范、齐备，符合移送条件的，应当立即由办案部门按照规定移送；认为材料不符合要求的，应当及时通知办案部门补送、更正。"},{"i":668,"n":"第六百六十八条","txt":"监察机关或者公安机关随案移送涉案财物及其孳息的，人民检察院负责案件管理的部门应当在受理案件时进行审查，并及时办理入库保管手续。"},{"i":669,"n":"第六百六十九条","txt":"人民检察院负责案件管理的部门对扣押的涉案物品进行保管，并对查封、扣押、冻结、处理涉案财物工作进行监督管理。对违反规定的行为提出纠正意见；涉嫌违法违纪的，报告检察长。"},{"i":670,"n":"第六百七十条","txt":"人民检察院办案部门需要调用、移送、处理查封、扣押、冻结的涉案财物的，应当按照规定办理审批手续。审批手续齐全的，负责案件管理的部门应当办理出库手续。"},{"i":671,"n":"第六百七十一条","txt":"人民检察院依据国际刑事司法协助法等有关法律和有关刑事司法协助条约进行刑事司法协助。"},{"i":672,"n":"第六百七十二条","txt":"人民检察院刑事司法协助的范围包括刑事诉讼文书送达，调查取证，安排证人作证或者协助调查，查封、扣押、冻结涉案财物，返还违法所得及其他涉案财物，移管被判刑人以及其他协助。"},{"i":673,"n":"第六百七十三条","txt":"最高人民检察院是检察机关开展国际刑事司法协助的主管机关，负责审核地方各级人民检察院向外国提出的刑事司法协助请求，审查处理对外联系机关转递的外国提出的刑事司法协助请求，审查决定是否批准执行外国的刑事司法协助请求，承担其他与国际刑事司法协助相关的工作。"},{"i":674,"n":"第六百七十四条","txt":"地方各级人民检察院需要向外国请求刑事司法协助的，应当制作刑事司法协助请求书并附相关材料。经省级人民检察院审核同意后，报送最高人民检察院。"},{"i":675,"n":"第六百七十五条","txt":"最高人民检察院收到地方各级人民检察院刑事司法协助请求书及所附相关材料后，应当依照国际刑事司法协助法和有关条约进行审查。对符合规定、所附材料齐全的，最高人民检察院是对外联系机关的，应当及时向外国提出请求；不是对外联系机关的，应当通过对外联系机关向外国提出请求。对不符合规定或者材料不齐全的，应当退回提出请求的人民检察院或者要求其补充、修正。"},{"i":676,"n":"第六百七十六条","txt":"最高人民检察院收到外国提出的刑事司法协助请求后，应当对请求书及所附材料进行审查。对于请求书形式和内容符合要求的，应当按照职责分工，将请求书及所附材料转交有关主管机关或者省级人民检察院处理；对于请求书形式和内容不符合要求的，可以要求请求方补充材料或者重新提出请求。"},{"i":677,"n":"第六百七十七条","txt":"最高人民检察院在收到对外联系机关转交的刑事司法协助请求书及所附材料后，经审查，分别作出以下处理："},{"i":678,"n":"第六百七十八条","txt":"有关省级人民检察院收到最高人民检察院交办的外国刑事司法协助请求后，应当依法执行，或者交由下级人民检察院执行。"},{"i":679,"n":"第六百七十九条","txt":"最高人民检察院应当对执行结果进行审查。对于符合请求要求和有关规定的，通过对外联系机关转交或者转告请求方。"},{"i":680,"n":"第六百八十条","txt":"人民检察院办理国家安全机关、海警机关、监狱移送的刑事案件以及对国家安全机关、海警机关、监狱立案、侦查活动的监督，适用本规则关于公安机关的规定。"},{"i":681,"n":"第六百八十一条","txt":"军事检察院等专门人民检察院办理刑事案件，适用本规则和其他有关规定。"},{"i":682,"n":"第六百八十二条","txt":"本规则所称检察官，包括检察长、副检察长、检察委员会委员、检察员。"},{"i":683,"n":"第六百八十三条","txt":"本规则由最高人民检察院负责解释。"},{"i":684,"n":"第六百八十四条","txt":"本规则自2019年12月30日起施行。本规则施行后，《人民检察院刑事诉讼规则（试行）》（高检发释字〔2012〕2号）同时废止；最高人民检察院以前发布的司法解释和规范性文件与本规则不一致的，以本规则为准。"}],"renminjianchayuanjianchaweiyuanhuigongzuoguize":[{"i":1,"n":"第一条","txt":"为了规范人民检察院检察委员会工作，保障检察委员会依法履行职责，根据《中华人民共和国人民检察院组织法》《中华人民共和国检察官法》等有关法律规定，结合检察工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"检察委员会是人民检察院的办案组织和重大业务工作议事决策机构。"},{"i":3,"n":"第三条","txt":"检察委员会讨论决定案件和事项实行民主集中制。"},{"i":4,"n":"第四条","txt":"检察委员会履行下列职能："},{"i":5,"n":"第五条","txt":"检察委员会由检察长、副检察长和若干资深检察官组成，成员应当为单数，并设专职委员。"},{"i":6,"n":"第六条","txt":"担任检察委员会委员的资深检察官应当具备以下条件："},{"i":7,"n":"第七条","txt":"检察委员会委员履行下列职责："},{"i":8,"n":"第八条","txt":"人民检察院办理下列案件，应当提交检察委员会讨论决定："},{"i":9,"n":"第九条","txt":"人民检察院办理下列事项，应当提交检察委员会讨论决定："},{"i":10,"n":"第十条","txt":"检察委员会实行例会制，定期开会。必要时，可以提前或者推迟召开会议。"},{"i":11,"n":"第十一条","txt":"检察委员会召开会议，应当有全体委员半数以上出席。"},{"i":12,"n":"第十二条","txt":"对于拟提交检察委员会讨论决定的案件和事项，办案检察官和事项承办人应当制作报告，经其所在内设机构负责人审核后报检察长决定。"},{"i":13,"n":"第十三条","txt":"检察长决定将案件和事项提交检察委员会讨论的，检察委员会办事机构应当对办案检察官或者事项承办人移送的案件材料和事项材料进行审核，认为案件、事项及其报告的内容和形式不符合相关规定或者欠缺有关材料的，应当提出意见，由办案检察官或者事项承办人修改、补充。办事机构可以对案件和事项涉及的法律问题提出意见，供办案检察官或者事项承办人参考，并作为附件编入会议材料。"},{"i":14,"n":"第十四条","txt":"检察委员会办事机构应当根据会议排期或者案件、事项紧迫程度，提出会议议程建议，报检察长决定。除特殊情况外，一般应当在会议召开三日前将会议通知、议程和案件材料或者事项材料等分送检察委员会委员、列席会议的人员和办案检察官或者事项承办人。"},{"i":15,"n":"第十五条","txt":"检察委员会委员接到会议通知和议程后，应当认真审阅案件材料或者事项材料，准备意见，按时出席会议。"},{"i":16,"n":"第十六条","txt":"检察委员会会议由检察长主持。检察长因故不能出席的，应当委托一名副检察长主持；出现检察长职位空缺等不能委托情形的，由分管人民检察院日常工作的副检察长主持。"},{"i":17,"n":"第十七条","txt":"检察委员会讨论决定案件和事项，按照以下程序进行："},{"i":18,"n":"第十八条","txt":"检察委员会委员应当围绕讨论决定的案件和事项发表意见，提出明确的观点，并说明理由和依据。"},{"i":19,"n":"第十九条","txt":"检察长、副检察长、检察委员会专职委员作为主办检察官或者独任检察官承办的案件或者事项提交检察委员会讨论的，应当履行办案检察官或者事项承办人和检察委员会委员的双重职责。"},{"i":20,"n":"第二十条","txt":"对于提交讨论决定的案件和事项，检察委员会应当在讨论后进行表决。认为需要补充相关情况和材料的，可以责成办案检察官或者事项承办人补充相关情况和材料后，重新提交检察委员会讨论决定。"},{"i":21,"n":"第二十一条","txt":"检察委员会表决案件和事项，除分别依照本规则第二十二条或者第二十三条的规定办理外，应当按照全体委员过半数的意见作出决定。少数委员的意见应当记录在卷。"},{"i":22,"n":"第二十二条","txt":"地方各级人民检察院检察长不同意本院检察委员会全体委员过半数的意见，属于办理案件的，可以报请上一级人民检察院决定；属于重大事项的，可以报请上一级人民检察院或者本级人民代表大会常务委员会决定。报请本级人民代表大会常务委员会决定的，应当同时抄报上一级人民检察院。"},{"i":23,"n":"第二十三条","txt":"地方各级人民检察院检察委员会表决案件和事项，没有一种意见超过全体委员半数，如果全体委员出席会议的，应当报请上一级人民检察院决定。如果部分委员出席会议的，应当书面征求未出席会议委员的意见。征求意见后，应当按照全体委员过半数的意见作出决定，或者依照本规则第二十二条的规定办理；仍没有一种意见超过全体委员半数的，应当报请上一级人民检察院决定。"},{"i":24,"n":"第二十四条","txt":"受委托主持会议的副检察长应当在会后将会议讨论情况和表决结果及时报告检察长。报告检察长后，依照本规则第二十一条的规定办理。"},{"i":25,"n":"第二十五条","txt":"检察委员会讨论决定案件和事项，副检察长、检察委员会委员具有应当回避的情形的，应当申请回避并由检察长决定；本人没有申请回避的，检察长应当决定其回避。"},{"i":26,"n":"第二十六条","txt":"检察委员会召开会议，经检察长决定，不担任检察委员会委员的院领导和有关内设机构负责人可以列席会议；必要时，可以决定其他有关人员列席会议。"},{"i":27,"n":"第二十七条","txt":"检察委员会讨论和决定的情况，由检察委员会办事机构进行录音录像并如实记录，经检察长审批后存档。检察委员会委员不得要求或者自行在会议记录上修改已发表的意见和观点。"},{"i":28,"n":"第二十八条","txt":"检察委员会讨论案件和事项，检察委员会办事机构应当制作会议纪要和检察委员会决定事项通知书。纪要经检察长或者主持会议的副检察长审批后分送委员，并报上一级人民检察院检察委员会办事机构备案。检察委员会决定事项通知书发办案检察官或者事项承办人和有关内设机构执行。"},{"i":29,"n":"第二十九条","txt":"检察委员会的决定，办案检察官或者事项承办人和有关内设机构、下级人民检察院应当及时执行。"},{"i":30,"n":"第三十条","txt":"办案检察官或者事项承办人和有关内设机构因特殊原因无法及时执行检察委员会决定或者在执行完毕前出现新情况的，应当立即书面报告检察长。"},{"i":31,"n":"第三十一条","txt":"下级人民检察院不同意上级人民检察院检察委员会决定的，可以向上级人民检察院书面报告，但是不能停止对该决定的执行。"},{"i":32,"n":"第三十二条","txt":"办案检察官或者事项承办人应当在执行检察委员会决定完毕后五日以内填写《检察委员会决定事项执行情况反馈表》，连同反映执行情况、案件办理情况的相关材料，经所在内设机构负责人审核后送检察委员会办事机构。"},{"i":33,"n":"第三十三条","txt":"检察委员会办事机构应当及时了解办案检察官或者事项承办人和有关内设机构、下级人民检察院执行检察委员会决定的情况，必要时进行督办，重要情况及时报告检察长。"},{"i":34,"n":"第三十四条","txt":"对故意拖延、拒不执行检察委员会决定的，应当按照有关规定追究责任人员的法律、纪律责任。"},{"i":35,"n":"第三十五条","txt":"人民检察院设立检察委员会办事机构，负责检察委员会日常工作。"},{"i":36,"n":"第三十六条","txt":"检察委员会办事机构履行下列职责："},{"i":37,"n":"第三十七条","txt":"检察委员会讨论决定的案件和事项，其提交、讨论、表决、作出决定、执行和督办等均在统一业务应用系统中进行，全程留痕。"},{"i":38,"n":"第三十八条","txt":"出席、列席检察委员会会议的人员，对检察委员会讨论的内容和情况应当保密。"},{"i":39,"n":"第三十九条","txt":"检察委员会及其委员的司法责任的认定和追究，适用《中华人民共和国人民检察院组织法》《中华人民共和国检察官法》和检察官惩戒相关规定。"},{"i":40,"n":"第四十条","txt":"本规则自公布之日起施行，《人民检察院检察委员会组织条例》（高检发〔2008〕5号）《人民检察院检察委员会议事和工作规则》（高检发〔2009〕23号）同时废止。"}],"renminjianchayuanminshisusongjianduguize":[{"i":1,"n":"第一条","txt":"为了保障和规范人民检察院依法履行民事检察职责，根据《中华人民共和国民事诉讼法》《中华人民共和国人民检察院组织法》和其他有关规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院依法独立行使检察权，通过办理民事诉讼监督案件，维护司法公正和司法权威，维护国家利益和社会公共利益，维护自然人、法人和非法人组织的合法权益，保障国家法律的统一正确实施。"},{"i":3,"n":"第三条","txt":"人民检察院通过抗诉、检察建议等方式，对民事诉讼活动实行法律监督。"},{"i":4,"n":"第四条","txt":"人民检察院办理民事诉讼监督案件，应当以事实为根据，以法律为准绳，坚持公开、公平、公正和诚实信用原则，尊重和保障当事人的诉讼权利，监督和支持人民法院依法行使审判权和执行权。"},{"i":5,"n":"第五条","txt":"负责控告申诉检察、民事检察、案件管理的部门分别承担民事诉讼监督案件的受理、办理、管理工作，各部门互相配合，互相制约。"},{"i":6,"n":"第六条","txt":"人民检察院办理民事诉讼监督案件，实行检察官办案责任制，由检察官、检察长、检察委员会在各自职权范围内对办案事项作出决定，并依照规定承担相应司法责任。"},{"i":7,"n":"第七条","txt":"人民检察院办理民事诉讼监督案件，根据案件情况，可以由一名检察官独任办理，也可以由两名以上检察官组成办案组办理。由检察官办案组办理的，检察长应当指定一名检察官担任主办检察官，组织、指挥办案组办理案件。"},{"i":8,"n":"第八条","txt":"最高人民检察院领导地方各级人民检察院和专门人民检察院的民事诉讼监督工作，上级人民检察院领导下级人民检察院的民事诉讼监督工作。"},{"i":9,"n":"第九条","txt":"人民检察院检察长或者检察长委托的副检察长在同级人民法院审判委员会讨论民事抗诉案件或者其他与民事诉讼监督工作有关的议题时，可以依照有关规定列席会议。"},{"i":10,"n":"第十条","txt":"人民检察院办理民事诉讼监督案件，实行回避制度。"},{"i":11,"n":"第十一条","txt":"检察人员办理民事诉讼监督案件，应当秉持客观公正的立场，自觉接受监督。"},{"i":12,"n":"第十二条","txt":"检察人员有《中华人民共和国民事诉讼法》第四十四条规定情形之一的，应当自行回避，当事人有权申请他们回避。"},{"i":13,"n":"第十三条","txt":"检察人员自行回避的，可以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。"},{"i":14,"n":"第十四条","txt":"当事人申请回避，应当在人民检察院作出提出抗诉或者检察建议等决定前以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。根据《中华人民共和国民事诉讼法》第四十四条第二款规定提出回避申请的，应当提供相关证据。"},{"i":15,"n":"第十五条","txt":"检察人员有应当回避的情形，没有自行回避，当事人也没有申请其回避的，由检察长或者检察委员会决定其回避。"},{"i":16,"n":"第十六条","txt":"检察长的回避，由检察委员会讨论决定；检察人员和其他人员的回避，由检察长决定。检察委员会讨论检察长回避问题时，由副检察长主持，检察长不得参加。"},{"i":17,"n":"第十七条","txt":"人民检察院对当事人提出的回避申请，应当在三日内作出决定，并通知申请人。申请人对决定不服的，可以在接到决定时向原决定机关申请复议一次。人民检察院应当在三日内作出复议决定，并通知复议申请人。复议期间，被申请回避的人员不停止参与本案工作。"},{"i":18,"n":"第十八条","txt":"民事诉讼监督案件的来源包括："},{"i":19,"n":"第十九条","txt":"有下列情形之一的，当事人可以向人民检察院申请监督："},{"i":20,"n":"第二十条","txt":"当事人依照本规则第十九条第一项规定向人民检察院申请监督，应当在人民法院作出驳回再审申请裁定或者再审判决、裁定发生法律效力之日起两年内提出。"},{"i":21,"n":"第二十一条","txt":"当事人向人民检察院申请监督，应当提交监督申请书、身份证明、相关法律文书及证据材料。提交证据材料的，应当附证据清单。"},{"i":22,"n":"第二十二条","txt":"本规则第二十一条规定的监督申请书应当记明下列事项："},{"i":23,"n":"第二十三条","txt":"本规则第二十一条规定的身份证明包括："},{"i":24,"n":"第二十四条","txt":"本规则第二十一条规定的相关法律文书是指人民法院在该案件诉讼过程中作出的全部判决书、裁定书、决定书、调解书等法律文书。"},{"i":25,"n":"第二十五条","txt":"当事人申请监督，可以依照《中华人民共和国民事诉讼法》的规定委托诉讼代理人。"},{"i":26,"n":"第二十六条","txt":"当事人申请监督符合下列条件的，人民检察院应当受理："},{"i":27,"n":"第二十七条","txt":"当事人根据《中华人民共和国民事诉讼法》第二百零九条第一款的规定向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":28,"n":"第二十八条","txt":"当事人认为民事审判程序或者执行活动存在违法情形，向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":29,"n":"第二十九条","txt":"当事人根据《中华人民共和国民事诉讼法》第二百零九条第一款的规定向人民检察院申请检察建议或者抗诉，由作出生效民事判决、裁定、调解书的人民法院所在地同级人民检察院负责控告申诉检察的部门受理。"},{"i":30,"n":"第三十条","txt":"当事人认为民事审判程序中审判人员存在违法行为或者民事执行活动存在违法情形，向人民检察院申请监督的，由审理、执行案件的人民法院所在地同级人民检察院负责控告申诉检察的部门受理。"},{"i":31,"n":"第三十一条","txt":"当事人认为人民检察院不依法受理其监督申请的，可以向上一级人民检察院申请监督。上一级人民检察院认为当事人监督申请符合受理条件的，应当指令下一级人民检察院受理，必要时也可以直接受理。"},{"i":32,"n":"第三十二条","txt":"人民检察院负责控告申诉检察的部门对监督申请，应当根据以下情形作出处理："},{"i":33,"n":"第三十三条","txt":"负责控告申诉检察的部门应当在决定受理之日起三日内制作《受理通知书》，发送申请人，并告知其权利义务；同时将《受理通知书》和监督申请书副本发送其他当事人，并告知其权利义务。其他当事人可以在收到监督申请书副本之日起十五日内提出书面意见，不提出意见的不影响人民检察院对案件的审查。"},{"i":34,"n":"第三十四条","txt":"负责控告申诉检察的部门应当在决定受理之日起三日内将案件材料移送本院负责民事检察的部门，同时将《受理通知书》抄送本院负责案件管理的部门。负责控告申诉检察的部门收到其他当事人提交的书面意见等材料，应当及时移送负责民事检察的部门。"},{"i":35,"n":"第三十五条","txt":"当事人以外的自然人、法人和非法人组织认为人民法院民事审判程序中审判人员存在违法行为或者民事执行活动存在违法情形等，可以向同级人民检察院控告。控告由人民检察院负责控告申诉检察的部门受理。"},{"i":36,"n":"第三十六条","txt":"负责控告申诉检察的部门可以依据《人民检察院信访工作规定》，向下级人民检察院交办涉及民事诉讼监督的信访案件。"},{"i":37,"n":"第三十七条","txt":"人民检察院在履行职责中发现民事案件有下列情形之一的，应当依职权启动监督程序："},{"i":38,"n":"第三十八条","txt":"下级人民检察院提请抗诉、提请其他监督等案件，由上一级人民检察院负责案件管理的部门受理。"},{"i":39,"n":"第三十九条","txt":"负责案件管理的部门接收案件材料后，应当在三日内登记并将案件材料和案件登记表移送负责民事检察的部门；案件材料不符合规定的，应当要求补齐。"},{"i":40,"n":"第四十条","txt":"受理后的民事诉讼监督案件由负责民事检察的部门进行审查。"},{"i":41,"n":"第四十一条","txt":"上级人民检察院认为确有必要的，可以办理下级人民检察院受理的民事诉讼监督案件。"},{"i":42,"n":"第四十二条","txt":"上级人民检察院可以将受理的民事诉讼监督案件交由下级人民检察院办理，并限定办理期限。交办的案件应当制作《交办通知书》，并将有关材料移送下级人民检察院。下级人民检察院应当依法办理，不得将案件再行交办。除本规则第一百零七条规定外，下级人民检察院应当在规定期限内提出处理意见并报送上级人民检察院，上级人民检察院应当在法定期限内作出决定。"},{"i":43,"n":"第四十三条","txt":"人民检察院审查民事诉讼监督案件，应当围绕申请人的申请监督请求、争议焦点以及本规则第三十七条规定的情形，对人民法院民事诉讼活动是否合法进行全面审查。其他当事人在人民检察院作出决定前也申请监督的，应当将其列为申请人，对其申请监督请求一并审查。"},{"i":44,"n":"第四十四条","txt":"申请人或者其他当事人对提出的主张，应当提供证据材料。人民检察院收到当事人提交的证据材料，应当出具收据。"},{"i":45,"n":"第四十五条","txt":"人民检察院应当告知当事人有申请回避的权利，并告知办理案件的检察人员、书记员等的姓名、法律职务。"},{"i":46,"n":"第四十六条","txt":"人民检察院审查案件，应当通过适当方式听取当事人意见，必要时可以听证或者调查核实有关情况，也可以依照有关规定组织专家咨询论证。"},{"i":47,"n":"第四十七条","txt":"人民检察院审查案件，可以依照有关规定调阅人民法院的诉讼卷宗。"},{"i":48,"n":"第四十八条","txt":"承办检察官审查终结后，应当制作审查终结报告。审查终结报告应当全面、客观、公正地叙述案件事实，依据法律提出处理建议或者意见。"},{"i":49,"n":"第四十九条","txt":"承办检察官办理案件过程中，可以提请部门负责人召集检察官联席会议讨论。检察长、部门负责人在审核或者决定案件时，也可以召集检察官联席会议讨论。"},{"i":50,"n":"第五十条","txt":"人民检察院对审查终结的案件，应当区分情况作出下列决定："},{"i":51,"n":"第五十一条","txt":"人民检察院在办理民事诉讼监督案件过程中，当事人有和解意愿的，可以引导当事人自行和解。"},{"i":52,"n":"第五十二条","txt":"人民检察院受理当事人申请对人民法院已经发生法律效力的民事判决、裁定、调解书监督的案件，应当在三个月内审查终结并作出决定，但调卷、鉴定、评估、审计、专家咨询等期间不计入审查期限。"},{"i":53,"n":"第五十三条","txt":"人民检察院办理民事诉讼监督案件，可以依照有关规定指派司法警察协助承办检察官履行调查核实、听证等职责。"},{"i":54,"n":"第五十四条","txt":"人民检察院审查民事诉讼监督案件，认为确有必要的，可以组织有关当事人听证。"},{"i":55,"n":"第五十五条","txt":"人民检察院组织听证，由承办检察官主持，书记员负责记录。"},{"i":56,"n":"第五十六条","txt":"人民检察院组织听证，应当在听证三日前告知听证会参加人案由、听证时间和地点。"},{"i":57,"n":"第五十七条","txt":"参加听证的当事人和其他相关人员应当按时参加听证，当事人无正当理由缺席或者未经许可中途退席的，不影响听证程序的进行。"},{"i":58,"n":"第五十八条","txt":"听证应当围绕民事诉讼监督案件中的事实认定和法律适用等问题进行。"},{"i":59,"n":"第五十九条","txt":"听证会一般按照下列步骤进行："},{"i":60,"n":"第六十条","txt":"听证应当制作笔录，经当事人校阅后，由当事人签名或者盖章。拒绝签名盖章的，应当记明情况。"},{"i":61,"n":"第六十一条","txt":"参加听证的人员应当服从听证主持人指挥。"},{"i":62,"n":"第六十二条","txt":"人民检察院因履行法律监督职责的需要，有下列情形之一的，可以向当事人或者案外人调查核实有关情况："},{"i":63,"n":"第六十三条","txt":"人民检察院可以采取以下调查核实措施："},{"i":64,"n":"第六十四条","txt":"有下列情形之一的，人民检察院可以向银行业金融机构查询、调取、复制相关证据材料："},{"i":65,"n":"第六十五条","txt":"人民检察院可以就专门性问题书面或者口头咨询有关专业人员、相关部门或者行业协会的意见。口头咨询的，应当制作笔录，由接受咨询的专业人员签名或者盖章。拒绝签名盖章的，应当记明情况。"},{"i":66,"n":"第六十六条","txt":"人民检察院对专门性问题认为需要鉴定、评估、审计的，可以委托具备资格的机构进行鉴定、评估、审计。"},{"i":67,"n":"第六十七条","txt":"人民检察院认为确有必要的，可以勘验物证或者现场。勘验人应当出示人民检察院的证件，并邀请当地基层组织或者当事人所在单位派人参加。当事人或者当事人的成年家属应当到场，拒不到场的，不影响勘验的进行。"},{"i":68,"n":"第六十八条","txt":"需要调查核实的，由承办检察官在职权范围内决定，或者报检察长决定。"},{"i":69,"n":"第六十九条","txt":"人民检察院调查核实，应当由二人以上共同进行。"},{"i":70,"n":"第七十条","txt":"人民检察院可以指令下级人民检察院或者委托外地人民检察院调查核实。"},{"i":71,"n":"第七十一条","txt":"人民检察院调查核实，有关单位和个人应当配合。拒绝或者妨碍人民检察院调查核实的，人民检察院可以向有关单位或者其上级主管部门提出检察建议，责令纠正；涉嫌违纪违法犯罪的，依照规定移送有关机关处理。"},{"i":72,"n":"第七十二条","txt":"有下列情形之一的，人民检察院可以中止审查："},{"i":73,"n":"第七十三条","txt":"有下列情形之一的，人民检察院应当终结审查："},{"i":74,"n":"第七十四条","txt":"人民检察院发现人民法院已经发生法律效力的民事判决、裁定有《中华人民共和国民事诉讼法》第二百条规定情形之一的，依法向人民法院提出再审检察建议或者抗诉。"},{"i":75,"n":"第七十五条","txt":"人民检察院发现民事调解书损害国家利益、社会公共利益的，依法向人民法院提出再审检察建议或者抗诉。"},{"i":76,"n":"第七十六条","txt":"当事人因故意或者重大过失逾期提供的证据，人民检察院不予采纳。但该证据与案件基本事实有关并且能够证明原判决、裁定确有错误的，应当认定为《中华人民共和国民事诉讼法》第二百条第一项规定的情形。"},{"i":77,"n":"第七十七条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第二项规定的“认定的基本事实缺乏证据证明”："},{"i":78,"n":"第七十八条","txt":"有下列情形之一，导致原判决、裁定结果错误的，应当认定为《中华人民共和国民事诉讼法》第二百条第六项规定的“适用法律确有错误”："},{"i":79,"n":"第七十九条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第七项规定的“审判组织的组成不合法”："},{"i":80,"n":"第八十条","txt":"有下列情形之一的，应当认定为《中华人民共和国民事诉讼法》第二百条第九项规定的“违反法律规定，剥夺当事人辩论权利”："},{"i":81,"n":"第八十一条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的民事判决、裁定有下列情形之一的，可以向同级人民法院提出再审检察建议："},{"i":82,"n":"第八十二条","txt":"符合本规则第八十一条规定的案件有下列情形之一的，地方各级人民检察院一般应当提请上一级人民检察院抗诉："},{"i":83,"n":"第八十三条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的民事判决、裁定有下列情形之一的，一般应当提请上一级人民检察院抗诉："},{"i":84,"n":"第八十四条","txt":"符合本规则第八十二条、第八十三条规定的案件，适宜由同级人民法院再审纠正的，地方各级人民检察院可以向同级人民法院提出再审检察建议。"},{"i":85,"n":"第八十五条","txt":"地方各级人民检察院发现民事调解书损害国家利益、社会公共利益的，可以向同级人民法院提出再审检察建议，也可以提请上一级人民检察院抗诉。"},{"i":86,"n":"第八十六条","txt":"对人民法院已经采纳再审检察建议进行再审的案件，提出再审检察建议的人民检察院一般不得再向上级人民检察院提请抗诉。"},{"i":87,"n":"第八十七条","txt":"人民检察院提出再审检察建议，应当制作《再审检察建议书》，在决定提出再审检察建议之日起十五日内将《再审检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出再审检察建议的《通知书》，发送当事人。"},{"i":88,"n":"第八十八条","txt":"人民检察院提请抗诉，应当制作《提请抗诉报告书》，在决定提请抗诉之日起十五日内将《提请抗诉报告书》连同案件卷宗报送上一级人民检察院，并制作决定提请抗诉的《通知书》，发送当事人。"},{"i":89,"n":"第八十九条","txt":"人民检察院认为当事人的监督申请不符合提出再审检察建议或者提请抗诉条件的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送当事人。"},{"i":90,"n":"第九十条","txt":"最高人民检察院对各级人民法院已经发生法律效力的民事判决、裁定、调解书，上级人民检察院对下级人民法院已经发生法律效力的民事判决、裁定、调解书，发现有《中华人民共和国民事诉讼法》第二百条、第二百零八条规定情形的，应当向同级人民法院提出抗诉。"},{"i":91,"n":"第九十一条","txt":"人民检察院提出抗诉的案件，接受抗诉的人民法院将案件交下一级人民法院再审，下一级人民法院审理后作出的再审判决、裁定仍有明显错误的，原提出抗诉的人民检察院可以依职权再次提出抗诉。"},{"i":92,"n":"第九十二条","txt":"人民检察院提出抗诉，应当制作《抗诉书》，在决定抗诉之日起十五日内将《抗诉书》连同案件卷宗移送同级人民法院，并由接受抗诉的人民法院向当事人送达再审裁定时一并送达《抗诉书》。"},{"i":93,"n":"第九十三条","txt":"人民检察院认为当事人的监督申请不符合抗诉条件的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送当事人。上级人民检察院可以委托提请抗诉的人民检察院将《不支持监督申请决定书》发送当事人。"},{"i":94,"n":"第九十四条","txt":"人民检察院提出抗诉的案件，人民法院再审时，人民检察院应当派员出席法庭。"},{"i":95,"n":"第九十五条","txt":"接受抗诉的人民法院将抗诉案件交下级人民法院再审的，提出抗诉的人民检察院可以指令再审人民法院的同级人民检察院派员出庭。"},{"i":96,"n":"第九十六条","txt":"检察人员出席再审法庭的任务是："},{"i":97,"n":"第九十七条","txt":"当事人或者其他参加庭审人员在庭审中对检察机关或者出庭检察人员有侮辱、诽谤、威胁等不当言论或者行为的，出庭检察人员应当建议法庭即时予以制止；情节严重的，应当建议法庭依照规定予以处理，并在庭审结束后向检察长报告。"},{"i":98,"n":"第九十八条","txt":"《中华人民共和国民事诉讼法》第二百零八条第三款规定的审判程序包括："},{"i":99,"n":"第九十九条","txt":"《中华人民共和国民事诉讼法》第二百零八条第三款的规定适用于法官、人民陪审员、法官助理、书记员。"},{"i":100,"n":"第一百条","txt":"人民检察院发现同级人民法院民事审判程序中有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":101,"n":"第一百零一条","txt":"人民检察院发现同级人民法院民事审判程序中审判人员有《中华人民共和国法官法》第四十六条等规定的违法行为且可能影响案件公正审判、执行的，应当向同级人民法院提出检察建议。"},{"i":102,"n":"第一百零二条","txt":"人民检察院依照本章规定提出检察建议的，应当制作《检察建议书》，在决定提出检察建议之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出检察建议的《通知书》，发送申请人。"},{"i":103,"n":"第一百零三条","txt":"人民检察院认为当事人申请监督的审判程序中审判人员违法行为认定依据不足的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":104,"n":"第一百零四条","txt":"人民检察院对人民法院执行生效民事判决、裁定、调解书、支付令、仲裁裁决以及公证债权文书等法律文书的活动实行法律监督。"},{"i":105,"n":"第一百零五条","txt":"人民检察院认为人民法院在执行活动中可能存在怠于履行职责情形的，可以依照有关规定向人民法院发出《说明案件执行情况通知书》，要求说明案件的执行情况及理由。"},{"i":106,"n":"第一百零六条","txt":"人民检察院发现人民法院在执行活动中有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":107,"n":"第一百零七条","txt":"人民检察院依照本规则第三十条第二款规定受理后交办的案件，下级人民检察院经审查认为人民法院作出的执行复议裁定、决定等存在违法、错误情形的，应当提请上级人民检察院监督；认为人民法院作出的执行复议裁定、决定等正确的，应当作出不支持监督申请的决定。"},{"i":108,"n":"第一百零八条","txt":"人民检察院对执行活动提出检察建议的，应当经检察长或者检察委员会决定，制作《检察建议书》，在决定之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院，并制作决定提出检察建议的《通知书》，发送当事人。"},{"i":109,"n":"第一百零九条","txt":"人民检察院认为当事人申请监督的人民法院执行活动不存在违法情形的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":110,"n":"第一百一十条","txt":"人民检察院发现同级人民法院执行活动中执行人员存在违法行为的，参照本规则第六章有关规定执行。"},{"i":111,"n":"第一百一十一条","txt":"人民检察院负责案件管理的部门对民事诉讼监督案件的受理、期限、程序、质量等进行管理、监督、预警。"},{"i":112,"n":"第一百一十二条","txt":"负责案件管理的部门发现本院办案活动有下列情形之一的，应当及时提出纠正意见："},{"i":113,"n":"第一百一十三条","txt":"负责案件管理的部门对以本院名义制发民事诉讼监督法律文书实施监督管理。"},{"i":114,"n":"第一百一十四条","txt":"人民检察院办理的民事诉讼监督案件，办结后需要向其他单位移送案卷材料的，统一由负责案件管理的部门审核移送材料是否规范、齐备。负责案件管理的部门认为材料规范、齐备，符合移送条件的，应当立即由办案部门按照规定移送；认为材料不符合要求的，应当及时通知办案部门补送、更正。"},{"i":115,"n":"第一百一十五条","txt":"人民法院向人民检察院送达的民事判决书、裁定书或者调解书等法律文书，由负责案件管理的部门负责接收，并即时登记移送负责民事检察的部门。"},{"i":116,"n":"第一百一十六条","txt":"人民检察院在办理民事诉讼监督案件过程中，当事人及其诉讼代理人提出有关申请、要求或者提交有关书面材料的，由负责案件管理的部门负责接收，需要出具相关手续的，负责案件管理的部门应当出具。负责案件管理的部门接收材料后应当及时移送负责民事检察的部门。"},{"i":117,"n":"第一百一十七条","txt":"人民检察院发现人民法院在多起同一类型民事案件中有下列情形之一的，可以提出检察建议："},{"i":118,"n":"第一百一十八条","txt":"申请人向人民检察院提交的新证据是伪造的，或者对案件重要事实作虚假陈述的，人民检察院应当予以批评教育，并可以终结审查，但确有必要进行监督的除外；涉嫌违纪违法犯罪的，依照规定移送有关机关处理。"},{"i":119,"n":"第一百一十九条","txt":"人民检察院发现人民法院审查和处理当事人申请执行、撤销仲裁裁决或者申请执行公证债权文书存在违法、错误情形的，参照本规则第六章、第七章有关规定执行。"},{"i":120,"n":"第一百二十条","txt":"负责民事检察的部门在履行职责过程中，发现涉嫌违纪违法犯罪以及需要追究司法责任的行为，应当报检察长决定，及时将相关线索及材料移送有管辖权的机关或者部门。"},{"i":121,"n":"第一百二十一条","txt":"人民检察院发现作出的相关决定确有错误需要纠正或者有其他情形需要撤回的，应当经本院检察长或者检察委员会决定。"},{"i":122,"n":"第一百二十二条","txt":"人民法院对人民检察院监督行为提出建议的，人民检察院应当在一个月内将处理结果书面回复人民法院。人民法院对回复意见有异议，并通过上一级人民法院向上一级人民检察院提出的，上一级人民检察院认为人民法院建议正确，应当要求下级人民检察院及时纠正。"},{"i":123,"n":"第一百二十三条","txt":"人民法院对民事诉讼监督案件作出再审判决、裁定或者其他处理决定后，提出监督意见的人民检察院应当对处理结果进行审查，并填写《民事诉讼监督案件处理结果审查登记表》。"},{"i":124,"n":"第一百二十四条","txt":"有下列情形之一的，人民检察院可以按照有关规定再次监督或者提请上级人民检察院监督："},{"i":125,"n":"第一百二十五条","txt":"地方各级人民检察院对适用法律确属疑难、复杂，本院难以决断的重大民事诉讼监督案件，可以向上一级人民检察院请示。"},{"i":126,"n":"第一百二十六条","txt":"当事人认为人民检察院对同级人民法院已经发生法律效力的民事判决、裁定、调解书作出的不支持监督申请决定存在明显错误的，可以在不支持监督申请决定作出之日起一年内向上一级人民检察院申请复查一次。负责控告申诉检察的部门经初核，发现可能有以下情形之一的，可以移送本院负责民事检察的部门审查处理："},{"i":127,"n":"第一百二十七条","txt":"制作民事诉讼监督法律文书，应当符合规定的格式。"},{"i":128,"n":"第一百二十八条","txt":"人民检察院可以参照《中华人民共和国民事诉讼法》有关规定发送法律文书。"},{"i":129,"n":"第一百二十九条","txt":"人民检察院发现制作的法律文书存在笔误的，应当作出《补正决定书》予以补正。"},{"i":130,"n":"第一百三十条","txt":"人民检察院办理民事诉讼监督案件，应当按照规定建立民事诉讼监督案卷。"},{"i":131,"n":"第一百三十一条","txt":"人民检察院办理民事诉讼监督案件，不收取案件受理费。申请复印、鉴定、审计、勘验等产生的费用由申请人直接支付给有关机构或者单位，人民检察院不得代收代付。"},{"i":132,"n":"第一百三十二条","txt":"检察建议案件的办理，本规则未规定的，适用《人民检察院检察建议工作规定》。"},{"i":133,"n":"第一百三十三条","txt":"民事公益诉讼监督案件的办理，适用本规则及有关公益诉讼检察司法解释的规定。"},{"i":134,"n":"第一百三十四条","txt":"军事检察院等专门人民检察院对民事诉讼监督案件的办理，以及人民检察院对其他专门人民法院的民事诉讼监督案件的办理，适用本规则和其他有关规定。"},{"i":135,"n":"第一百三十五条","txt":"本规则自2021年8月1日起施行，《人民检察院民事诉讼监督规则（试行）》同时废止。本院之前公布的其他规定与本规则内容不一致的，以本规则为准。"}],"renminjianchayuanxingzhengsusongjianduguize":[{"i":1,"n":"第一条","txt":"为了保障和规范人民检察院依法履行行政诉讼监督职责，根据《中华人民共和国行政诉讼法》《中华人民共和国民事诉讼法》《中华人民共和国人民检察院组织法》和其他有关规定，结合人民检察院工作实际，制定本规则。"},{"i":2,"n":"第二条","txt":"人民检察院依法独立行使检察权，通过办理行政诉讼监督案件，监督人民法院依法审判和执行，促进行政机关依法行使职权，维护司法公正和司法权威，维护国家利益和社会公共利益，保护公民、法人和其他组织的合法权益，推动行政争议实质性化解，保障国家法律的统一正确实施。"},{"i":3,"n":"第三条","txt":"人民检察院通过提出抗诉、检察建议等方式，对行政诉讼实行法律监督。"},{"i":4,"n":"第四条","txt":"人民检察院对行政诉讼实行法律监督，应当以事实为根据，以法律为准绳，坚持公开、公平、公正，依法全面审查，监督和支持人民法院、行政机关依法行使职权。"},{"i":5,"n":"第五条","txt":"人民检察院办理行政诉讼监督案件，应当实行繁简分流，繁案精办、简案快办。"},{"i":6,"n":"第六条","txt":"人民检察院办理行政诉讼监督案件，应当查清案件事实、辨明是非，综合运用监督纠正、公开听证、释法说理、司法救助等手段，开展行政争议实质性化解工作。"},{"i":7,"n":"第七条","txt":"负责控告申诉检察、行政检察、案件管理的部门分别承担行政诉讼监督案件的受理、办理、管理工作，各部门互相配合，互相制约。"},{"i":8,"n":"第八条","txt":"人民检察院办理行政诉讼监督案件，由检察官、检察长、检察委员会在各自职权范围内对办案事项作出决定，并依照规定承担相应司法责任。"},{"i":9,"n":"第九条","txt":"人民检察院办理行政诉讼监督案件，根据案件情况，可以由一名检察官独任办理，也可以由两名以上检察官组成办案组办理。由检察官办案组办理的，检察长应当指定一名检察官担任主办检察官，组织、指挥办案组办理案件。"},{"i":10,"n":"第十条","txt":"最高人民检察院领导地方各级人民检察院和专门人民检察院的行政诉讼监督工作，上级人民检察院领导下级人民检察院的行政诉讼监督工作。"},{"i":11,"n":"第十一条","txt":"人民检察院检察长或者检察长委托的副检察长在同级人民法院审判委员会讨论行政诉讼监督案件或者其他与行政诉讼监督工作有关的议题时，可以依照有关规定列席会议。"},{"i":12,"n":"第十二条","txt":"检察人员办理行政诉讼监督案件，应当秉持客观公正的立场，自觉接受监督。"},{"i":13,"n":"第十三条","txt":"检察人员办理行政诉讼监督案件，有下列情形之一的，应当自行回避，当事人有权申请他们回避："},{"i":14,"n":"第十四条","txt":"检察人员自行回避的，可以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。"},{"i":15,"n":"第十五条","txt":"当事人申请回避，应当在人民检察院作出提出抗诉或者检察建议等决定前以口头或者书面方式提出，并说明理由。口头提出申请的，应当记录在卷。依照本规则第十三条第二款规定提出回避申请的，应当提供相关证据。"},{"i":16,"n":"第十六条","txt":"检察长的回避，由检察委员会讨论决定；检察人员和其他人员的回避，由检察长决定。检察委员会讨论检察长回避问题时，由副检察长主持，检察长不得参加。"},{"i":17,"n":"第十七条","txt":"人民检察院对当事人提出的回避申请，应当在三日内作出决定，并通知申请人。对明显不属于法定回避事由的申请，可以当场驳回，并记录在卷。"},{"i":18,"n":"第十八条","txt":"人民检察院受理行政诉讼监督案件的途径包括："},{"i":19,"n":"第十九条","txt":"有下列情形之一的，当事人可以向人民检察院申请监督："},{"i":20,"n":"第二十条","txt":"当事人依照本规则第十九条第一款第一项、第二项规定向人民检察院申请监督，应当在人民法院送达驳回再审申请裁定之日或者再审判决、裁定发生法律效力之日起六个月内提出；对人民法院逾期未对再审申请作出裁定的，应当在再审申请审查期限届满之日起六个月内提出。"},{"i":21,"n":"第二十一条","txt":"当事人向人民检察院申请监督，应当提交监督申请书、身份证明、相关法律文书及证据材料。提交证据材料的，应当附证据清单。"},{"i":22,"n":"第二十二条","txt":"本规则第二十一条规定的监督申请书应当记明下列事项："},{"i":23,"n":"第二十三条","txt":"本规则第二十一条规定的身份证明包括："},{"i":24,"n":"第二十四条","txt":"本规则第二十一条规定的相关法律文书是指人民法院在该案件诉讼过程中作出的全部判决书、裁定书、决定书、调解书等法律文书。"},{"i":25,"n":"第二十五条","txt":"当事人申请监督，可以依照《中华人民共和国行政诉讼法》的规定委托代理人。"},{"i":26,"n":"第二十六条","txt":"当事人申请监督同时符合下列条件的，人民检察院应当受理："},{"i":27,"n":"第二十七条","txt":"当事人向人民检察院申请监督，有下列情形之一的，人民检察院不予受理："},{"i":28,"n":"第二十八条","txt":"当事人对已经发生法律效力的行政判决、裁定、调解书向人民检察院申请监督的，由作出生效判决、裁定、调解书的人民法院所在地同级人民检察院负责控告申诉检察的部门受理。"},{"i":29,"n":"第二十九条","txt":"当事人认为行政审判程序中审判人员存在违法行为或者执行活动存在违法情形，向人民检察院申请监督的，由审理、执行案件的人民法院所在地同级人民检察院负责控告申诉检察的部门受理。"},{"i":30,"n":"第三十条","txt":"人民检察院不依法受理当事人监督申请的，当事人可以向上一级人民检察院申请监督。上一级人民检察院认为当事人监督申请符合受理条件的，应当指令下一级人民检察院受理，必要时也可以直接受理。"},{"i":31,"n":"第三十一条","txt":"人民检察院负责控告申诉检察的部门对监督申请，应当在七日内根据以下情形作出处理，并答复申请人："},{"i":32,"n":"第三十二条","txt":"负责控告申诉检察的部门应当在决定受理之日起三日内制作《受理通知书》，发送申请人，并告知其权利义务。"},{"i":33,"n":"第三十三条","txt":"负责控告申诉检察的部门应当在决定受理之日起三日内将案件材料移送本院负责行政检察的部门，同时将《受理通知书》抄送本院负责案件管理的部门。负责控告申诉检察的部门收到其他当事人提交的书面意见等材料，应当及时移送负责行政检察的部门。"},{"i":34,"n":"第三十四条","txt":"当事人以外的公民、法人或者其他组织认为人民法院行政审判程序中审判人员存在违法行为或者执行活动存在违法情形的，可以向同级人民检察院控告。控告由人民检察院负责控告申诉检察的部门受理。"},{"i":35,"n":"第三十五条","txt":"负责控告申诉检察的部门可以依照《人民检察院信访工作规定》，向下级人民检察院交办涉及行政诉讼监督的信访案件。"},{"i":36,"n":"第三十六条","txt":"人民检察院在履行职责中发现行政案件有下列情形之一的，应当依职权监督："},{"i":37,"n":"第三十七条","txt":"下级人民检察院提请抗诉、提请其他监督等案件，由上一级人民检察院负责案件管理的部门受理。"},{"i":38,"n":"第三十八条","txt":"负责案件管理的部门接收案件材料后，应当在三日内登记并将案件材料和案件登记表移送负责行政检察的部门；案件材料不符合规定的，应当要求补齐。"},{"i":39,"n":"第三十九条","txt":"人民检察院负责行政检察的部门负责对受理后的行政诉讼监督案件进行审查。"},{"i":40,"n":"第四十条","txt":"负责行政检察的部门收到负责控告申诉检察、案件管理的部门移送的行政诉讼监督案件后，应当按照随机分案为主、指定分案为辅的原则，确定承办案件的独任检察官或者检察官办案组。"},{"i":41,"n":"第四十一条","txt":"上级人民检察院可以将受理的行政诉讼监督案件交由下级人民检察院办理，并限定办理期限。交办的案件应当制作《交办通知书》，并将有关材料移送下级人民检察院。下级人民检察院应当依法办理，在规定期限内提出处理意见并报送上级人民检察院，上级人民检察院应当在法定期限内作出决定。"},{"i":42,"n":"第四十二条","txt":"上级人民检察院认为确有必要的，可以办理下级人民检察院受理的行政诉讼监督案件。"},{"i":43,"n":"第四十三条","txt":"人民检察院审查行政诉讼监督案件，应当围绕申请人的申请监督请求、争议焦点、本规则第三十六条规定的情形以及发现的其他违法情形，对行政诉讼活动进行全面审查。其他当事人在人民检察院作出决定前也申请监督的，应当将其列为申请人，对其申请监督请求一并审查。"},{"i":44,"n":"第四十四条","txt":"人民检察院在审查行政诉讼监督案件期间收到申请人或者其他当事人提交的证据材料的，应当出具收据。"},{"i":45,"n":"第四十五条","txt":"被诉行政机关以外的当事人对不能自行收集的证据，在原审中向人民法院申请调取，人民法院应当调取而未予以调取，在诉讼监督阶段向人民检察院申请调取，符合下列情形之一的，人民检察院可以调取："},{"i":46,"n":"第四十六条","txt":"人民检察院应当告知当事人有申请回避的权利，并告知办理行政诉讼监督案件的检察人员、书记员等的姓名、法律职务。"},{"i":47,"n":"第四十七条","txt":"人民检察院审查案件，应当听取当事人意见，调查核实有关情况，必要时可以举行听证，也可以听取专家意见。"},{"i":48,"n":"第四十八条","txt":"人民检察院可以采取当面、视频、电话、传真、电子邮件、由当事人提交书面意见等方式听取当事人意见。"},{"i":49,"n":"第四十九条","txt":"人民检察院审查案件，可以依照有关规定调阅人民法院的诉讼卷宗、执行卷宗。"},{"i":50,"n":"第五十条","txt":"人民检察院审查案件，对于事实认定、法律适用的重大、疑难、复杂问题，可以采用以下方式听取专家意见："},{"i":51,"n":"第五十一条","txt":"人民检察院办理行政诉讼监督案件，应当全面检索相关指导性案例、典型案例和关联案例，并在审查终结报告中作出说明。"},{"i":52,"n":"第五十二条","txt":"承办检察官对审查认定的事实负责。审查终结后，应当制作审查终结报告。审查终结报告应当全面、客观、公正地叙述案件事实，依照法律提出明确的处理意见。"},{"i":53,"n":"第五十三条","txt":"承办检察官办理案件过程中，可以提请负责行政检察的部门负责人召集检察官联席会议讨论。"},{"i":54,"n":"第五十四条","txt":"检察长不同意检察官意见的，可以要求检察官复核，也可以直接作出决定，或者提请检察委员会讨论决定。"},{"i":55,"n":"第五十五条","txt":"人民检察院对审查终结的案件，应当区分情况依法作出下列决定："},{"i":56,"n":"第五十六条","txt":"人民检察院受理当事人申请对人民法院已经发生法律效力的行政判决、裁定、调解书监督的案件，应当在三个月内审查终结并作出决定，但调卷、鉴定、评估、审计、专家咨询等期间不计入审查期限。"},{"i":57,"n":"第五十七条","txt":"人民检察院办理行政诉讼监督案件，在当面听取当事人意见、调查核实、举行听证、出席法庭时，可以依照有关规定指派司法警察执行职务。"},{"i":58,"n":"第五十八条","txt":"人民检察院因履行法律监督职责的需要，有下列情形之一的，可以向当事人或者案外人调查核实有关情况："},{"i":59,"n":"第五十九条","txt":"人民检察院通过阅卷以及调查核实难以认定有关事实的，可以听取人民法院相关审判、执行人员的意见，全面了解案件审判、执行的相关事实和理由。"},{"i":60,"n":"第六十条","txt":"人民检察院可以采取以下调查核实措施："},{"i":61,"n":"第六十一条","txt":"有下列情形之一的，人民检察院可以向银行业金融机构查询、调取、复制相关证据材料："},{"i":62,"n":"第六十二条","txt":"人民检察院可以就专门性问题书面或者口头咨询有关专业人员、相关部门或者行业协会的意见。口头咨询的，应当制作笔录，由接受咨询的专业人员签名或者盖章。拒绝签名盖章的，应当记明情况。"},{"i":63,"n":"第六十三条","txt":"人民检察院认为确有必要的，可以勘验物证或者现场。勘验人应当出示人民检察院的证件，并邀请当地基层组织或者当事人所在单位派人参加。当事人或者当事人的成年家属应当到场，拒不到场的，不影响勘验的进行。"},{"i":64,"n":"第六十四条","txt":"需要调查核实的，由承办检察官在职权范围内决定，或者报检察长决定。"},{"i":65,"n":"第六十五条","txt":"人民检察院调查核实，应当由二人以上共同进行。"},{"i":66,"n":"第六十六条","txt":"人民检察院可以指令下级人民检察院或者委托外地人民检察院调查核实。"},{"i":67,"n":"第六十七条","txt":"人民检察院调查核实，有关单位和个人应当配合。拒绝或者妨碍人民检察院调查核实的，人民检察院可以向有关单位或者其上级主管机关提出检察建议，责令纠正，必要时可以通报同级政府、监察机关；涉嫌违纪违法犯罪的，依照规定移送有关机关处理。"},{"i":68,"n":"第六十八条","txt":"人民检察院审查行政诉讼监督案件，在事实认定、法律适用、案件处理等方面存在较大争议，或者有重大社会影响，需要当面听取当事人和其他相关人员意见的，可以召开听证会。"},{"i":69,"n":"第六十九条","txt":"人民检察院召开听证会，可以邀请与案件没有利害关系的人大代表、政协委员、人民监督员、特约检察员、专家咨询委员、人民调解员或者当事人所在单位、居住地的居民委员会、村民委员会成员以及专家、学者、律师等其他社会人士担任听证员。"},{"i":70,"n":"第七十条","txt":"人民检察院决定召开听证会的，应当做好以下准备工作："},{"i":71,"n":"第七十一条","txt":"当事人和其他相关人员应当按时参加听证会。当事人无正当理由缺席或者未经许可中途退席的，听证程序是否继续进行，由主持人决定。"},{"i":72,"n":"第七十二条","txt":"听证会由检察官主持，书记员负责记录，司法警察负责维持秩序。"},{"i":73,"n":"第七十三条","txt":"听证会应当围绕行政诉讼监督案件中的事实认定和法律适用等问题进行。"},{"i":74,"n":"第七十四条","txt":"听证会一般按照下列步骤进行："},{"i":75,"n":"第七十五条","txt":"听证应当制作笔录，经参加听证的人员校阅后，由参加听证的人员签名。拒绝签名的，应当记明情况。"},{"i":76,"n":"第七十六条","txt":"参加听证的人员应当服从听证主持人指挥。"},{"i":77,"n":"第七十七条","txt":"行政诉讼监督案件具有下列情形之一的，可以确定为简易案件："},{"i":78,"n":"第七十八条","txt":"审查简易案件，承办检察官通过审查监督申请书等材料即可以认定案件事实的，可以直接制作审查终结报告，提出处理建议。"},{"i":79,"n":"第七十九条","txt":"办理简易案件，不适用延长审查期限的规定。"},{"i":80,"n":"第八十条","txt":"有下列情形之一的，人民检察院可以中止审查："},{"i":81,"n":"第八十一条","txt":"有下列情形之一的，人民检察院应当终结审查："},{"i":82,"n":"第八十二条","txt":"申请人提供的新证据以及人民检察院调查取得的证据，能够证明原判决、裁定确有错误的，应当认定为《中华人民共和国行政诉讼法》第九十一条第二项规定的情形，但原审被诉行政机关无正当理由逾期提供证据的除外。"},{"i":83,"n":"第八十三条","txt":"有下列情形之一的，应当认定为《中华人民共和国行政诉讼法》第九十一条第三项规定的“认定事实的主要证据不足”："},{"i":84,"n":"第八十四条","txt":"有下列情形之一，导致原判决、裁定结果确有错误的，应当认定为《中华人民共和国行政诉讼法》第九十一条第四项规定的“适用法律、法规确有错误”："},{"i":85,"n":"第八十五条","txt":"有下列情形之一的，应当认定为《中华人民共和国行政诉讼法》第九十一条第五项规定的“违反法律规定的诉讼程序，可能影响公正审判”："},{"i":86,"n":"第八十六条","txt":"有下列情形之一的，应当认定为本规则第八十五条第一项规定的“审判组织的组成不合法”："},{"i":87,"n":"第八十七条","txt":"有下列情形之一的，应当认定为本规则第八十五条第六项规定的“违反法律规定，剥夺当事人辩论权”："},{"i":88,"n":"第八十八条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的行政判决、裁定有下列情形之一的，可以向同级人民法院提出再审检察建议："},{"i":89,"n":"第八十九条","txt":"符合本规则第八十八条规定的案件有下列情形之一的，地方各级人民检察院应当提请上一级人民检察院抗诉："},{"i":90,"n":"第九十条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的行政判决、裁定具有下列情形之一的，应当提请上一级人民检察院抗诉："},{"i":91,"n":"第九十一条","txt":"地方各级人民检察院发现同级人民法院已经发生法律效力的行政调解书损害国家利益或者社会公共利益的，可以向同级人民法院提出再审检察建议，也可以提请上一级人民检察院抗诉。"},{"i":92,"n":"第九十二条","txt":"人民检察院提出再审检察建议，应当制作《再审检察建议书》，在决定之日起十五日内将《再审检察建议书》连同案件卷宗移送同级人民法院，并制作通知文书，发送当事人。"},{"i":93,"n":"第九十三条","txt":"人民检察院提请抗诉，应当制作《提请抗诉报告书》，在决定之日起十五日内将《提请抗诉报告书》连同案件卷宗等材料报送上一级人民检察院，并制作通知文书，发送当事人。"},{"i":94,"n":"第九十四条","txt":"最高人民检察院对各级人民法院已经发生法律效力的行政判决、裁定、调解书，上级人民检察院对下级人民法院已经发生法律效力的行政判决、裁定、调解书，发现有《中华人民共和国行政诉讼法》第九十一条、第九十三条规定情形的，应当向同级人民法院提出抗诉。"},{"i":95,"n":"第九十五条","txt":"人民检察院提出抗诉，应当制作《抗诉书》，在决定之日起十五日内将《抗诉书》连同案件卷宗移送同级人民法院，并由接受抗诉的人民法院向当事人送达再审裁定时一并送达《抗诉书》。"},{"i":96,"n":"第九十六条","txt":"人民检察院认为当事人不服人民法院生效行政判决、裁定、调解书的监督申请不符合监督条件，应当制作《不支持监督申请决定书》，在决定之日起十五日内发送当事人。"},{"i":97,"n":"第九十七条","txt":"人民检察院办理行政诉讼监督案件，发现地方性法规同行政法规相抵触的，或者认为规章以及国务院各部门、省、自治区、直辖市和设区的市、自治州的人民政府发布的其他具有普遍约束力的行政决定、命令同法律、行政法规相抵触的，可以层报最高人民检察院，由最高人民检察院向国务院书面提出审查建议。"},{"i":98,"n":"第九十八条","txt":"人民检察院提出抗诉的案件，人民法院再审时，人民检察院应当派员出席法庭，并全程参加庭审活动。"},{"i":99,"n":"第九十九条","txt":"检察人员在出庭前，应当做好以下准备工作："},{"i":100,"n":"第一百条","txt":"检察人员出席再审法庭的任务是："},{"i":101,"n":"第一百零一条","txt":"当事人或者其他参加庭审人员在庭审中有哄闹法庭，对检察机关或者出庭检察人员有侮辱、诽谤、威胁等不当言论或者行为，法庭未予制止的，出庭检察人员应当建议法庭即时制止；情节严重的，应当建议法庭依照规定予以处理，并在庭审结束后向检察长报告。"},{"i":102,"n":"第一百零二条","txt":"人民法院开庭审理人民检察院提出再审检察建议的案件，人民检察院派员出席再审法庭的，参照适用本节规定。"},{"i":103,"n":"第一百零三条","txt":"人民检察院依法对人民法院下列行政审判程序中审判人员违法行为进行监督："},{"i":104,"n":"第一百零四条","txt":"人民检察院发现人民法院行政审判活动有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":105,"n":"第一百零五条","txt":"人民检察院发现同级人民法院行政审判程序中审判人员有《中华人民共和国法官法》第四十六条等规定的违法行为且可能影响案件公正审判、执行的，应当向同级人民法院提出检察建议。"},{"i":106,"n":"第一百零六条","txt":"人民检察院依照本章规定提出检察建议，应当经检察长批准或者检察委员会决定，制作《检察建议书》，在决定之日起十五日内将《检察建议书》连同案件卷宗移送同级人民法院。当事人申请监督的案件，人民检察院应当制作通知文书，发送申请人。"},{"i":107,"n":"第一百零七条","txt":"人民检察院认为当事人申请监督的行政审判程序中审判人员违法行为认定依据不足的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":108,"n":"第一百零八条","txt":"人民检察院对人民法院行政案件执行活动实行法律监督。"},{"i":109,"n":"第一百零九条","txt":"人民检察院发现人民法院执行裁定、决定等有下列情形之一的，应当向同级人民法院提出检察建议："},{"i":110,"n":"第一百一十条","txt":"人民检察院发现人民法院在执行活动中违反规定采取调查、查封、扣押、冻结、评估、拍卖、变卖、保管、发还财产，以及信用惩戒等执行实施措施的，应当向同级人民法院提出检察建议。"},{"i":111,"n":"第一百一十一条","txt":"人民检察院发现人民法院有下列不履行或者怠于履行执行职责情形之一的，应当向同级人民法院提出检察建议："},{"i":112,"n":"第一百一十二条","txt":"人民检察院认为人民法院在行政案件执行活动中可能存在怠于履行职责情形的，可以向人民法院发出《说明案件执行情况通知书》，要求说明案件的执行情况及理由，并在十五日内书面回复人民检察院。"},{"i":113,"n":"第一百一十三条","txt":"人民检察院依照本章规定提出检察建议，适用本规则第一百零六条的规定。"},{"i":114,"n":"第一百一十四条","txt":"对于当事人申请的执行监督案件，人民检察院认为人民法院执行活动不存在违法情形的，应当作出不支持监督申请的决定，并在决定之日起十五日内制作《不支持监督申请决定书》，发送申请人。"},{"i":115,"n":"第一百一十五条","txt":"人民检察院发现同级人民法院行政案件执行活动中执行人员存在违法行为的，参照本规则第六章有关规定执行。"},{"i":116,"n":"第一百一十六条","txt":"人民检察院负责案件管理的部门对行政诉讼监督案件的受理、期限、程序、质量等进行管理、监督、预警。"},{"i":117,"n":"第一百一十七条","txt":"负责案件管理的部门对以本院名义制发行政诉讼监督法律文书实施监督管理。"},{"i":118,"n":"第一百一十八条","txt":"负责案件管理的部门发现本院办案活动有下列情形之一的，应当及时提出纠正意见："},{"i":119,"n":"第一百一十九条","txt":"人民检察院发现人民法院在多起同一类行政案件中有下列情形之一的，可以提出检察建议："},{"i":120,"n":"第一百二十条","txt":"人民检察院依照有关规定提出改进工作、完善治理的检察建议，对同类违法情形，应当制发一份检察建议。"},{"i":121,"n":"第一百二十一条","txt":"人民检察院办理行政诉讼监督案件，可以对行政诉讼监督情况进行年度或者专题分析，向人民法院、行政机关通报，向党委、人大报告。通报、报告包括以下内容："},{"i":122,"n":"第一百二十二条","txt":"人民检察院可以针对行政诉讼监督中的普遍性问题或者突出问题，组织开展专项监督活动。"},{"i":123,"n":"第一百二十三条","txt":"人民检察院负责行政检察的部门在履行职责过程中，发现涉嫌违纪违法犯罪以及需要追究司法责任的行为，经检察长批准，应当及时将相关线索及材料移送有管辖权的机关或者部门。"},{"i":124,"n":"第一百二十四条","txt":"人民法院对行政诉讼监督案件作出再审判决、裁定或者其他处理决定后，提出监督意见的人民检察院应当对处理结果进行审查，并填写《行政诉讼监督案件处理结果审查登记表》。"},{"i":125,"n":"第一百二十五条","txt":"有下列情形之一的，人民检察院可以依照有关规定跟进监督或者提请上级人民检察院监督："},{"i":126,"n":"第一百二十六条","txt":"地方各级人民检察院对适用法律确属疑难、复杂，本院难以决断的重大行政诉讼监督案件，可以向上一级人民检察院请示。"},{"i":127,"n":"第一百二十七条","txt":"人民检察院发现作出的相关决定确有错误或者有其他情形需要撤回、变更的，应当经检察长批准或者检察委员会决定。"},{"i":128,"n":"第一百二十八条","txt":"人民法院对人民检察院监督行为提出书面异议的，人民检察院应当在规定期限内将处理结果书面回复人民法院。人民法院对回复意见仍有异议，并通过上一级人民法院向上一级人民检察院提出的，上一级人民检察院认为人民法院异议正确，应当要求下级人民检察院及时纠正。"},{"i":129,"n":"第一百二十九条","txt":"制作行政诉讼监督法律文书，应当符合规定的格式。"},{"i":130,"n":"第一百三十条","txt":"人民检察院可以参照《中华人民共和国行政诉讼法》《中华人民共和国民事诉讼法》有关规定发送法律文书。"},{"i":131,"n":"第一百三十一条","txt":"人民检察院发现制作的法律文书存在笔误的，应当作出《补正决定书》予以补正。"},{"i":132,"n":"第一百三十二条","txt":"人民检察院办理行政诉讼监督案件，应当依照规定立卷归档。"},{"i":133,"n":"第一百三十三条","txt":"人民检察院办理行政诉讼监督案件，不收取案件受理费。申请复印、鉴定、审计、勘验等产生的费用由申请人直接支付给有关机构或者单位，人民检察院不得代收代付。"},{"i":134,"n":"第一百三十四条","txt":"人民检察院办理行政诉讼监督案件，对于申请人诉求具有一定合理性，但通过法律途径难以解决，且生活困难的，可以依法给予司法救助。"},{"i":135,"n":"第一百三十五条","txt":"人民检察院办理行政诉讼监督案件，本规则没有规定的，适用《人民检察院民事诉讼监督规则》的相关规定。"},{"i":136,"n":"第一百三十六条","txt":"人民检察院办理行政诉讼监督案件，向有关单位和部门提出检察建议，本规则没有规定的，适用《人民检察院检察建议工作规定》的相关规定。"},{"i":137,"n":"第一百三十七条","txt":"本规则自2021年9月1日起施行，《人民检察院行政诉讼监督规则（试行）》同时废止。本院之前公布的其他规定与本规则内容不一致的，以本规则为准。"}],"renminfayuanzaixiansusongguize":[{"i":1,"n":"第一条","txt":"人民法院、当事人及其他诉讼参与人等可以依托电子诉讼平台（以下简称“诉讼平台”），通过互联网或者专用网络在线完成立案、调解、证据交换、询问、庭审、送达等全部或者部分诉讼环节。"},{"i":2,"n":"第二条","txt":"人民法院开展在线诉讼应当遵循以下原则："},{"i":3,"n":"第三条","txt":"人民法院综合考虑案件情况、当事人意愿和技术条件等因素，可以对以下案件适用在线诉讼："},{"i":4,"n":"第四条","txt":"人民法院开展在线诉讼，应当征得当事人同意，并告知适用在线诉讼的具体环节、主要形式、权利义务、法律后果和操作方法等。"},{"i":5,"n":"第五条","txt":"在诉讼过程中，如存在当事人欠缺在线诉讼能力、不具备在线诉讼条件或者相应诉讼环节不宜在线办理等情形之一的，人民法院应当将相应诉讼环节转为线下进行。"},{"i":6,"n":"第六条","txt":"当事人已同意适用在线诉讼，但无正当理由不参与在线诉讼活动或者不作出相应诉讼行为，也未在合理期限内申请提出转为线下进行的，应当依照法律和司法解释的相关规定承担相应法律后果。"},{"i":7,"n":"第七条","txt":"参与在线诉讼的诉讼主体应当先行在诉讼平台完成实名注册。人民法院应当通过证件证照在线比对、身份认证平台认证等方式，核实诉讼主体的实名手机号码、居民身份证件号码、护照号码、统一社会信用代码等信息，确认诉讼主体身份真实性。诉讼主体在线完成身份认证后，取得登录诉讼平台的专用账号。"},{"i":8,"n":"第八条","txt":"人民法院、特邀调解组织、特邀调解员可以通过诉讼平台、人民法院调解平台等开展在线调解活动。在线调解应当按照法律和司法解释相关规定进行，依法保护国家秘密、商业秘密、个人隐私和其他不宜公开的信息。"},{"i":9,"n":"第九条","txt":"当事人采取在线方式提交起诉材料的，人民法院应当在收到材料后的法定期限内，在线作出以下处理："},{"i":10,"n":"第十条","txt":"案件适用在线诉讼的，人民法院应当通知被告、被上诉人或者其他诉讼参与人，询问其是否同意以在线方式参与诉讼。被通知人同意采用在线方式的，应当在收到通知的三日内通过诉讼平台验证身份、关联案件，并在后续诉讼活动中通过诉讼平台了解案件信息、接收和提交诉讼材料，以及实施其他诉讼行为。"},{"i":11,"n":"第十一条","txt":"当事人可以在诉讼平台直接填写录入起诉状、答辩状、反诉状、代理意见等诉讼文书材料。"},{"i":12,"n":"第十二条","txt":"当事人提交的电子化材料，经人民法院审核通过后，可以直接在诉讼中使用。诉讼中存在下列情形之一的，人民法院应当要求当事人提供原件、原物："},{"i":13,"n":"第十三条","txt":"当事人提交的电子化材料，符合下列情形之一的，人民法院可以认定符合原件、原物形式要求："},{"i":14,"n":"第十四条","txt":"人民法院根据当事人选择和案件情况，可以组织当事人开展在线证据交换，通过同步或者非同步方式在线举证、质证。"},{"i":15,"n":"第十五条","txt":"当事人作为证据提交的电子化材料和电子数据，人民法院应当按照法律和司法解释的相关规定，经当事人举证质证后，依法认定其真实性、合法性和关联性。未经人民法院查证属实的证据，不得作为认定案件事实的根据。"},{"i":16,"n":"第十六条","txt":"当事人作为证据提交的电子数据系通过区块链技术存储，并经技术核验一致的，人民法院可以认定该电子数据上链后未经篡改，但有相反证据足以推翻的除外。"},{"i":17,"n":"第十七条","txt":"当事人对区块链技术存储的电子数据上链后的真实性提出异议，并有合理理由的，人民法院应当结合下列因素作出判断："},{"i":18,"n":"第十八条","txt":"当事人提出电子数据上链存储前已不具备真实性，并提供证据证明或者说明理由的，人民法院应当予以审查。"},{"i":19,"n":"第十九条","txt":"当事人可以申请具有专门知识的人就区块链技术存储电子数据相关技术问题提出意见。人民法院可以根据当事人申请或者依职权，委托鉴定区块链技术存储电子数据的真实性，或者调取其他相关证据进行核对。"},{"i":20,"n":"第二十条","txt":"经各方当事人同意，人民法院可以指定当事人在一定期限内，分别登录诉讼平台，以非同步的方式开展调解、证据交换、调查询问、庭审等诉讼活动。"},{"i":21,"n":"第二十一条","txt":"人民法院开庭审理的案件，应当根据当事人意愿、案件情况、社会影响、技术条件等因素，决定是否采取视频方式在线庭审，但具有下列情形之一的，不得适用在线庭审："},{"i":22,"n":"第二十二条","txt":"适用在线庭审的案件，应当按照法律和司法解释的相关规定开展庭前准备、法庭调查、法庭辩论等庭审活动，保障当事人申请回避、举证、质证、陈述、辩论等诉讼权利。"},{"i":23,"n":"第二十三条","txt":"需要公告送达的案件，人民法院可以在公告中明确线上或者线下参与庭审的具体方式，告知当事人选择在线庭审的权利。被公告方当事人未在开庭前向人民法院表示同意在线庭审的，被公告方当事人适用线下庭审。其他同意适用在线庭审的当事人，可以在线参与庭审。"},{"i":24,"n":"第二十四条","txt":"在线开展庭审活动，人民法院应当设置环境要素齐全的在线法庭。在线法庭应当保持国徽在显著位置，审判人员及席位名称等在视频画面合理区域。因存在特殊情形，确需在在线法庭之外的其他场所组织在线庭审的，应当报请本院院长同意。"},{"i":25,"n":"第二十五条","txt":"出庭人员参加在线庭审应当尊重司法礼仪，遵守法庭纪律。人民法院根据在线庭审的特点，适用《中华人民共和国人民法院法庭规则》相关规定。"},{"i":26,"n":"第二十六条","txt":"证人通过在线方式出庭的，人民法院应当通过指定在线出庭场所、设置在线作证室等方式，保证其不旁听案件审理和不受他人干扰。当事人对证人在线出庭提出异议且有合理理由的，或者人民法院认为确有必要的，应当要求证人线下出庭作证。"},{"i":27,"n":"第二十七条","txt":"适用在线庭审的案件，应当按照法律和司法解释的相关规定公开庭审活动。"},{"i":28,"n":"第二十八条","txt":"在线诉讼参与人故意违反本规则第八条、第二十四条、第二十五条、第二十六条、第二十七条的规定，实施妨害在线诉讼秩序行为的，人民法院可以根据法律和司法解释关于妨害诉讼的相关规定作出处理。"},{"i":29,"n":"第二十九条","txt":"经受送达人同意，人民法院可以通过送达平台，向受送达人的电子邮箱、即时通讯账号、诉讼平台专用账号等电子地址，按照法律和司法解释的相关规定送达诉讼文书和证据材料。"},{"i":30,"n":"第三十条","txt":"人民法院可以通过电话确认、诉讼平台在线确认、线下发送电子送达确认书等方式，确认受送达人是否同意电子送达，以及受送达人接收电子送达的具体方式和地址，并告知电子送达的适用范围、效力、送达地址变更方式以及其他需告知的送达事项。"},{"i":31,"n":"第三十一条","txt":"人民法院向受送达人主动提供或者确认的电子地址送达的，送达信息到达电子地址所在系统时，即为送达。"},{"i":32,"n":"第三十二条","txt":"人民法院适用电子送达，可以同步通过短信、即时通讯工具、诉讼平台提示等方式，通知受送达人查阅、接收、下载相关送达材料。"},{"i":33,"n":"第三十三条","txt":"适用在线诉讼的案件，各方诉讼主体可以通过在线确认、电子签章等方式，确认和签收调解协议、笔录、电子送达凭证及其他诉讼材料。"},{"i":34,"n":"第三十四条","txt":"适用在线诉讼的案件，人民法院应当在调解、证据交换、庭审、合议等诉讼环节同步形成电子笔录。电子笔录以在线方式核对确认后，与书面笔录具有同等法律效力。"},{"i":35,"n":"第三十五条","txt":"适用在线诉讼的案件，人民法院应当利用技术手段随案同步生成电子卷宗，形成电子档案。电子档案的立卷、归档、存储、利用等，按照档案管理相关法律法规的规定执行。"},{"i":36,"n":"第三十六条","txt":"执行裁决案件的在线立案、电子材料提交、执行和解、询问当事人、电子送达等环节，适用本规则的相关规定办理。"},{"i":37,"n":"第三十七条","txt":"符合本规定第三条第二项规定的刑事案件，经公诉人、当事人、辩护人同意，可以根据案件情况，采取在线方式讯问被告人、开庭审理、宣判等。"},{"i":38,"n":"第三十八条","txt":"参与在线诉讼的相关主体应当遵守数据安全和个人信息保护的相关法律法规，履行数据安全和个人信息保护义务。除人民法院依法公开的以外，任何人不得违法违规披露、传播和使用在线诉讼数据信息。出现上述情形的，人民法院可以根据具体情况，依照法律和司法解释关于数据安全、个人信息保护以及妨害诉讼的规定追究相关单位和人员法律责任，构成犯罪的，依法追究刑事责任。"},{"i":39,"n":"第三十九条","txt":"本规则自2021年8月1日起施行。最高人民法院之前发布的司法解释涉及在线诉讼的规定与本规则不一致的，以本规则为准。"}],"renminfayuanzaixiantiaojieguize":[{"i":1,"n":"第一条","txt":"在立案前或者诉讼过程中依托人民法院调解平台开展在线调解的，适用本规则。"},{"i":2,"n":"第二条","txt":"在线调解包括人民法院、当事人、调解组织或者调解员通过人民法院调解平台开展的在线申请、委派委托、音视频调解、制作调解协议、申请司法确认调解协议、制作调解书等全部或者部分调解活动。"},{"i":3,"n":"第三条","txt":"民事、行政、执行、刑事自诉以及被告人、罪犯未被羁押的刑事附带民事诉讼等法律规定可以调解或者和解的纠纷，可以开展在线调解。"},{"i":4,"n":"第四条","txt":"人民法院采用在线调解方式应当征得当事人同意，并综合考虑案件具体情况、技术条件等因素。"},{"i":5,"n":"第五条","txt":"人民法院审判人员、专职或者兼职调解员、特邀调解组织和特邀调解员以及人民法院邀请的其他单位或者个人，可以开展在线调解。"},{"i":6,"n":"第六条","txt":"人民法院可以邀请符合条件的外国人入驻人民法院调解平台，参与调解当事人一方或者双方为外国人、无国籍人、外国企业或者组织的民商事纠纷。"},{"i":7,"n":"第七条","txt":"人民法院立案人员、审判人员在立案前或者诉讼过程中，认为纠纷适宜在线调解的，可以通过口头、书面、在线等方式充分释明在线调解的优势，告知在线调解的主要形式、权利义务、法律后果和操作方法等，引导当事人优先选择在线调解方式解决纠纷。"},{"i":8,"n":"第八条","txt":"当事人同意在线调解的，应当在人民法院调解平台填写身份信息、纠纷简要情况、有效联系电话以及接收诉讼文书电子送达地址等，并上传电子化起诉申请材料。当事人在电子诉讼平台已经提交过电子化起诉申请材料的，不再重复提交。"},{"i":9,"n":"第九条","txt":"当事人在立案前申请在线调解，属于下列情形之一的，人民法院退回申请并分别予以处理："},{"i":10,"n":"第十条","txt":"当事人一方在立案前同意在线调解的，由人民法院征求其意见后指定调解组织或者调解员。"},{"i":11,"n":"第十一条","txt":"在线调解一般由一名调解员进行，案件重大、疑难复杂或者具有较强专业性的，可以由两名以上调解员调解，并由当事人共同选定其中一人主持调解。无法共同选定的，由人民法院指定一名调解员主持。"},{"i":12,"n":"第十二条","txt":"调解组织或者调解员应当在收到人民法院委派委托调解信息或者当事人在线调解申请后三个工作日内，确认接受人民法院委派委托或者当事人调解申请。纠纷不符合调解组织章程规定的调解范围或者行业领域，明显超出调解员擅长领域或者具有其他不适宜接受情形的，调解组织或者调解员可以写明理由后不予接受。"},{"i":13,"n":"第十三条","txt":"主持或者参与在线调解的人员有下列情形之一，应当在接受调解前或者调解过程中进行披露："},{"i":14,"n":"第十四条","txt":"在线调解过程中，当事人可以申请更换调解组织或者调解员；更换后，当事人仍不同意且拒绝自行选择的，视为当事人拒绝调解。"},{"i":15,"n":"第十五条","txt":"人民法院对当事人一方立案前申请在线调解的，应当征询对方当事人的调解意愿。调解员可以在接受人民法院委派调解之日起三个工作日内协助人民法院通知对方当事人，询问是否同意调解。"},{"i":16,"n":"第十六条","txt":"主持在线调解的人员应当在组织调解前确认当事人参与调解的方式，并按照下列情形作出处理："},{"i":17,"n":"第十七条","txt":"在线调解开始前，主持调解的人员应当通过证件证照在线比对等方式核实当事人和其他参与调解人员的身份，告知虚假调解法律后果。立案前调解的，调解员还应当指导当事人填写《送达地址确认书》等相关材料。"},{"i":18,"n":"第十八条","txt":"在线调解过程中，当事人可以通过语音、文字、视频等形式自主表达意愿，提出纠纷解决方案。除共同确认的无争议事实外，当事人为达成调解协议作出妥协而认可的事实、证据等，不得在诉讼程序中作为对其不利的依据或者证据，但法律另有规定或者当事人均同意的除外。"},{"i":19,"n":"第十九条","txt":"调解员组织当事人就所有或者部分调解请求达成一致意见的，应当在线制作或者上传调解协议，当事人和调解员应当在调解协议上进行电子签章；由调解组织主持达成调解协议的，还应当加盖调解组织电子印章，调解组织没有电子印章的，可以将加盖印章的调解协议上传至人民法院调解平台。"},{"i":20,"n":"第二十条","txt":"各方当事人在立案前达成调解协议的，调解员应当记入调解笔录并按诉讼外调解结案，引导当事人自动履行。依照法律和司法解释规定可以申请司法确认调解协议的，当事人可以在线提出申请，人民法院经审查符合法律规定的，裁定调解协议有效。"},{"i":21,"n":"第二十一条","txt":"经在线调解达不成调解协议，调解组织或者调解员应当记录调解基本情况、调解不成的原因、导致其他当事人诉讼成本增加的行为以及需要向人民法院提示的其他情况。人民法院按照下列情形作出处理："},{"i":22,"n":"第二十二条","txt":"调解员在线调解过程中，同步形成电子笔录，并确认无争议事实。经当事人双方明确表示同意的，可以以调解录音录像代替电子笔录，但无争议事实应当以书面形式确认。"},{"i":23,"n":"第二十三条","txt":"人民法院在审查司法确认申请或者出具调解书过程中，发现当事人可能采取恶意串通、伪造证据、捏造事实、虚构法律关系等手段实施虚假调解行为，侵害他人合法权益的，可以要求当事人提供相关证据。当事人不提供相关证据的，人民法院不予确认调解协议效力或者出具调解书。"},{"i":24,"n":"第二十四条","txt":"立案前在线调解期限为三十日。各方当事人同意延长的，不受此限。立案后在线调解，适用普通程序的调解期限为十五日，适用简易程序的调解期限为七日，各方当事人同意延长的，不受此限。立案后延长的调解期限不计入审理期限。"},{"i":25,"n":"第二十五条","txt":"有下列情形之一的，在线调解程序终结："},{"i":26,"n":"第二十六条","txt":"立案前调解需要鉴定评估的，人民法院工作人员、调解组织或者调解员可以告知当事人诉前委托鉴定程序，指导通过电子诉讼平台或者现场办理等方式提交诉前委托鉴定评估申请，鉴定评估期限不计入调解期限。"},{"i":27,"n":"第二十七条","txt":"各级人民法院负责本级在线调解组织和调解员选任确认、业务培训、资质认证、指导入驻、权限设置、业绩评价等管理工作。上级人民法院选任的在线调解组织和调解员，下级人民法院在征得其同意后可以确认为本院在线调解组织和调解员。"},{"i":28,"n":"第二十八条","txt":"人民法院可以建立婚姻家庭、劳动争议、道路交通、金融消费、证券期货、知识产权、海事海商、国际商事和涉港澳台侨纠纷等专业行业特邀调解名册，按照不同专业邀请具备相关专业能力的组织和人员加入。"},{"i":29,"n":"第二十九条","txt":"在线调解组织和调解员在调解过程中，存在下列行为之一的，当事人可以向作出邀请的人民法院投诉："},{"i":30,"n":"第三十条","txt":"本规则自2022年1月1日起施行。最高人民法院以前发布的司法解释与本规则不一致的，以本规则为准。"}],"zuigaorenminjianchayuanguanyujianchagongzuozhongju331793":[],"zuigaorenminjianchayuanguanyushiyongxingfafenzeguiffac0a":[],"zuigaorenminfayuanguowuyuanzongjiaoshiwujuguanyusicb3a40":[],"zuigaorenminfayuangonganbuguanyuhaishifayuanshenpac460db":[],"zuigaorenminfayuanzuigaorenminjianchayuangonganbulf86dea":[],"zuigaorenminfayuanzuigaorenminjianchayuangonganbug2a3e8f":[],"zuigaorenminfayuanzuigaorenminjianchayuangonganbugb198fe":[],"zuigaorenminfayuanzuigaorenminjianchayuangonganbuy92c073":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubuz96f126":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyubuz65e4b5":[],"zuigaorenminfayuanzuigaorenminjianchayuanguanyuxiuc07ee6":[{"i":1,"n":"第一条","txt":"复制他人信用卡、将他人信用卡信息资料写入磁条介质、芯片或者以其他方法伪造信用卡一张以上的，应当认定为刑法第一百七十七条第一款第四项规定的“伪造信用卡”，以伪造金融票证罪定罪处罚。"},{"i":2,"n":"第二条","txt":"明知是伪造的空白信用卡而持有、运输十张以上不满一百张的，应当认定为刑法第一百七十七条之一第一款第一项规定的“数量较大”；非法持有他人信用卡五张以上不满五十张的，应当认定为刑法第一百七十七条之一第一款第二项规定的“数量较大”。"},{"i":3,"n":"第三条","txt":"窃取、收买、非法提供他人信用卡信息资料，足以伪造可进行交易的信用卡，或者足以使他人以信用卡持卡人名义进行交易，涉及信用卡一张以上不满五张的，依照刑法第一百七十七条之一第二款的规定，以窃取、收买、非法提供信用卡信息罪定罪处罚；涉及信用卡五张以上的，应当认定为刑法第一百七十七条之一第一款规定的“数量巨大”。"},{"i":4,"n":"第四条","txt":"为信用卡申请人制作、提供虚假的财产状况、收入、职务等资信证明材料，涉及伪造、变造、买卖国家机关公文、证件、印章，或者涉及伪造公司、企业、事业单位、人民团体印章，应当追究刑事责任的，依照刑法第二百八十条的规定，分别以伪造、变造、买卖国家机关公文、证件、印章罪和伪造公司、企业、事业单位、人民团体印章罪定罪处罚。"},{"i":5,"n":"第五条","txt":"使用伪造的信用卡、以虚假的身份证明骗领的信用卡、作废的信用卡或者冒用他人信用卡，进行信用卡诈骗活动，数额在五千元以上不满五万元的，应当认定为刑法第一百九十六条规定的“数额较大”；数额在五万元以上不满五十万元的，应当认定为刑法第一百九十六条规定的“数额巨大”；数额在五十万元以上的，应当认定为刑法第一百九十六条规定的“数额特别巨大”。"},{"i":6,"n":"第六条","txt":"持卡人以非法占有为目的，超过规定限额或者规定期限透支，经发卡银行两次有效催收后超过三个月仍不归还的，应当认定为刑法第一百九十六条规定的“恶意透支”。"},{"i":7,"n":"第七条","txt":"催收同时符合下列条件的，应当认定为本解释第六条规定的“有效催收”："},{"i":8,"n":"第八条","txt":"恶意透支，数额在五万元以上不满五十万元的，应当认定为刑法第一百九十六条规定的“数额较大”；数额在五十万元以上不满五百万元的，应当认定为刑法第一百九十六条规定的“数额巨大”；数额在五百万元以上的，应当认定为刑法第一百九十六条规定的“数额特别巨大”。"},{"i":9,"n":"第九条","txt":"恶意透支的数额，是指公安机关刑事立案时尚未归还的实际透支的本金数额，不包括利息、复利、滞纳金、手续费等发卡银行收取的费用。归还或者支付的数额，应当认定为归还实际透支的本金。"},{"i":10,"n":"第十条","txt":"恶意透支数额较大，在提起公诉前全部归还或者具有其他情节轻微情形的，可以不起诉；在一审判决前全部归还或者具有其他情节轻微情形的，可以免予刑事处罚。但是，曾因信用卡诈骗受过两次以上处罚的除外。"},{"i":11,"n":"第十一条","txt":"发卡银行违规以信用卡透支形式变相发放贷款，持卡人未按规定归还的，不适用刑法第一百九十六条‘恶意透支’的规定。构成其他犯罪的，以其他犯罪论处。"},{"i":12,"n":"第十二条","txt":"违反国家规定，使用销售点终端机具（POS机）等方法，以虚构交易、虚开价格、现金退货等方式向信用卡持卡人直接支付现金，情节严重的，应当依据刑法第二百二十五条的规定，以非法经营罪定罪处罚。"},{"i":13,"n":"第十三条","txt":"单位实施本解释规定的行为，适用本解释规定的相应自然人犯罪的定罪量刑标准。"}],"zuigaorenminfayuanzuigaorenminjianchayuanguanyufeie756eb":[],"zuigaorenminfayuanyuyifeizhide1999niandiyiqianfabu128197":[],"zuigaorenminfayuanyuyifeizhide2000niandiyiqianfabu37d414":[],"zuigaorenminfayuanyuyifeizhide2000niandiyiqianfabua68fa6":[],"zuigaorenminfayuanyuyifeizhide2000niandiyiqianfabua3921d":[],"zuigaorenminfayuanguanyubufuzhengfuhuofangdichanxia85804":[],"zuigaorenminfayuanguanyuxiugairenminfayuanfatinggue569ce":[{"i":1,"n":"第一条","txt":"为了维护法庭安全和秩序，保障庭审活动正常进行，保障诉讼参与人依法行使诉讼权利，方便公众旁听，促进司法公正，彰显司法权威，根据《中华人民共和国人民法院组织法》《中华人民共和国刑事诉讼法》《中华人民共和国民事诉讼法》《中华人民共和国行政诉讼法》等有关法律规定，制定本规则。"},{"i":2,"n":"第二条","txt":"法庭是人民法院代表国家依法审判各类案件的专门场所。"},{"i":3,"n":"第三条","txt":"法庭分设审判活动区和旁听区，两区以栏杆等进行隔离。"},{"i":4,"n":"第四条","txt":"刑事法庭可以配置同步视频作证室，供依法应当保护或其他确有保护必要的证人、鉴定人、被害人在庭审作证时使用。"},{"i":5,"n":"第五条","txt":"法庭应当设置残疾人无障碍设施；根据需要配备合议庭合议室，检察人员、律师及其他诉讼参与人休息室，被告人羁押室等附属场所。"},{"i":6,"n":"第六条","txt":"进入法庭的人员应当出示有效身份证件，并接受人身及携带物品的安全检查。"},{"i":7,"n":"第七条","txt":"除经人民法院许可，需要在法庭上出示的证据外，下列物品不得携带进入法庭："},{"i":8,"n":"第八条","txt":"人民法院应当通过官方网站、电子显示屏、公告栏等向公众公开各法庭的编号、具体位置以及旁听席位数量等信息。"},{"i":9,"n":"第九条","txt":"公开的庭审活动，公民可以旁听。"},{"i":10,"n":"第十条","txt":"人民法院应当对庭审活动进行全程录像或录音。"},{"i":11,"n":"第十一条","txt":"依法公开进行的庭审活动，具有下列情形之一的，人民法院可以通过电视、互联网或其他公共媒体进行图文、音频、视频直播或录播："},{"i":12,"n":"第十二条","txt":"出庭履行职务的人员，按照职业着装规定着装。但是，具有下列情形之一的，着正装："},{"i":13,"n":"第十三条","txt":"刑事在押被告人或上诉人出庭受审时，着正装或便装，不着监管机构的识别服。"},{"i":14,"n":"第十四条","txt":"庭审活动开始前，书记员应当宣布本规则第十七条规定的法庭纪律。"},{"i":15,"n":"第十五条","txt":"审判人员进入法庭以及审判长或独任审判员宣告判决、裁定、决定时，全体人员应当起立。"},{"i":16,"n":"第十六条","txt":"人民法院开庭审判案件应当严格按照法律规定的诉讼程序进行。"},{"i":17,"n":"第十七条","txt":"全体人员在庭审活动中应当服从审判长或独任审判员的指挥，尊重司法礼仪，遵守法庭纪律，不得实施下列行为："},{"i":18,"n":"第十八条","txt":"审判长或独任审判员主持庭审活动时，依照规定使用法槌。"},{"i":19,"n":"第十九条","txt":"审判长或独任审判员对违反法庭纪律的人员应当予以警告；对不听警告的，予以训诫；对训诫无效的，责令其退出法庭；对拒不退出法庭的，指令司法警察将其强行带出法庭。"},{"i":20,"n":"第二十条","txt":"行为人实施下列行为之一，危及法庭安全或扰乱法庭秩序的，根据相关法律规定，予以罚款、拘留；构成犯罪的，依法追究其刑事责任："},{"i":21,"n":"第二十一条","txt":"司法警察依照审判长或独任审判员的指令维持法庭秩序。"},{"i":22,"n":"第二十二条","txt":"人民检察院认为审判人员违反本规则的，可以在庭审活动结束后向人民法院提出处理建议。"},{"i":23,"n":"第二十三条","txt":"检察人员违反本规则的，人民法院可以向人民检察院通报情况并提出处理建议。"},{"i":24,"n":"第二十四条","txt":"律师违反本规则的，人民法院可以向司法行政机关及律师协会通报情况并提出处理建议。"},{"i":25,"n":"第二十五条","txt":"人民法院进行案件听证、国家赔偿案件质证、网络视频远程审理以及在法院以外的场所巡回审判等，参照适用本规则。"},{"i":26,"n":"第二十六条","txt":"外国人、无国籍人旁听庭审活动，外国媒体记者报道庭审活动，应当遵守本规则。"},{"i":27,"n":"第二十七条","txt":"本规则自2016年5月1日起施行；最高人民法院此前发布的司法解释及规范性文件与本规则不一致的，以本规则为准。"}],"zuigaorenminfayuanguanyuneidiyuaomentebiexingzheng643e9c":[{"i":1,"n":"第一条","txt":"内地与澳门特别行政区民商事案件（在内地包括劳动争议案件，在澳门特别行政区包括劳动民事案件）判决的相互认可和执行，适用本安排。"},{"i":2,"n":"第二条","txt":"本安排所称“判决”，在内地包括：判决、裁定、决定、调解书、支付令；在澳门特别行政区包括：裁判、判决、确认和解的裁定、法官的决定或者批示。"},{"i":3,"n":"第三条","txt":"一方法院作出的具有给付内容的生效判决，当事人可以向对方有管辖权的法院申请认可和执行。"},{"i":4,"n":"第四条","txt":"内地有权受理认可和执行判决申请的法院为被申请人住所地、经常居住地或者财产所在地的中级人民法院。两个或者两个以上中级人民法院均有管辖权的，申请人应当选择向其中一个中级人民法院提出申请。"},{"i":5,"n":"第五条","txt":"被申请人在内地和澳门特别行政区均有可供执行财产的，申请人可以向一地法院提出执行申请。"},{"i":6,"n":"第六条","txt":"请求认可和执行判决的申请书，应当载明下列事项："},{"i":7,"n":"第七条","txt":"申请书应当附生效判决书副本，或者经作出生效判决的法院盖章的证明书，同时应当附作出生效判决的法院或者有权限机构出具的证明下列事项的相关文件："},{"i":8,"n":"第八条","txt":"申请书应当用中文制作。所附司法文书及其相关文件未用中文制作的，应当提供中文译本。其中法院判决书未用中文制作的，应当提供由法院出具的中文译本。"},{"i":9,"n":"第九条","txt":"法院收到申请人请求认可和执行判决的申请后，应当将申请书送达被申请人。"},{"i":10,"n":"第十条","txt":"被请求方法院应当尽快审查认可和执行的请求，并作出裁定。"},{"i":11,"n":"第十一条","txt":"被请求方法院经审查核实存在下列情形之一的，裁定不予认可："},{"i":12,"n":"第十二条","txt":"法院就认可和执行判决的请求作出裁定后，应当及时送达。"},{"i":13,"n":"第十三条","txt":"经裁定予以认可的判决，与被请求方法院的判决具有同等效力。判决有给付内容的，当事人可以向该方有管辖权的法院申请执行。"},{"i":14,"n":"第十四条","txt":"被请求方法院不能对判决所确认的所有请求予以认可和执行时，可以认可和执行其中的部分请求。"},{"i":15,"n":"第十五条","txt":"法院受理认可和执行判决的申请之前或者之后，可以按照被请求方法律关于财产保全的规定，根据申请人的申请，对被申请人的财产采取保全措施。"},{"i":16,"n":"第十六条","txt":"在被请求方法院受理认可和执行判决的申请期间，或者判决已获认可和执行，当事人再行提起相同诉讼的，被请求方法院不予受理。"},{"i":17,"n":"第十七条","txt":"对于根据本安排第十一条第（一）、（四）、（六）项不予认可的判决，申请人不得再行提起认可和执行的申请。但根据被请求方的法律，被请求方法院有管辖权的，当事人可以就相同案件事实向当地法院另行提起诉讼。"},{"i":18,"n":"第十八条","txt":"为适用本安排，由一方有权限公共机构（包括公证员）作成或者公证的文书正本、副本及译本，免除任何认证手续而可以在对方使用。"},{"i":19,"n":"第十九条","txt":"申请人依据本安排申请认可和执行判决，应当根据被请求方法律规定，交纳诉讼费用、执行费用。"},{"i":20,"n":"第二十条","txt":"对民商事判决的认可和执行，除本安排有规定的以外，适用被请求方的法律规定。"},{"i":21,"n":"第二十一条","txt":"本安排生效前提出的认可和执行请求，不适用本安排。"},{"i":22,"n":"第二十二条","txt":"本安排在执行过程中遇有问题或者需要修改，应当由最高人民法院与澳门特别行政区协商解决。"},{"i":23,"n":"第二十三条","txt":"为执行本安排，最高人民法院和澳门特别行政区终审法院应当相互提供相关法律资料。"},{"i":24,"n":"第二十四条","txt":"本安排自2006年4月1日起生效。"}],"zuigaorenminfayuanguanyuneidiyuaomentebiexingzhenga2d27d":[{"i":1,"n":"第一条","txt":"本安排所称“保全”，在内地包括财产保全、证据保全、行为保全；在澳门特别行政区包括为确保受威胁的权利得以实现而采取的保存或者预行措施。"},{"i":2,"n":"第二条","txt":"按照澳门特别行政区仲裁法规向澳门特别行政区仲裁机构提起民商事仲裁程序的当事人，在仲裁裁决作出前，可以参照《中华人民共和国民事诉讼法》《中华人民共和国仲裁法》以及相关司法解释的规定，向被申请人住所地、财产所在地或者证据所在地的内地中级人民法院申请保全。被申请人住所地、财产所在地或者证据所在地在不同人民法院辖区的，应当选择向其中一个人民法院提出申请，不得分别向两个或者两个以上人民法院提出申请。"},{"i":3,"n":"第三条","txt":"向内地人民法院申请保全的，应当提交下列材料："},{"i":4,"n":"第四条","txt":"向内地人民法院提交的保全申请书应当载明下列事项："},{"i":5,"n":"第五条","txt":"依据《中华人民共和国仲裁法》向内地仲裁机构提起民商事仲裁程序的当事人，在仲裁裁决作出前，可以根据澳门特别行政区法律规定，向澳门特别行政区初级法院申请保全。"},{"i":6,"n":"第六条","txt":"向澳门特别行政区法院申请保全的，须附同下列资料："},{"i":7,"n":"第七条","txt":"被请求方法院应当尽快审查当事人的保全申请，可以按照被请求方法律规定要求申请人提供担保。"},{"i":8,"n":"第八条","txt":"当事人对被请求方法院的裁定不服的，按被请求方相关法律规定处理。"},{"i":9,"n":"第九条","txt":"当事人申请保全的，应当根据被请求方法律的规定交纳费用。"},{"i":10,"n":"第十条","txt":"本安排不减损内地和澳门特别行政区的仲裁机构、仲裁庭、仲裁员、当事人依据对方法律享有的权利。"},{"i":11,"n":"第十一条","txt":"本安排在执行过程中遇有问题或者需要修改的，由最高人民法院和澳门特别行政区协商解决。"},{"i":12,"n":"第十二条","txt":"本安排自2022年3月25日起施行。"}],"zuigaorenminfayuanguanyuneidiyuaomentebiexingzheng5034cf":[{"i":1,"n":"第一条","txt":"内地人民法院与澳门特别行政区法院就民商事案件（在内地包括劳动争议案件，在澳门特别行政区包括民事劳工案件）相互委托送达司法文书和调取证据，均适用本安排。"},{"i":2,"n":"第二条","txt":"双方相互委托送达司法文书和调取证据，通过各高级人民法院和澳门特别行政区终审法院进行。最高人民法院与澳门特别行政区终审法院可以直接相互委托送达和调取证据。"},{"i":3,"n":"第三条","txt":"双方相互委托送达司法文书和调取证据，通过内地与澳门司法协助网络平台以电子方式转递；不能通过司法协助网络平台以电子方式转递的，采用邮寄方式。"},{"i":4,"n":"第四条","txt":"各高级人民法院和澳门特别行政区终审法院收到对方法院的委托书后，应当立即将委托书及所附司法文书和相关文件转送根据其本辖区法律规定有权完成该受托事项的法院。"},{"i":5,"n":"第五条","txt":"委托书应当以中文文本提出。所附司法文书及其他相关文件没有中文文本的，应当提供中文译本。"},{"i":6,"n":"第六条","txt":"委托方法院应当在合理的期限内提出委托请求，以保证受委托方法院收到委托书后，及时完成受托事项。"},{"i":7,"n":"第七条","txt":"受委托方法院应当根据本辖区法律规定执行受托事项。委托方法院请求按照特殊方式执行委托事项的，受委托方法院认为不违反本辖区的法律规定的，可以按照特殊方式执行。"},{"i":8,"n":"第八条","txt":"委托方法院无须支付受委托方法院在送达司法文书、调取证据时发生的费用、税项。但受委托方法院根据其本辖区法律规定，有权在调取证据时，要求委托方法院预付鉴定人、证人、翻译人员的费用，以及因采用委托方法院在委托书中请求以特殊方式送达司法文书、调取证据所产生的费用。"},{"i":9,"n":"第九条","txt":"受委托方法院收到委托书后，不得以其本辖区法律规定对委托方法院审理的该民商事案件享有专属管辖权或者不承认对该请求事项提起诉讼的权利为由，不予执行受托事项。"},{"i":10,"n":"第十条","txt":"委托方法院请求送达司法文书，须出具盖有其印章或者法官签名的委托书，并在委托书中说明委托机关的名称、受送达人的姓名或者名称、详细地址以及案件性质。委托方法院请求按特殊方式送达或者有特别注意的事项的，应当在委托书中注明。"},{"i":11,"n":"第十一条","txt":"采取邮寄方式委托的，委托书及所附司法文书和其他相关文件一式两份，受送达人为两人以上的，每人一式两份。"},{"i":12,"n":"第十二条","txt":"完成司法文书送达事项后，内地人民法院应当出具送达回证；澳门特别行政区法院应当出具送达证明书。出具的送达回证和送达证明书，应当注明送达的方法、地点和日期以及司法文书接收人的身份，并加盖法院印章。"},{"i":13,"n":"第十三条","txt":"不论委托方法院司法文书中确定的出庭日期或者期限是否已过，受委托方法院均应当送达。"},{"i":14,"n":"第十四条","txt":"受委托方法院对委托方法院委托送达的司法文书和所附相关文件的内容和后果不负法律责任。"},{"i":15,"n":"第十五条","txt":"本安排中的司法文书在内地包括：起诉状副本、上诉状副本、反诉状副本、答辩状副本、授权委托书、传票、判决书、调解书、裁定书、支付令、决定书、通知书、证明书、送达回证以及其他司法文书和所附相关文件；在澳门特别行政区包括：起诉状复本、答辩状复本、反诉状复本、上诉状复本、陈述书、申辩书、声明异议书、反驳书、申请书、撤诉书、认诺书、和解书、财产目录、财产分割表、和解建议书、债权人协议书、传唤书、通知书、法官批示、命令状、法庭许可令状、判决书、合议庭裁判书、送达证明书以及其他司法文书和所附相关文件。"},{"i":16,"n":"第十六条","txt":"委托方法院请求调取的证据只能是用于与诉讼有关的证据。"},{"i":17,"n":"第十七条","txt":"双方相互委托代为调取证据的委托书应当写明："},{"i":18,"n":"第十八条","txt":"代为调取证据的范围包括：代为询问当事人、证人和鉴定人，代为进行鉴定和司法勘验，调取其他与诉讼有关的证据。"},{"i":19,"n":"第十九条","txt":"委托方法院提出要求的，受委托方法院应当将取证的时间、地点通知委托方法院，以便有关当事人及其诉讼代理人能够出席。"},{"i":20,"n":"第二十条","txt":"受委托方法院在执行委托调取证据时，根据委托方法院的请求，可以允许委托方法院派司法人员出席。必要时，经受委托方允许，委托方法院的司法人员可以向证人、鉴定人等发问。"},{"i":21,"n":"第二十一条","txt":"受委托方法院完成委托调取证据的事项后，应当向委托方法院书面说明。"},{"i":22,"n":"第二十二条","txt":"受委托方法院可以根据委托方法院的请求，并经证人、鉴定人同意，协助安排其辖区的证人、鉴定人到对方辖区出庭作证。"},{"i":23,"n":"第二十三条","txt":"受委托方法院可以根据委托方法院的请求，并经证人、鉴定人同意，协助安排其辖区的证人、鉴定人通过视频、音频作证。"},{"i":24,"n":"第二十四条","txt":"受委托方法院取证时，被调查的当事人、证人、鉴定人等的代理人可以出席。"},{"i":25,"n":"第二十五条","txt":"受委托方法院可以根据委托方法院的请求代为查询并提供本辖区的有关法律。"},{"i":26,"n":"第二十六条","txt":"本安排在执行过程中遇有问题的，由最高人民法院与澳门特别行政区终审法院协商解决。"},{"i":27,"n":"第二十七条","txt":"本安排自2001年9月15日起生效。本安排的修改文本自2020年3月1日起生效。"}],"zuigaorenminfayuanguanyuneidiyuaomentebiexingzheng9e8871":[{"i":1,"n":"第一条","txt":"内地人民法院认可和执行澳门特别行政区仲裁机构及仲裁员按照澳门特别行政区仲裁法规在澳门作出的民商事仲裁裁决，澳门特别行政区法院认可和执行内地仲裁机构依据《中华人民共和国仲裁法》在内地作出的民商事仲裁裁决，适用本安排。"},{"i":2,"n":"第二条","txt":"在内地或者澳门特别行政区作出的仲裁裁决，一方当事人不履行的，另一方当事人可以向被申请人住所地、经常居住地或者财产所在地的有关法院申请认可和执行。"},{"i":3,"n":"第三条","txt":"被申请人的住所地、经常居住地或者财产所在地分别在内地和澳门特别行政区的，申请人可以向一地法院提出认可和执行申请，也可以分别向两地法院提出申请。"},{"i":4,"n":"第四条","txt":"申请人向有关法院申请认可和执行仲裁裁决的，应当提交以下文件或者经公证的副本："},{"i":5,"n":"第五条","txt":"申请书应当包括下列内容："},{"i":6,"n":"第六条","txt":"申请人向有关法院申请认可和执行内地或者澳门特别行政区仲裁裁决的期限，依据认可和执行地的法律确定。"},{"i":7,"n":"第七条","txt":"对申请认可和执行的仲裁裁决，被申请人提出证据证明有下列情形之一的，经审查核实，有关法院可以裁定不予认可："},{"i":8,"n":"第八条","txt":"申请人依据本安排申请认可和执行仲裁裁决的，应当根据执行地法律的规定，交纳诉讼费用。"},{"i":9,"n":"第九条","txt":"一方当事人向一地法院申请执行仲裁裁决，另一方当事人向另一地法院申请撤销该仲裁裁决，被执行人申请中止执行且提供充分担保的，执行法院应当中止执行。"},{"i":10,"n":"第十条","txt":"受理申请的法院应当尽快审查认可和执行的请求，并作出裁定。"},{"i":11,"n":"第十一条","txt":"法院在受理认可和执行仲裁裁决申请之前或者之后，可以依当事人的申请，按照法院地法律规定，对被申请人的财产采取保全措施。"},{"i":12,"n":"第十二条","txt":"由一方有权限公共机构（包括公证员）作成的文书正本或者经公证的文书副本及译本，在适用本安排时，可以免除认证手续在对方使用。"},{"i":13,"n":"第十三条","txt":"本安排实施前，当事人提出的认可和执行仲裁裁决的请求，不适用本安排。"},{"i":14,"n":"第十四条","txt":"为执行本安排，最高人民法院和澳门特别行政区终审法院应当相互提供相关法律资料。"},{"i":15,"n":"第十五条","txt":"本安排在执行过程中遇有问题或者需要修改的，由最高人民法院和澳门特别行政区协商解决。"},{"i":16,"n":"第十六条","txt":"本安排自2008年1月1日起实施。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz31a370":[{"i":1,"n":"第一条","txt":"本安排所称“保全”，在内地包括财产保全、证据保全、行为保全；在香港特别行政区包括强制令以及其他临时措施，以在争议得以裁决之前维持现状或者恢复原状、采取行动防止目前或者即将对仲裁程序发生的危害或者损害，或者不采取可能造成这种危害或者损害的行动、保全资产或者保全对解决争议可能具有相关性和重要性的证据。"},{"i":2,"n":"第二条","txt":"本安排所称“香港仲裁程序”，应当以香港特别行政区为仲裁地，并且由以下机构或者常设办事处管理："},{"i":3,"n":"第三条","txt":"香港仲裁程序的当事人，在仲裁裁决作出前，可以参照《中华人民共和国民事诉讼法》《中华人民共和国仲裁法》以及相关司法解释的规定，向被申请人住所地、财产所在地或者证据所在地的内地中级人民法院申请保全。被申请人住所地、财产所在地或者证据所在地在不同人民法院辖区的，应当选择向其中一个人民法院提出申请，不得分别向两个或者两个以上人民法院提出申请。"},{"i":4,"n":"第四条","txt":"向内地人民法院申请保全的，应当提交下列材料："},{"i":5,"n":"第五条","txt":"保全申请书应当载明下列事项："},{"i":6,"n":"第六条","txt":"内地仲裁机构管理的仲裁程序的当事人，在仲裁裁决作出前，可以依据香港特别行政区《仲裁条例》《高等法院条例》，向香港特别行政区高等法院申请保全。"},{"i":7,"n":"第七条","txt":"向香港特别行政区法院申请保全的，应当依据香港特别行政区相关法律规定，提交申请、支持申请的誓章、附同的证物、论点纲要以及法庭命令的草拟本，并应当载明下列事项："},{"i":8,"n":"第八条","txt":"被请求方法院应当尽快审查当事人的保全申请。内地人民法院可以要求申请人提供担保等，香港特别行政区法院可以要求申请人作出承诺、就费用提供保证等。"},{"i":9,"n":"第九条","txt":"当事人对被请求方法院的裁定或者命令等不服的，按被请求方相关法律规定处理。"},{"i":10,"n":"第十条","txt":"当事人申请保全的，应当依据被请求方有关诉讼收费的法律和规定交纳费用。"},{"i":11,"n":"第十一条","txt":"本安排不减损内地和香港特别行政区的仲裁机构、仲裁庭、当事人依据对方法律享有的权利。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz7ce9ab":[{"i":1,"n":"第一条","txt":"内地人民法院与香港特别行政区法院就民商事案件相互委托提取证据，适用本安排。"},{"i":2,"n":"第二条","txt":"双方相互委托提取证据，须通过各自指定的联络机关进行。其中，内地指定各高级人民法院为联络机关；香港特别行政区指定香港特别行政区政府政务司司长办公室辖下行政署为联络机关。"},{"i":3,"n":"第三条","txt":"受委托方的联络机关收到对方的委托书后，应当及时将委托书及所附相关材料转送相关法院或者其他机关办理，或者自行办理。"},{"i":4,"n":"第四条","txt":"委托书及所附相关材料应当以中文文本提出。没有中文文本的，应当提供中文译本。"},{"i":5,"n":"第五条","txt":"委托方获得的证据材料只能用于委托书所述的相关诉讼。"},{"i":6,"n":"第六条","txt":"内地人民法院根据本安排委托香港特别行政区法院提取证据的，请求协助的范围包括："},{"i":7,"n":"第七条","txt":"受委托方应当根据本辖区法律规定安排取证。"},{"i":8,"n":"第八条","txt":"内地人民法院委托香港特别行政区法院提取证据，应当提供加盖最高人民法院或者高级人民法院印章的委托书。香港特别行政区法院委托内地人民法院提取证据，应当提供加盖香港特别行政区高等法院印章的委托书。"},{"i":9,"n":"第九条","txt":"受委托方因执行受托事项产生的一般性开支，由受委托方承担。"},{"i":10,"n":"第十条","txt":"受委托方应当尽量自收到委托书之日起六个月内完成受托事项。受委托方完成受托事项后，应当及时书面回复委托方。"},{"i":11,"n":"第十一条","txt":"本安排在执行过程中遇有问题，或者本安排需要修改，应当通过最高人民法院与香港特别行政区政府协商解决。"},{"i":12,"n":"第十二条","txt":"本安排在内地由最高人民法院发布司法解释和香港特别行政区完成有关内部程序后，由双方公布生效日期。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz147e90":[],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz8ae999":[{"i":1,"n":"第一条","txt":"当事人向香港特别行政区法院申请认可和执行内地人民法院就婚姻家庭民事案件作出的生效判决，或者向内地人民法院申请认可和执行香港特别行政区法院就婚姻家庭民事案件作出的生效判决的，适用本安排。"},{"i":2,"n":"第二条","txt":"本安排所称生效判决："},{"i":3,"n":"第三条","txt":"本安排所称婚姻家庭民事案件："},{"i":4,"n":"第四条","txt":"申请认可和执行本安排规定的判决："},{"i":5,"n":"第五条","txt":"申请认可和执行本安排第一条第一款规定的判决的，应当提交下列材料："},{"i":6,"n":"第六条","txt":"申请书应当载明下列事项："},{"i":7,"n":"第七条","txt":"申请认可和执行判决的期间、程序和方式，应当依据被请求方法律的规定。"},{"i":8,"n":"第八条","txt":"法院应当尽快审查认可和执行的请求，并作出裁定或者命令。"},{"i":9,"n":"第九条","txt":"申请认可和执行的判决，被申请人提供证据证明有下列情形之一的，法院审查核实后，不予认可和执行："},{"i":10,"n":"第十条","txt":"被请求方法院不能对判决的全部判项予以认可和执行时，可以认可和执行其中的部分判项。"},{"i":11,"n":"第十一条","txt":"对于香港特别行政区法院作出的判决，一方当事人已经提出上诉，内地人民法院审查核实后，可以中止认可和执行程序。经上诉，维持全部或者部分原判决的，恢复认可和执行程序；完全改变原判决的，终止认可和执行程序。"},{"i":12,"n":"第十二条","txt":"在本安排下，内地人民法院作出的有关财产归一方所有的判项，在香港特别行政区将被视为命令一方向另一方转让该财产。"},{"i":13,"n":"第十三条","txt":"被申请人在内地和香港特别行政区均有可供执行财产的，申请人可以分别向两地法院申请执行。"},{"i":14,"n":"第十四条","txt":"内地与香港特别行政区法院相互认可和执行的财产给付范围，包括判决确定的给付财产和相应的利息、迟延履行金、诉讼费，不包括税收、罚款。"},{"i":15,"n":"第十五条","txt":"被请求方法院就认可和执行的申请作出裁定或者命令后，当事人不服的，在内地可以于裁定送达之日起十日内向上一级人民法院申请复议，在香港特别行政区可以依据其法律规定提出上诉。"},{"i":16,"n":"第十六条","txt":"在审理婚姻家庭民事案件期间，当事人申请认可和执行另一地法院就同一争议作出的判决的，应当受理。受理后，有关诉讼应当中止，待就认可和执行的申请作出裁定或者命令后，再视情终止或者恢复诉讼。"},{"i":17,"n":"第十七条","txt":"审查认可和执行判决申请期间，当事人就同一争议提起诉讼的，不予受理；已经受理的，驳回起诉。"},{"i":18,"n":"第十八条","txt":"被请求方法院在受理认可和执行判决的申请之前或者之后，可以依据其法律规定采取保全或者强制措施。"},{"i":19,"n":"第十九条","txt":"申请认可和执行判决的，应当依据被请求方有关诉讼收费的法律和规定交纳费用。"},{"i":20,"n":"第二十条","txt":"内地与香港特别行政区法院自本安排生效之日起作出的判决，适用本安排。"},{"i":21,"n":"第二十一条","txt":"本安排在执行过程中遇有问题或者需要修改的，由最高人民法院和香港特别行政区政府协商解决。"},{"i":22,"n":"第二十二条","txt":"本安排自2022年2月15日起施行。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingzfd0f3f":[{"i":1,"n":"第一条","txt":"内地与香港特别行政区法院民商事案件生效判决的相互认可和执行，适用本安排。"},{"i":2,"n":"第二条","txt":"本安排所称“民商事案件”是指依据内地和香港特别行政区法律均属于民商事性质的案件，不包括香港特别行政区法院审理的司法复核案件以及其他因行使行政权力直接引发的案件。"},{"i":3,"n":"第三条","txt":"本安排暂不适用于就下列民商事案件作出的判决："},{"i":4,"n":"第四条","txt":"本安排所称“判决”，在内地包括判决、裁定、调解书、支付令，不包括保全裁定；在香港特别行政区包括判决、命令、判令、讼费评定证明书，不包括禁诉令、临时济助命令。"},{"i":5,"n":"第五条","txt":"本安排所称“知识产权”是指《与贸易有关的知识产权协定》第一条第二款规定的知识产权，以及《中华人民共和国民法典》第一百二十三条第二款第七项、香港《植物品种保护条例》规定的权利人就植物新品种享有的知识产权。"},{"i":6,"n":"第六条","txt":"本安排所称“住所地”，当事人为自然人的，是指户籍所在地或者永久性居民身份所在地、经常居住地；当事人为法人或者其他组织的，是指注册地或者登记地、主要办事机构所在地、主要营业地、主要管理地。"},{"i":7,"n":"第七条","txt":"申请认可和执行本安排规定的判决："},{"i":8,"n":"第八条","txt":"申请认可和执行本安排规定的判决，应当提交下列材料："},{"i":9,"n":"第九条","txt":"申请书应当载明下列事项："},{"i":10,"n":"第十条","txt":"申请认可和执行判决的期间、程序和方式，应当依据被请求方法律的规定。"},{"i":11,"n":"第十一条","txt":"符合下列情形之一，且依据被请求方法律有关诉讼不属于被请求方法院专属管辖的，被请求方法院应当认定原审法院具有管辖权："},{"i":12,"n":"第十二条","txt":"申请认可和执行的判决，被申请人提供证据证明有下列情形之一的，被请求方法院审查核实后，应当不予认可和执行："},{"i":13,"n":"第十三条","txt":"申请认可和执行的判决，被申请人提供证据证明在原审法院进行的诉讼违反了当事人就同一争议订立的有效仲裁协议或者管辖协议的，被请求方法院审查核实后，可以不予认可和执行。"},{"i":14,"n":"第十四条","txt":"被请求方法院不能仅因判决的先决问题不属于本安排适用范围，而拒绝认可和执行该判决。"},{"i":15,"n":"第十五条","txt":"对于原审法院就知识产权有效性、是否成立或者存在作出的判项，不予认可和执行，但基于该判项作出的有关责任承担的判项符合本安排规定的，应当认可和执行。"},{"i":16,"n":"第十六条","txt":"相互认可和执行的判决内容包括金钱判项、非金钱判项。"},{"i":17,"n":"第十七条","txt":"知识产权侵权纠纷案件以及内地人民法院审理的《中华人民共和国反不正当竞争法》第六条规定的不正当竞争纠纷民事案件、香港特别行政区法院审理的假冒纠纷案件，内地与香港特别行政区法院相互认可和执行判决的，限于根据原审法院地发生的侵权行为所确定的金钱判项，包括惩罚性赔偿部分。"},{"i":18,"n":"第十八条","txt":"内地与香港特别行政区法院相互认可和执行的财产给付范围，包括判决确定的给付财产和相应的利息、诉讼费、迟延履行金、迟延履行利息，不包括税收、罚款。"},{"i":19,"n":"第十九条","txt":"被请求方法院不能认可和执行判决全部判项的，可以认可和执行其中的部分判项。"},{"i":20,"n":"第二十条","txt":"对于香港特别行政区法院作出的判决，一方当事人已经提出上诉，内地人民法院审查核实后，中止认可和执行程序。经上诉，维持全部或者部分原判决的，恢复认可和执行程序；完全改变原判决的，终止认可和执行程序。"},{"i":21,"n":"第二十一条","txt":"被申请人在内地和香港特别行政区均有可供执行财产的，申请人可以分别向两地法院申请执行。"},{"i":22,"n":"第二十二条","txt":"在审理民商事案件期间，当事人申请认可和执行另一地法院就同一争议作出的判决的，应当受理。受理后，有关诉讼应当中止，待就认可和执行的申请作出裁定或者命令后，再视情终止或者恢复诉讼。"},{"i":23,"n":"第二十三条","txt":"审查认可和执行判决申请期间，当事人就同一争议提起诉讼的，不予受理；已经受理的，驳回起诉。"},{"i":24,"n":"第二十四条","txt":"申请认可和执行判决的，被请求方法院在受理申请之前或者之后，可以依据被请求方法律规定采取保全或者强制措施。"},{"i":25,"n":"第二十五条","txt":"法院应当尽快审查认可和执行的申请，并作出裁定或者命令。"},{"i":26,"n":"第二十六条","txt":"被请求方法院就认可和执行的申请作出裁定或者命令后，当事人不服的，在内地可以于裁定送达之日起十日内向上一级人民法院申请复议，在香港特别行政区可以依据其法律规定提出上诉。"},{"i":27,"n":"第二十七条","txt":"申请认可和执行判决的，应当依据被请求方有关诉讼收费的法律和规定交纳费用。"},{"i":28,"n":"第二十八条","txt":"本安排签署后，最高人民法院和香港特别行政区政府经协商，可以就第三条所列案件判决的认可和执行以及第四条所涉保全、临时济助的协助问题签署补充文件。"},{"i":29,"n":"第二十九条","txt":"内地与香港特别行政区法院自本安排生效之日起作出的判决，适用本安排。"},{"i":30,"n":"第三十条","txt":"本安排生效之日，《最高人民法院关于内地与香港特别行政区法院相互认可和执行当事人协议管辖的民商事案件判决的安排》同时废止。"},{"i":31,"n":"第三十一条","txt":"本安排生效后，《最高人民法院关于内地与香港特别行政区法院相互认可和执行婚姻家庭民事案件判决的安排》继续施行。"},{"i":32,"n":"第三十二条","txt":"本安排自2024年1月29日起施行。"}],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingzb8ab8a":[],"zuigaorenminfayuanguanyuneidiyuxianggangtebiexingz11d242":[],"zuigaorenminfayuanguanyujunduilituixiuganbutengtui49e972":[],"zuigaorenminfayuanguanyuxiangjuzhuzaiwaiguodewoguo2de0a3":[],"zuigaorenminfayuanguanyuchulisheqiangshebaoshensua7b9ad1":[],"zuigaorenminfayuanguanyuduidangshirenyiweishengxina1acce":[],"zuigaorenminfayuanguanyuduiwenhuadagemingqianpanch34637e":[],"zuigaorenminfayuanguanyuduidixiareshuideshuxingjis90fabb":[],"zuigaorenminfayuanguanyuduilinyexingzhengjiguanyiff1f0a4":[],"zuigaorenminfayuanguanyuduihedaocaishayingfoujiaon1cc196":[],"zuigaorenminfayuanguanyuyingdangyunxujianchayuanpa29559e":[],"zuigaorenminfayuanguanyufeizhi1979nianzhi1989nianj4f74ae":[],"zuigaorenminfayuanguanyufeizhi1993niandiyiqianfabu44e8ad":[],"zuigaorenminfayuanguanyudangshirenduixingzhengjiguf35095":[],"zuigaorenminfayuanguanyuzhixingwoguojiarudechengred81024":[{"i":1,"n":"第四条","txt":"一、声请承认及执行之一造，为取得前条所称之承认及执行，应于声请时提具："},{"i":2,"n":"第五条","txt":"一、裁决唯有受裁决援用之一造向声请承认及执行地之主管机关提具证据证明有下列情形之一时，始得依该造之请求，拒予承认及执行："},{"i":3,"n":"第一百六十九条","txt":"申请执行的期限，双方或者一方当事人是个人的为一年；双方是企业事业单位、机关、团体的为六个月。"},{"i":4,"n":"第二百零四条","txt":"中华人民共和国人民法院对外国法院委托执行的已经确定的判决、裁决，应当根据中华人民共和国缔结或者参加的国际条约，或者按照互惠原则进行审查，认为不违反中华人民共和国法律的基本准则或者我国国家、社会利益的，裁定承认其效力，并且依照本法规定的程序执行。否则，应当退回外国法院。"}],"zuigaorenminfayuanguanyuzhixinglingshitiaoyuezhong0f9317":[],"zuigaorenminfayuanguanyufayuandongjiecaichandehumi22631e":[],"zuigaorenminfayuanguanyuzhongzhidifangfayuanyuguow98d173":[],"zuigaorenminfayuanguanyutongyixingshisixinganjianh67ca11":[],"zuigaorenminfayuanguanyurenzhenxuexixuanchuanguancb146a4":[],"zuigaorenminfayuanguanyuzhuanfasifabuguanyuzaiweit5240bc":[],"zuigaorenminfayuanbangongtingguanyuzhuanfaguowuyua9f6ce1":[],"zuigaorenminfayuanyinfaguanyurenminfayuanzhixinggub5c735":[],"zuigaorenminfayuanyinfaguanyuguifanrenminfayuanzai098620":[{"i":1,"n":"第一条","txt":"各级人民法院、专门人民法院对本院或者上级人民法院对下级人民法院作出的终审裁判，经复查认为符合再审立案条件的，应当决定或裁定再审。"},{"i":2,"n":"第二条","txt":"地方各级人民法院、专门人民法院负责下列案件的再审立案："},{"i":3,"n":"第三条","txt":"最高人民法院负责下列案件的再审立案："},{"i":4,"n":"第四条","txt":"上级人民法院对下级人民法院作出的终审裁判，认为确有必要的，可以直接立案复查，经复查认为符合再审立案条件的，可以决定或裁定再审。"},{"i":5,"n":"第五条","txt":"再审申请人或申诉人向人民法院申请再审或申诉，应当提交以下材料："},{"i":6,"n":"第六条","txt":"申请再审或申诉一般由终审人民法院审查处理。"},{"i":7,"n":"第七条","txt":"对终审刑事裁判的申诉，具备下列情形之一的，人民法院应当决定再审："},{"i":8,"n":"第八条","txt":"对终审民事裁判、调解的再审申请，具备下列情形之一的，人民法院应当裁定再审："},{"i":9,"n":"第九条","txt":"对终审行政裁判的申诉，具备下列情形之一的，人民法院应当裁定再审："},{"i":10,"n":"第十条","txt":"人民法院对刑事案件的申诉人在刑罚执行完毕后两年内提出的申诉，应当受理；超过两年提出申诉，具有下列情形之一的，应当受理："},{"i":11,"n":"第十一条","txt":"人民法院对刑事附带民事案件中仅就民事部分提出申诉的，一般不予再审立案。但有证据证明民事部分明显失当且原审被告人有赔偿能力的除外。"},{"i":12,"n":"第十二条","txt":"人民法院对民事、行政案件的再审申请人或申诉人超过两年提出再审申请或申诉的，不予受理。"},{"i":13,"n":"第十三条","txt":"人民法院对不符合法定主体资格的再审申请或申诉，不予受理。"},{"i":14,"n":"第十四条","txt":"人民法院对下列民事案件的再审申请不予受理："},{"i":15,"n":"第十五条","txt":"上级人民法院对经终审法院的上一级人民法院依照审判监督程序审理后维持原判或者经两级人民法院依照审判监督程序复查均驳回的申请再审或申诉案件，一般不予受理。"},{"i":16,"n":"第十六条","txt":"最高人民法院再审裁判或者复查驳回的案件，再审申请人或申诉人仍不服提出再审申请或申诉的，不予受理。"},{"i":17,"n":"第十七条","txt":"本意见自2002年11月1日起施行。以前有关再审立案的规定与本意见不一致的，按本意见执行。"}],"zuigaorenminfayuanduidangshirenduirenminfayuanqian86faef":[],"zuigaorenminfayuanyanjiushiguanyushangjirenminjian3a5851":[],"zuigaorenminfayuanyanjiushiguanyuyincuopanzaifuxind2dd54":[],"zuigaorenminfayuanyanjiushiguanyuruhelijieshenpand31b515":[],"zuigaorenminfayuanyanjiushiguanyuduizaishengaipanqe27bb1":[],"zuigaorenminfayuanyanjiushiguanyuduizaibangjialesu2f26ea":[],"zuigaorenminfayuanyanjiushiguanyushenfuqiangzhapiaef3a46":[],"zuigaorenminfayuanyanjiushiguanyudaoyongtarenchang71b96e":[],"zuigaorenminfayuanxingzhengshenpantingguanyuhuheha4b7a8a":[],"zuigaorenminfayuanxingzhengshenpantingguanyuxiangz24aaa6":[],"zuigaorenminfayuanxingzhengshenpantingguanyugongan2cd896":[],"zuigaorenminfayuanxingzhengshenpantingguanyuchushocb2679":[],"zuigaorenminfayuanxingzhengshenpantingguanyuruhesh9b880a":[],"zuigaorenminfayuanxingzhengshenpantingguanyuduijia662c73":[],"zuigaorenminfayuanxingzhengshenpantingguanyuzhengsd436ed":[]};
